/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180301-18","meetingId":"h30-cm03","date":"2018年3月1日","dateIso":"2018-03-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、請願読み上げられましたけれども、全くそのとおりだなと考えています。今、競技場などいろいろ建設が行われておりますけれども、この建設工事従事者の方々が今汗水垂らしてつくっているという状況ですが、請願提出者からいただいた資料を見たのですが、鉄道工事の例が載っていました。あわせて区のほうも、組織委員会のほうにぜひ働きかけていただきたいと思いますけれども、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"開会式・閉会式につきましては、今ご説明しましたように組織委員会のほうで全員が参画をするということを目標に現在検討を進めているです。そうした組織委員会の動きをとりあえず区としては見守っていきたいと考えています。","id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"２点、あります。１点は、本当に言葉の細かい確認で、改めて東京２０２０大会の正式名称がどうだったのかなという正式名称の問題ですけれども、東京オリンピック・パラリンピック競技大会組織委員会のほうは、東京オリンピック・パラリンピックというふうになっているということで、この第３２回オリンピック競技大会が正式名称ということなのでしょうか。この請願の趣旨の中にどの辺まで含まれているのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、略称につきまして、例えば東京２０２０オリンピック、東京２０２０パラリンピックということで、オリンピックとパラリンピックを分けた言い方をすることも可能だというような説明を受けているところです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派にも請願者の方にお越しをいただいて、お話をうかがいました。その点について把握をされているのか。それで、我々も例えばいろいろ今要望を東京都にもしていますけれども、では東京都にすることと、組織委員会にすることをどうやって分けて、その話をしていったらいいのか。我々の要望をどうやったら実らせていったらいいのかということを、どうお考えなのかを教えていただきたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"開会式、閉会式につきましては、初めにご説明させていただきましたとおり、組織委員会のほうが役割分担として全てを担うというふうに東京都から確認しています。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうではなくて一体となって行うのか。役割については組織委員会なのか東京都なのか。今ご説明いただいた開会式・閉会式は、それは組織委員会ですよというのは、今わかったけれども、ほかのそういうイベント的なものも含めて、我々も要望しているものもあるのですが、それをどういうふうに我々としてこれから具体的に実現させていくにはどうしたらいいのか、あわせてお話を伺えればありがたいなと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、直接的な要望ということになりますと、やはり組織委員会にダイレクトに要望する方法は、大きな意義があるかとは思います。今、この場で私のほうで、東京都がいいのか組織委員会がいいのかというような、なかなか即答はできないところではあります。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派としても、議論をした中で署名をさせていただきました。これは委員長にお願いでありますけれども、毎年委員会として東京都に要望しており、この前も要望しに行ったりとかいろいろなことをしていますよね。やはりもう一度この委員会で期間を定めていただいて、要望を取りまとめて出していくという必要があるのだろうなと思っています。それから、要望はこの請願の項目１つだけではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点お伺いしたいのですが、ここオリンピック競技大会（２０２０／東京）ということで、多分パラリンピックも入っているニュアンスなのかなと思う中で、先ほど頭に冠がついたものは全て組織委員会がやるという理事者のご答弁だったのですが、これが例えば、要は開会式とか閉会式等のセレモニーの「等」の中には、おそらく品川区内で行われるビーチバレーであったり、ホッケーであったりというのも含めた中で。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした意味で、こうした団体のほうで、区の例えばしながわサポーターという制度もありますので、そういった形で一緒にイベントに応援していただくというような、参画していただくような形は十分あり得ることかと考えております。","id":"exchange-006"},{"speaker":"いながわ委員","kind":"提案","question":"それもオリンピックにかかわっているわけであります。一言あればお願いします。この請願については、趣旨は重々理解しているので、これも結論めいたことを先ほど石田秀男委員がおっしゃっていましたけれども、しっかりこの委員会として、これも含むさまざまな観点で要望書を提出するということを、私ども会派からもご提案をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"会派の考え方や方向性につきましては石田秀男委員が述べましたので、１点だけ確認というか教えていただきたいことがあります。こういう開会式や閉会式についても組織委員会のほうで柔軟にできることなのか、それともすごく厳しいルールがあるのか。その感覚だけ教えていただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"お話のありました聖火ランナーにつきましても、まさにこれから検討していくというようなことは聞いております。日本の中でどういったコースを走るのかということ。それからどういった方たちに走っていただくのかというようなこと。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"品川区に１点伺いたいのですけれども、この請願にも書かれているとおり、建設労働者の開会式などの参加について、今後の東京都、まだスケジュールなども決まっていないということで、見守っていきたいという話ですけれども、決まっていなければなおのこと、品川区でも今ホッケーの会場を建設するわけですが、品川区としてもしっかり建設労働者が開会式に参加ができて。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"労働組合の方だけに限定することなく、区としてはそういった思いで見ていきたいと考えています。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出すでお願いをしたいと考えています。それで先ほども言いましたように、この請願については趣旨採択で、意見書は提出をしないという扱いでお願いをできればと考えています。先ほど言いましたように、全体の中で、この委員会の中で要望書を出していく中でこの願意も入れていくということで我々は考えたいと考えていますので、結論を出す、趣旨採択、これに対する意見書は出さない。これでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"態度は結論を出すで、うちも趣旨採択ということで、今、石田秀男委員がご発言されていましたけれども、先ほど理事者のほうからの説明があって、組織委員会の考え方ということで参画の部分については、皆がかかわっていると感じられるようにするとありまして、この請願自体は労働従事者ということで、その方だけに限った形での請願という形になっていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、意見書を出したいと思います。先ほど、委員会として要望を出そうじゃないかというご意見そのものには理解をするわけですけれども、また、先ほど来からの議論を聞いていましても、全体の方向として、ここに書かれていることの中身については理解があるということですが、請願者の思いにしっかり答えていきたいということで、意見書を出したいという結論になりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そして全ての方に光の当たるようにするような形で、組織委員会または必要であれば東京都に対して要望書をこの委員会からしっかりと何項目か挙げて、提出する必要性もあるのかなと思いますので、趣旨採択ということで、お願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークとしても、先ほど質問した結果、多分この請願代表者の方も、パラリンピックの大会の開会式じゃ嫌だとおっしゃっているわけでもないでしょうし、それから建設工事従事者の方たちにスポットを当てたいという気持ちもそのとおりだと思いますので、その趣旨には賛成をいたしますけれども、１点、文言上ではありますが、やはりパラリンピックも含めて全体として捉えたいなというのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、採択を主張させていただきましたけれども、皆さんのご意見をうかがう中で、趣旨は理解できるし、委員会としても要望をしていきたい方向が確認されましたので、趣旨採択に変更したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"願第４号 第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","agenda":"願第４号 第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、１点区のほうにお伺いしたいのですが、区としても、この競技会場の所在地というところで、区としても組織委員会のほうに、組織委員会もやるとは言っておりますけれども、改めて品川区のほうからもしっかり調達コードを守るよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"改善要求の働きかけに協力させるというようなことを、最終的には十分に取り組んでいないと認められるような場合には契約を解除するというところまで踏み込んで書かれてあります。そうしたところで組織委員会のほうが対応していただけるというふうに考えているところです。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先日も搬入ですか。もう既に２月末、３月頭にはホッケー場、品川区内で行われる競技の競技場の建設が今始まっていると思いますが、やはり品川区としても、そういった調達コードの遵守がされているかどうかというのを再確認する意味、啓発も含めて、しっかりとかかわれるかどうかは別にしても、やはり他人事ではないというか、そういう思いでしっかりとやっていただきたいのですが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区内で工事をされるということですので、区としてもしっかり見守りたいとは思いますが、そういったことを監督するような立場に区はございませんので、そういった意味できちんと情報収集しながら、組織委員会とはいろいろな関係でかかわっておりますので。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひそこはやっていただきたいと思います。２年前にリオの視察に行ったときも、もう如実にそこはあらわれていたのですが、やはり競技場の周りはまだ工事最中、オリンピックがもう始まっているにもかかわらず、まだ工事をしていたという現状であります。日本の粋を集めれば、あと２年後の開催までには全てが間に合うと思うのですが、もうお尻は決まっている工事であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"我が会派は、この請願者の方ともお会いをさせていただいて、いろいろな話を、議論もさせていただきました。署名はなぜしなかったのかというところがあると思います。もう１つ言えば保険の問題とか、今、建設業界の中で、若い人たちにいかに担っていただくかという。ある国では、今変な話年間４万人ぐらいを育てて送り込もうという話があったり、じゃあ日本人の労働者がどういう形で今いるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"公明党も会派で請願を見て議論させていただきました。今、石田秀男委員からもありましたけれども、ここに、鍵括弧の中には長時間労働の禁止等とあるのですが、趣旨の中には、その長時間労働に関することを主におかれて記載があるような部分もあることも含め、それだけではない部分もありますし、全体を立てて見ていかないといけないのかなというところで、継続にさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"共産党としては結論を出すということと、採択をして、意見書を出すべきだと思います。長時間労働のこと、公契約のこと、若い人の担い手など、推移を見ながら全体をさらに深めていきたいということは理解を示しますけれども、請願の内容にしっかりと答えていきたいので、結論を出すと。採択して、意見書を出すということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すということで、紹介議員にもなっているということで、採択を主張させていただきたいと思います。さらに言うのであれば、やはり今後のさまざまな契約案件の中で工期の設定もしっかりと行っていかなければ最終的には長時間労働につながっていくのではないかなと考えていますので、今回の請願については、我が会派としては、採択を主張させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"文化芸術振興協議会の準備会のご報告をいただきましたが、今回この３１団体が挙げられておりますが、これは今後増えていくということもお話をいただきましたので、また拡大をしていただきたいと思うのですが、これは団体のみが登録をされるのか、例えば品川区内にお住まいの個人の方、どういう方がいらっしゃるかわかりませんけれども、芸術にかかわっている方とか、また、芸能人の方とか。","respondent":"鈴木文化観光課長","answer":"協議会に参加する団体または個人の芸術関係の方ですが、基本的に今現時点では、団体に限定する予定はございません。ただ、今準備会の段階では、一定程度各分野の方から広く意見をお伺いしたいと。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"「しながわ文化プログラム」に参加しようというところから、お伺いしたいのですが、この文化プログラム自体が、多分オリンピック・パラリンピックがあるから、この文化プログラムという概念というか、こういうのが出てきて、品川区としてやるというのは重々理解しているのですが、このパンフレットの内容が、「しながわ文化プログラム」のロゴマークがお使いいただけますとか。","respondent":"小川オリンピック・パラリンピック準備課長、鈴木文化観光課長","answer":"さまざまいろいろな今後もご意見を伺いながら、デザインにつきましては、意見を伺いながら検討してまいりたいと思います。ただ、この皆さんの中で共通しているのが、自分たちの活動事業はしっかりとしているけれども、ほかの団体と連携することで新しいことや何かもっと大きなことができるのではないかということが皆さん共通の認識でございました。","id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問・要望","question":"「しながわ文化プログラムに参加しよう！文化芸術振興協議会に関しては、これからまた人数も増えるかと思います。団体がうちはこうなのだという方もいらっしゃるかもしれませんが、そこはぜひファシリテーターというのですか。仕切る方がしっかりとそういうことがないように、本当に連携だけはとっていただいて、東京２０２０大会後も品川の文化芸術の振興に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"１点だけ文化芸術振興協議会準備会に関連してなのですけれども、こういう形でいろいろ進んでくると、いろいろな形でお金がかかってくると思うのです。そうすると、予算書をよく見ていないのでわからないですが、基金が２年ぐらい前にできたと思うのですが、これを、例えば今後の予定の中のキックオフイベントだとか、いろいろなところでそういったものを活用していくのか。もしわかれば教えてください。","respondent":"柏原企画調整課長","answer":"そういった趣旨を鑑みながら、基金というのも、当然ここにかかわるような形で使いようというのが出てくると思いますので、実際どういう形でそれを充てていくかというのは、いろいろ事業の中身を検討しながらというのもありますけれども。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えていただきたいのですが、まず準備会のことです。なぜそのようなことを言うかというと、今、児童遊園になっているのを屋外広告物条例で今度、都市公園にしようとか、いろいろな考え方がある。それからハードの部分があるではないですか。それを文化芸術では、ハードのが必ず出てくるではないですか。そういう方々といかに連携をしたりもしているのかというのをまず教えていただきたい。","respondent":"鈴木文化観光課長","answer":"１点目の準備会での参加いただいた団体の皆さんからのご意見の中で特徴的なものですが、１つは、そもそも区のほうで協議会を構想、検討しているときに、区民芸術祭でかかわっていただいている団体から、同様の趣旨で、広く多くの団体に声をかけて。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、この前ちょっと質問でも出たけれども、４月の７日、８日にエクストリーム大会が広島市民球場跡地で開かれる。これは多分２桁万人の動員規模のレベルでやろうとしているわけです。これは区民芸術祭で、そういうのも含めてやっていくのはいいのだけれども、そういう多くの人を集客できるようなイベントというものも考えていくべきではないのかなと思うのだけれども、ここら辺の考えはどうお考えですか。","respondent":"鈴木文化観光課長","answer":"文化観光課で観光の事業もやっておりますので、文化芸術のイベント、大規模なものを実施しながら、それを観光の資源として活用する。シティプロモーションによる魅力発信というところも想定をして、考えているところです。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"この文化プログラム。品川のというところで、参考までなのですが、オリンピックが決定して以降だけではなく以前も含めてで結構なのですが、まずファッションショーありますよね。シルバーの方のファッションショーとかそういうものがあるのですけれども、いわゆるファッションショーが行われたことがあるかどうか、わかる範疇で教えてください。","respondent":"鈴木文化観光課長","answer":"あちらの学生の方がやはりいろいろデザインした服をファッションショーでやられたり、最近は文化のほうでお世話になっている喜多能楽堂が杉野学園とコラボをして、学生が能楽堂の衣装を研究した上で新しいデザインをして。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"予算特別委員会とかでもまた改めて伺おうかなと思っているのですが、当然区からというよりも、これはどちらかというと文化プログラムで、それぞれの地域のいろいろな方、団体とかが、各地域で行われているよというのが趣旨だと思うのですけれども、そういった例えば文化と一口に言ってもいろいろな文化があるなというところで、せっかくやるならば、この文化プログラムの条件としては。","respondent":"鈴木文化観光課長","answer":"ご質問いただきました商店街や地域の商業関係の事業所との連携、協力体制ですが、実は来年度以降、やはり総合的な文化芸術、それからスポーツ、そういうもののイベントを実施したいと思っておりまして、そのときに、やはり近隣の商店街や町会、地域の団体にもお声かけをして。","id":"exchange-030"}]},{"id":"topic-04","title":"ＩＢＳＡブラインドサッカーワールドグランプリ２０１８","agenda":"ＩＢＳＡブラインドサッカーワールドグランプリ２０１８","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"これは基本的にはこちらの主催者の問題だろうと、ＩＢＳＡの問題だろうと思っていたのですが、品川区が特別共催ということなので、わかる範囲で教えていただきたいのですが、ブラインドサッカーということなので、視覚障害者への情報提供のことです。全体的な考え方と、このことに関しての２つをお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この本大会におきましても、当然そういったことをしていくことと聞いてあります。","id":"exchange-031"},{"speaker":"吉田委員","kind":"提案","question":"そういう配慮がされていたということでよかったと思います。その後、私たち、生活者ネットワークとしても、きちんとした提案をしていないのが悪いのですけれども、その辺のことも今後オリンピック・パラリンピック準備課のほうから、いろいろなところに働きかけていただけると、有効な情報提供につながるかなと思いますので、その辺ぜひご検討いただければと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問","question":"場所の提供をしているから、非常に日本全国を見ても、品川区は非常にブラインドサッカーに対して造詣が深い部分だと思うので、会場などにＳＰコードやら様々な取り組みをされているというのは重々理解はできるのですが、ではこれがオリンピック・パラリンピックのときに、青海の会場になると思うのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"組織委員会の取り組みですが、東京都ですとかいろいろなところが出している、これからご紹介しますものについても、ＳＰコードがついているものとついていないものがあるのですけれども、組織委員会がどういうふうにするかはわかりませんが、パラリンピックについては。","id":"exchange-033"}]},{"id":"topic-05","title":"その他を先に議題に供します。 まず(1)の議会閉会中継続審査調査事項","agenda":"その他を先に議題に供します。 まず(1)の議会閉会中継続審査調査事項","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。ボランティアの件なのですけれども、どういう広報をしてどれぐらい知らせていくのか。こういうことは、ただ情報が来たのはいいのだけれども、その辺のところというのもわかりやすくやりたい方に手が届くように、ただこの１枚が東京都から来てもよくわからないし、どういうふうになっていくと我々は思っておけばいいのですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"都市ボランティアにつきましては、来年の２月から５月を面接として予定していると。研修につきましては、２０１９年の来年の１０月ぐらいから研修をするというようなところまでの情報ですが、私どもが把握しているのは、以上です。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひこういうのは、意地悪で言っているわけではなくて、それは書いてあることを今お聞きしたと。我々も聞かれたときに答えられる。こういう期間というのはインターネットで見るのですか。ボランティアだってやりたいと思っているけれども、みんなインターネットなのですか。こういうのがわからないではないですか。いつ研修があるとかいったら、会社を休まなくてはならないわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"すみません。お考えなのか、お考えではないのであれば、東京都に言われたとおりにただ配置されていくだけなのかとか、その辺について簡単でいいので教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした意味で、まだ都市ボランティアがどういうふうに配置されるかというようなことが明らかに見えてございませんので、そうした組織委員会の動きを見ながら、区としても考えてまいりたいと考えています。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/478583?Template=document&Id=6530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":36972,"voices":128}},{"id":"h30-20180305-3","meetingId":"h30-c-budget","date":"2018年3月5日","dateIso":"2018-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡部委員","kind":"提案","question":"おはようあります。総括質疑まで長い期間続きますが、会派としてもさまざま勉強等積んでまいりましたので、いろいろ教えていただければと思います。提案、要望等もしますので、よろしくお願いします。一番最初なのですけれども、ページ数はないのですが、先週ご報告いただきました福井県坂井市の雪害等に関する状況ということで、区から今回も義援金が出されるというご説明がありました。","respondent":"米田危機管理室長","answer":"これまで坂井市側と被害状況、支援の必要性に関する連絡を所管のほうでとり合ってきたのですけれども、市側の豪雪への緊急対応の状況も落ち着いてきて、費用もかなりかかっているというようなことですので、品川区大規模災害被災地に対する支援に関する条例に基づき。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"考えるところ、人口も増えている、景気もよくなっているなどの要因が挙げられると思うのですが、実際今回もこれだけの増額補正が入った経緯、わかれば教えていただきたいのと、あわせて伺いますけれども、実は補正の裏に隠れている、先ほど冒頭区長からのご挨拶の中にもありましたふるさと納税で、前回の決算特別委員会等の中でもいろいろご説明もいただいておりまして、本年度の流出がおおむね６億円。","respondent":"秋山財政課長、伊東税務課長","answer":"特別区民税の見込みですけれども、このところ人口が増えております。入りの部分ですけれども、平成２９年度としては全くその額には及ばないところではありますが、今現在、１１０万円ほどの入りを見込んでいるところです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"提案","question":"状況を聞かせていただきました。これも平成２９年度は終わってしまうことでありまして、明日から始まります平成３０年度予算のほうのところで、さまざまご提案等も私どもでさせていただきたいとは考えておりますが、２３区さまざまなところでさまざまな取組みがされていると思います。Ｙａｈｏｏ！それと手数料のところはあらあら承知していますが、少し教えてください。","respondent":"伊東税務課長","answer":"クレジット納付の状況ですが、今年の１月からクレジットカードでの納付を開始したところです。速報値ですが、２月末で１６４件のクレジット納付があったということで報告がされております。金額にしては約１,３００万円ほどです。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"件数を聞きましても、１月スタートでこれだけの件数で入ってきているということは、それなりにご利用されている方、希望されている方がいらっしゃるのかなとは感じています。この後、税もそうですし、新年度は国保等でも始まると思いますが、さまざまな形、推移を見ながら、これから先もさまざまな納付方法の研究をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは３６ページ、次世代育成支援対策施設整備交付金、それと４４ページの学校施設トイレ整備支援事業補助金、４２ページのまちづくり緊急推進事業補助金、公衆便所費、公園・児童遊園維持管理費からお伺いしたいと思います。","respondent":"佐藤保育課長","answer":"具体的には平塚シルバーセンター跡のオアシスルームと、第三庁舎内のオアシスムールに関しまして、この間ずっと調整をしてきたのですが、採択がおりましたので、こちらのほうをお願いしています。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"このオアシスルームですけれども、オアシスルームとは、現在品川区に９カ所あり、またこれから２カ所増えていくというところです。その視点からお伺いをさせていただきたいと考えています。そこでまず、平成２８年度の利用実績は大体１万６,０００人と認識をしておりますが、この平成２９年度、現在までの利用状況と、各施設での利用の傾向をお知らせいただきたいと思います。","respondent":"佐藤保育課長","answer":"オアシスルームに関するお尋ねです。１点目の利用状況は、今委員ご指摘のとおり、大体１万６,０００人から１万７,０００人ぐらいの間で、平成２９年度の実績は出るものと考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"新しい施設でありますので、皆さん関心を持って使われていくのかと思うところもありましたけれども、この利用率の低さというところで、何かこれが原因といいますか、理由というのはどのようにお考えでしょうか。このオアシスルームにおいても、それぞれの箇所の特徴も入れながら、このマップを作成していただきたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"委員ご提案のマップの掲載ですが、インターネットシステムは区のホームページから入っていって、オアシスルームのページからまたリンクを張る予定ですので、そのあたりにわかりやすい地図のほうを載せて、より周知に努めてまいりたいと考えております。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"区民の方がわかりやすく確認ができるような体制を整えていただきたいと思います。そして、平成３０年度から、このようにデータ化をされてネットでの予約が開始されます。コールセンターでの細かい対応もしていただけるということです。区にもこのような要望が来ているかと思いますが、この勝島・八潮地域へのオアシスルームの展開というのはどのようにお考えかお聞かせください。","respondent":"佐藤保育課長","answer":"１点目の手続のほうの簡素化なのですが、一応オアシスルーム、一時利用ではありますけれども、命を預かる施設ということで、一度ご利用する施設のほうでの面接というものは省略できないと考えておりますが、一度面接したところ。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"場所を確保することも大変な困難が伴うこともあると思いますけれども、ぜひよろしくお願いいたします。次に、学校施設トイレ整備支援事業補助金について伺います。現在、我が会派からもたびたびトイレの洋式化を要望させていただきまして、大幅に、大きく進んでいることと認識をしております。どのようなスピード感で進んでいくのかということをお知らせいただきたいと思います。","respondent":"品川庶務課長","answer":"洋式のほうが６６、和式が３４という形です。それから今年度、また力を入れて進めていきたいと考えております。一応来年度末の予測としましては７０対３０、７割が達成できるというような見込みで進めている状況です。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"さらに加速をさせていただきたいと思いますが、１００％を目指すことを私ども会派としては要望していますけれども、この洋式化、やるべきところは早く達成していただきたいという思いで、加速していただきたいと思いますので、よろしくお願いいたします。","respondent":"品川庶務課長","answer":"学校でのトイレ教育ですが、基本的にはまず市民科のほうで、１年生のときに和式トイレの使い方というものを市民科の教科書に載せております。その中でトイレ教育について、教員のほうが少し進めてお話をするというようなところでやってあります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"その考え方について少しお伺いをしたいのですが、設置はなかなか難しいところもあると思いますけれども、例えば携帯タイプのもの、そういう「音姫」の携帯タイプがあったりするのです。それを持ち込んでいくとか、また、設置も考えられるということもあるのか、少しお考えをお聞かせいただきたいと思います。","respondent":"品川庶務課長","answer":"それからこのあたりの、例えば温水洗浄便座とか、あと便座除菌クリーナーとか、そういった面も問題としてはあるかと思いますけれども、この辺につきましては国や都の動向、それから他の市区町村の動きなども見て考えていきたいと、このように考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ品川区として寄り添ったご検討をお願いしたいと思います。最後にまちづくり緊急推進事業補助金についてお伺いいたします。洋式化をするときに、このトイレの中に、用を足しているときに赤ちゃんを座らせておく、メーカーによってはベビーキープであったり、ベビーチェアーといっているようですけれども、この設置を必ずするということを前向きにご検討いただきたいと思うのですがいかがでしょうか。","respondent":"溝口公園課長","answer":"現在だれでもトイレの設置を進めておりまして、その中でベビーチェアーというものは設置をしていくところです。そのほかにつきましても、今後整備する中で検討していきたいと考えているものです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"私からは、５９ページの衛生費、保健所の職員給与費に関連して、保健所の役割、カプセルホテルと近隣住民の関係についてお伺いしたいと思います。このカプセルホテルを建設する際、旅館業法に基づいて看板の設置が行われますけれども、この看板設置の趣旨は何か、そして近隣住民への説明をどう指導されているのか、現状をお聞かせください。","respondent":"井浦生活衛生課長","answer":"事前に許可申請予定者に対する指導といたしまして、標識を設置して近隣によく説明をしまして、トラブルのないように進めていただくというようなことを指導しています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"標識を設置して近隣によく説明するようにというご説明でした。具体的に、西大井駅近くの西大井六丁目において、株式会社イノベーターズによる計画で、敷地面積は１１３m2、２階建て、客室は１９室のカプセルホテルの計画です。この計画がカプセルホテルだと電話で説明があったのは、看板設置から約１カ月後のことでありました。このような業者の対応は問題だと思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"許可申請の前の事前相談の段階の手続ですが、さまざまな近隣の声を頂戴しながら、ときには業者に直接連絡をする、そして監督・指導するというような形で、適切に説明をしていただけるように努めているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"区は指導されていると思うのですけれども、今伺ったのは、このような対応は問題ではないのかと思うのですが、その点についてお伺いしたいと思います。西大井六丁目は準工業地域ということですが、現状ではほとんどが住宅地です。ぜひ旅館業法に基づく建物を建てる場合は、最低限説明会の開催をしっかり条例で義務化して、良好な住環境を守るルールづくりが急がれていると思いますが、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"旅館業法につきましては、もともと用途地域の指定というものがございまして、さらに学校施設、教育福祉施設等につきましては、それぞれの関係行政機関に意見を聞きまして、さらに品川区の要綱に基づき。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、今回のこのケースはまず問題ではないのかと。それを解決するために説明会の開催の条例化が必要ではないかと、そう指摘をいたしました。改めて問題ではないのか、条例化をなぜ検討しないのかお伺いしたいと思います。","respondent":"井浦生活衛生課長","answer":"その結果、説明会の開催ということも業者のほうで提案されたということで聞いているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"この現状がある中で、これを問題だと思わないのか、解決のために条例で説明会の開催を義務づけることが必要ではないかと思うのですけれども、はっきりとお答えいただきたいと思います。一体保健所は誰の何を守ろうとしているのか、しっかり良好な住環境を守る責任があると思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"その中で旅館につきましては、もともと説明会というようなところまで制度が構築されているところではございませんので、東京都、特別区等の動向も踏まえながら、私ども、どのようなところに課題があるというようなところは研究しています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"確認","question":"でも、現状ほとんどが住宅街になっているというのが実態です。私も調べてわかったのですけれども、今回の業者は１月１４日に看板を設置して、２日後の１月１６日に建築確認を受けております。そしてこうしたケースが、２０２０年東京オリンピックに向けて、区内各地で広がっているのではないかと私は思うのですけれども、この簡易宿所、カプセルホテルの動きについては、区内ではいかがでしょうか。","respondent":"井浦生活衛生課長","answer":"旅館業営業許可申請に伴う標識の設置につきましては、営業許可申請の１５日前までに標識を設置して、建築確認の表示が国土交通省令に基づいて出されるまで継続して掲示するようにというようなところで、要綱で定めているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"確認","question":"今回のケースは、その要綱が守られていないということなのです。大体標識が出て２日後に建築確認の審査が通っている。住民がその標識にある電話番号に電話をしてもつながらない。つながらないのです。何回電話しても。これでもその要綱が守られているという認識なのか、私はしっかりと条例化して、説明会の開催を義務づけるべきだと思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"いずれにしましても、このような手続面も含めたトラブルの防止という意味では、旅館業営業許可申請と建築確認申請については同時に行うように指導してまいりたいと考えています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"この業者は品川区が電話すると出るのです。住民が電話すると出ないのです。この旅館業法に基づく建物について、最終的に営業許可をおろすのは保健所長と伺いました。これを問題なしとしてしまったら、このように住宅街にカプセルホテルができ、近隣住民とのトラブルになるケースが今後も広がっていくのではないかと私は心配しているのですけれども、その現状認識についても伺いたいと思います。","respondent":"井浦生活衛生課長","answer":"そのような中で、どのように規制していくのか、あるいは区として誘導していくのかというようなところについては、大きな都市計画、まちづくりというようなところの分野もかかわってまいりますので、庁内関係課とも連携いたしまして、また、東京都。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"先ほど来、適切な指導とおっしゃるのですけれども、今回のケースは単に建物の基準が合っているとか、保健衛生とか、そこがクリアしているというだけではなくて、近隣住民との関係がつくられていないのに計画を進めるというのは問題ではないかと、そう伺っているのです。それだけに、改めて説明会の開催を義務化する、そのような規制が必要だと思いますけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"その高さ制限に今回は該当しないというような建築物の許可をめぐる事前の手続ですので、再三申し上げてありますが、品川区の要綱に基づきまして適切に指導していくという中で、生活環境の確保を図ってまいりたいと考えています。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは３７ページの公園・児童遊園整備についてと、５７ページの認証保育所運営費について伺います。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"２月の上旬に認証保育所１園から、近隣で工事が予定されているので、保育に懸念があるということでご相談を受けました。それについて、区と事業者で３回にわたって話し合いを持ったところです。健康遊具につきましては、しながわ中央公園等含めて３４公園に、そういった健康遊具というものが設置されているものです。児童遊園につきましては、児童福祉法に基づく公園というのは２カ所指定されたものがあります。","id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"健康遊具３４公園ということで、あと１点、児童福祉法における児童遊園の設置が２カ所ということで、そのほかの、例えばここに書いてある児童遊園１００カ所ぐらい、ここというのは今名前などは公園になっていなくて、そのまま児童遊園なのか、この辺の名前などという部分の考え方、一方では児童遊園というのは何ですかというような声もあったりする中で、名前について今後どのような。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"近隣での工事の場合、保育施設は工事箇所からの距離にもよりますし、あとはその保育施設が木造か、鉄骨かというような、いろいろ条件によっても変わってくるとは思いますので、一概に近隣で工事があるからといって。そのほかにつきましては、例えば敷地の権原をお借りして公園に設置しているとか、また防災目的で設置している防災広場ですとか。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"公園についてなのですが、今後改修が計画されている中で、もう既にいろいろなところで子どものアイデアを活かした公園等やられているところで、学校とか、児童センターとか、特に子どもが利用する環境がある公園については、ぜひ子どもの声も、聞いていただいているとは思いますが、そういった地域の施設の声を聞きながら取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"１３ページの国保ですけれども、まず、１７億８,０００万円余減額しているのですが、その理由についてお伺いします。それと６３ページの補助１６３号線整備なのですけれども、今区役所のガードの東急線の工事をしていますが、これの進捗状況、完成の見通しについて変更はないのか、そして今回のＪＲの大崎支線というのですか、区役所の大崎寄りの坂下、これの見通しは甘かったのでしょうか。","respondent":"三ッ橋国保医療年金課長、大澤待機児童対策担当課長、黒田人事課長、品川庶務課長、多並道路課長","answer":"こちらが一番大きいです。次に窓口業務に関しましては、引き続き品川区が今までどおり対応してまいります。最終的に２０年後とか、２５年後では、閉園するような園も出てくるかとは思いますが、そのときに利用者に混乱がないように。この寄附元ですが、こちら共済企画センターという有限会社でございまして。以前勤めていた学校のほうでこれを使うというようなことになっております。大井町線ガードにつきましては、当初の予定どおり平成３２年度の道路整備完了ということで、工事を順調に進めているところです。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと補正予算全体について伺いたいのですけれども、今回の一般会計の補正予算なのですが、トータルで約２６億円の増額補正となっているのですけれども、これを見ると当初予算の精度がどうなのかなという思いがでます。そこで今回の補正の増額分で幾らか、減額分で幾らか、またそれぞれ何％に当たるのかお伺いします。","respondent":"秋山財政課長","answer":"パーセントにつきましては、今１,６５５億円の内訳ですので、数％ということだと認識しております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"補正予算の意義といいますか、位置づけです。当初予算の精度はどうなのでしょうか。本当に高いと言えるのでしょうか。これだけ多くの額を基金に積み立てに回せるなら、その品川区の各施策はすばらしいと思うのですけれども、これはもう当初予算から計上してもいいのではないかと私は思うのですが、その辺についてはいかがでしょうか。","respondent":"秋山財政課長","answer":"当初予算の精度というものは高めていかなければいけないとは思っておりますけれども、今回の増額、減額というのはタイムリーに施策を行っていくという面で必要不可欠だったということで、今回補正という形で出させていただいていると認識しております。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"順番は違うのですけれども、最初に７２ページの後地小学校の用地の購入について、校内の一部の国有地を買い取るということで、ほぼうまくいくというふうに、以前お問い合わせをしたとき伺っていたのですが、それが減額になった理由を教えてください。この基金の積立ての考え方を伺いたいと思います。このように書かれた場合、目標額があるなら、普通は当初予算で３０億円計上するのではないでしょうか。","respondent":"品川庶務課長、秋山財政課長","answer":"こういったものを算定はしていたのですけれども、国のほうでの算定と大きくずれてしまったということで、こういった状況になってあります。このような基金のほうに積み立てるというのは、やはり万が一のときに、いざというときのためにですので、そこの部分を当初の予算で見込むというよりも、ある程度財政状況等を踏まえて歳入。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"申しわけありません。１つ言葉を抜かしました。後地小学校の用地購入、次年度、次の予算で計上されていないのだけれども、今後に向けた考え方について伺いたい。そうしたら、私はきちんと当初予算で計上すべきではないかと。今回質問するにあたっても、２０１０年までさかのぼってこの基金積立ての当初予算と最終補正の額を調べたのですけれども、どう考えて予算立てをしているのか、よく読み取れないのです。","respondent":"品川庶務課長、秋山財政課長","answer":"後地小学校の用地、国有地ですけれども、今年度無事購入をできましたので、来年度のほうは予算計上してございません。予算の積み方というか、基金の積み方ですけれども、条例に書いてある予算で定めるということについては、補正予算も予算ですので、今回予算の中で定めているというのが答えといえば答えなのですが、ただ。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"基金なのですけれども、やはりこれ、前のときも補正の考え方というところで伺っているのです。当初予算は１０月の現人数で予算が立てられているということは承知しております。ですから、補正がかかるのは当然かなと思いますが、これ多少でも増減があれば全部この補正予算に記載されるのか、まずそれ１点伺いたいのと、それから５８ページの保健衛生施設費の職員給与費の追加分、増額の要因を教えてください。","respondent":"黒田人事課長","answer":"児童福祉施設費の減額につきましては、こちら１０月１日の現員現給では、当初は職員数自体は、例えば保育園ですと７１２名だったものが、平成２９年１０月１日の現員ですと７２８人ということで、人数は増えているのですけれども、採用しますと初任給という形で。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"保健衛生施設費の職員給与費の追加について、あらかじめお問い合わせしたのとお答えが違ったので、それでいいのかもう１回教えてください。若い方が入れば人件費が少し減って、その分ベテランがやめればということで増減があるというのは理解できるのですけれども、この額でいうと、本当にそれだけでこれだけの差が出るのかなということで、現人数、定数に照らし合わせて今どうなのかも教えてください。","respondent":"黒田人事課長","answer":"保育園につきましては、どうしても女性が多い職場ということで、育休者がおりますと年度途中に職員が欠になるというような状況がございまして、そういった意味では職員が減っているという状況がありますので、今年度、先ほど７２８人と申し上げましたのは。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"申しわけありません。要は言いたいのは、これ増減出ておりますけれども、仕事の忙しさとか、そういう人の問題とかで、人数が足りないのではないかということを感じているものですから、このような質問をさせていただきました。時間がないので次に行きます。ここに計上されている返還分が２０１６年度事業に関するもので、どのように算定されているかについてはあらかじめ伺いました。","respondent":"矢木生活福祉課長","answer":"この点につきましては、そもそもこちらの国庫支出金返還金の性質を申し上げなければいけないと思うのですが、この返還金の性質の主な内容といたしましては、医療扶助と介護扶助、すなわち緊急時のインフルエンザなどの対応ですとか、あと入院ですとか。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"この返還の額については了解をしましたが、やはり生活保護費でいうと、この１０％を限度に減額というのは影響があったかと思うのですけれども、その辺の影響について改めて教えていただけますか。","respondent":"矢木生活福祉課長","answer":"こちらにつきましては、厚生労働省標準世帯というものがございまして、３３歳の父、２９歳の母、４歳の子の世帯で推移を見るものですが、生活扶助基準額の推移ですけれども、平成２４年４月１日では１６万２,１７０円。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"そうすると３年間、ここまで１０％限度の減額ですので、全部が１０％ということではないかと思うのですが、その辺ざっくりでいいので、合計でいうとどれくらいの影響が出ているかということを教えてください。","respondent":"矢木生活福祉課長","answer":"全体の影響というのはなかなか難しいものでございまして、こちら算定はしてございません。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"算定は難しいということなのですけれども、その厚生労働省モデル家庭でいったらどうかだけでも教えてください。","respondent":"矢木生活福祉課長","answer":"失礼いたしました。生活扶助基準額、厚生労働省標準世帯につきましては１万２,０６０円の生活扶助基準額の減額でございました。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり全体の額からの１家族で約１万２,０００円の減額というのは、かなり大きなものかなと思います。今年の１０月から生活扶助費がまた減額となっております。３年間の減額の検証がされないままではないかという識者からの批判もあります。国としての検証を品川区として求めるべきと考えますが、その点についてお考えをお知らせください。","respondent":"矢木生活福祉課長","answer":"品川区での検証ですが、こちら生活保護制度はそもそも第一号法定受託事務ということで、国の事務です。国としての動向調査等は平成３０年度のこちらの基準の見直しの中で、国の生活保護基準部会が扱っているところですので、特に品川区独自の影響を算定する考えはございません。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の事業ではありますけれども、やはりそれがどのように影響してくるかというのは、その区のその後の施策に関連してくるかと思うのです。算定が難しいというのはよく理解できますけれども、それでもやはり何らかの形で検証する、もしくは、やはり国の事業ということであれば、国全体として検証をしながら進めるべきということは、品川区としてもぜひ意見を言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"私からは、３７ページのオアシスルーム運営費、１０６ページ、特定健康診査等事業費についてをお伺いいたします。１点目に、特定健康診査等事業費についてお伺いをいたします。今年度の取組みと来年度の取組み、それぞれどのようなものか確認させてください。","respondent":"三ッ橋国保医療年金課長","answer":"今年度の健診受診率の向上対策ですけれども、この未受診者勧奨の通知、また早得キャンペーンの実施など、医師会と連携をしながら、共同で受診啓発を実施してまいりました。来年度も引き続き、早得キャンペーンなどを継続実施してまいります。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"風邪ですとか、インフルエンザなどが流行する冬の時期ではなくて、年度初めの春からの健診を促すという早得キャンペーンでしょうか、こちら大変よい取組みだと考えております。早得キャンペーンの内容なのですけれども、具体的にはどのようなものでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"この早得キャンペーンの内容ですが、５月から８月までの早期受診者を対象にいたしまして、平成３０年度につきましては品川浴場組合の入浴券をプレゼントいたします。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"キャンペーンの内容、品川浴場組合の入浴券ということで、１月２２日の厚生委員会のほうで、我が会派の鈴木真澄委員より、「公衆浴場のない地域への配慮をお願いしたい」という要望をしていますので、さらなる受診啓発につながるキャンペーンの利用のしやすさについて、今後も工夫のほうをお願いできればと考えています。より参加のしやすい保健指導のあり方について、区はどのようにお考えでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"今回軽度リスク者対策を中心に行いまして、そちらにつきましては、測定会と、またセミナー形式での初回面談の実施をしてまいる予定です。","id":"exchange-041"},{"speaker":"横山委員","kind":"確認","question":"軽度リスク保持者の対策というところ、測定会とセミナー形式での初回面談の実施ということで、忙しくて受診できない方への配慮をされるです。医師会や業者と調整のほう、ぜひよろしくお願いいたします。平成２９年度の決算特別委員会の総括質疑の中でも、データヘルス計画や実施計画の内容を確認させていただきましたが、今年度完成予定のデータヘルス計画と、実施計画の冊子作成状況を教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"今、データヘルス計画、そしてこの実施計画の合冊という考えに基づいて実施しております。冊子は最終確認作業中でございまして、今月末には完成する予定です。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"冊子のほう、完成に向けてよろしくお願いいたします。データヘルス計画で目指す全体目標として、被保険者を含む区民のＱＯＬの向上、健康寿命の延伸が挙げられています。図書館とのコラボヘルスなど、広く区民の皆様に健康情報の発信を実施していただきたいのですが、ＩＣＴを活用した健康情報の発信についてはいかがでしょうか。区のお考えをお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"これからの時代はＩＣＴを活用した発信というものはとても重要な手段だと考えています。今後はデータヘルス計画評価委員会の中でご意見をいただきながら、どのようなことができるのか区として考えてまいります。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"ＩＣＴの活用につきましても前向きに、ほかの委員の方々とご検討いただければと思います。今後の見通しをお伺いいたします。","respondent":"三ッ橋国保医療年金課長","answer":"健康ポイントとして、特定健診の受診者などにポイントを付与する検討をしていると聞いております。国保のデータ活用などを含む詳細につきましては、業者のプロポーザルの提案を踏まえて、今後検討してまいります。","id":"exchange-044"},{"speaker":"横山委員","kind":"提案","question":"２点目に、オアシスルーム運営費についてお伺いいたします。平成２９年決算特別委員会において、我が会派の渡部委員よりインターネット予約システムの導入と、品川区役所第三庁舎内オアシスルームにおける日曜日の開館についての提案がありました。インターネット、電話予約ともに変更点などはありますでしょうか。","respondent":"佐藤保育課長","answer":"次に予約の変更点ですが、電話予約は廃止いたしまして、インターネット予約のみにしたいと考えております。インターネット予約の画面操作がわからない場合は、コールセンター等で予約を代行して、利用率の向上につなげていきたいと考えております。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"これらは子育て中でどのような方でも一度は感じる思いではないでしょうか。区は区内９カ所のオアシスルームに加えて、品川区役所第三庁舎オアシスルーム、平塚シルバーセンター跡にオアシスルームの開設を進めておりますが、在宅子育て家庭が社会からの孤立感を感じることのないように、育児負担の軽減と保護者のリフレッシュを今後もさらに応援していただきたいと要望いたします。","respondent":"佐藤保育課長","answer":"現時点で制度上はご利用いただけませんが、ファミリー・サポート・センターやベビーシッター等をご紹介しております。地域による子育て支援の必要性はより高まっておりますので、保育園、幼稚園等で行っているチャイルドステーション事業等を拡充してまいりたいと考えております。","id":"exchange-046"},{"speaker":"横山委員","kind":"意見","question":"民間企業では子育て中の女性の活躍を応援するお子さん連れが可能なコワーキングスペースですとか、シェアオフィスなどの取組みも年々広がっているかと思うのですけれども、今後のオアシスルームが担っていく役割について、この直近から５年、１０年後あたりくらいなのですが、現在の区のお考えをお聞かせください。","respondent":"佐藤保育課長","answer":"オアシスルームの設置の目的は、在宅子育て世帯の社会参加を図るとともに、育児疲れや保護者の心理的負担の軽減でもあります。今後も委員ご指摘の趣旨を踏まえまして、在宅子育て支援のさまざまな支援について努力してまいります。","id":"exchange-047"},{"speaker":"横山委員","kind":"意見","question":"在宅子育て、ワンオペ育児などという言葉もありますけれども、お母様、お父様が孤立してリフレッシュができないなど育児疲れ等ないように、今後もオアシスルーム、キャンセルを減らしていただき、利用率の向上に努めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"７３ページ、学校改築推進経費更正減額、３９、４５ページの校舎等整備、それから３７、４１ページのすまいるスクール運営費について伺っていきたいと思います。学校改築推進経費更正減額ですが、この更正減額７億３,４１０万円の理由、国の算定とのずれという理由で簡単なご説明はありましたけれども、もう少し詳しくこのあたりを教えてください。","respondent":"品川庶務課長","answer":"当初そういったところも勘案して算定はしたのですけれども、やはり国のほうでの算定評価と大きくずれが出たです。","id":"exchange-049"},{"speaker":"つる委員","kind":"確認","question":"わかりました。購入された土地は３,３００m2で、坪に直すとちょうど１,０００坪ということです。今回更正減額されて実際の購入金額で、単純に１坪当たりの単価を比較すると、３９万円ですか。もともとの算定で出していた、予算で出していたのが１坪１１２万円ぐらいかと思うのですが、これでよろしいかどうかという確認をお願いします。","respondent":"品川庶務課長","answer":"おおむね、こちらも平米単価で出していたもので、坪変換まではしていませんが、計算上そのような差が出ているです。ですので、単価のところで大きく違いが出ると、そこで平米数がかなり大きいので、金額にも大きな差が出るです。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"それが当初が坪でいうと１１２万円ぐらい、１m2でいうと１１８万４,５００円ぐらいですか、１１８万円ぐらいになると思うのですが、たしか。計算したらそうなっていました。その上で全体の話ですが、当初予算で後地小学校のほかは大井第一小学校、延山小学校、それから鮫浜小学校も含めての予算立てがあったかと思いますので、それぞれどこからの土地の購入で、購入金額は幾らなのか教えてください。","respondent":"品川庶務課長","answer":"今回大井第一小学校、それから鮫浜小学校、それと延山小学校と、学校の近隣の用地、これについて空きが出たというか、引っ越し等をされて売却の予定があったというようなところで、学校用地として少しでも広げていくほうが、子どもたちのためにも利用しやすいということで。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"そうすると１億２,９００万円ぐらいですか。１億２,９００万円足す、先ほどの３億９,０００万円だから、５億円ぐらいが合計でという計算で、単純な足し算の話ですけれども、わかりました。それで、これは教育債で起債をされていると思うのですけれども、その起債についてはいつされるのか、そのタイミングを教えてください。","respondent":"秋山財政課長","answer":"こちら教育債で今回補正をしています４億１,５６０万円につきましては、金額が確定して国や都との協議が整った後ということで、これから起債の手続に入る、平成２９年度中に歳入の予定です。","id":"exchange-052"},{"speaker":"つる委員","kind":"意見","question":"私も基本的なところですけれども、このような起債の場合は９割が起債でできて、土地の代金ですね。９割が起債にできて、その後、これについては財調の措置がされるということの流れになると思うのですが、その辺の仕組みについて少し詳しく、改めて教えください。","respondent":"秋山財政課長","answer":"今回起債をする予定が４億１,５６０万円ということで、これについては平成３０年度以降、財調の基準財政需要額の算定に、元利償還金分ですね。毎年返済する元金と利子の分が財調の基準財政需要額の中に算定されるという仕組みになってあります。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"ちょっと単純に引き算したのですけれども、予算ベースですが、そうすると３４１万円ぐらいが後地小学校の年間の借地料になるのかなと思ったのですけれども、まずこの後地小学校の借地料が幾らなのかというところと、それから後地小学校以外の６校、その小学校が借地の部分について何小学校なのかというところと、借地については、先ほど後地小学校については旗ざお状の形状で一部というところでしたが。","respondent":"品川庶務課長","answer":"それから学校、今全校で７校あるのですけれども、山中小学校、延山小学校、大原小学校、宮前小学校、源氏前小学校、旗台小学校、後地小学校、今年度のトータルの借地料としましては、約３,１００万円になります。","id":"exchange-054"},{"speaker":"つる委員","kind":"確認","question":"今お聞きした借地料についてなのですが、ここは３年に一度、２００９年とか２０１０年ぐらいの質疑をちょっと確認させていただいたら、３年に一度見直しをするという中で、当初はその当時２０％一気に上がるというところが、段階的に３％ずつぐらいとなっていましたけれども、その３年に一度のタイミングというのが、この近年だと何年になるのか教えてください。","respondent":"品川庶務課長","answer":"３年に一度のタイミングですと、ちょうど今年度がタイミングとなっております。大体３年間で増加分としましては、先ほどお話あったように３％程度上昇をしているです。","id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"そうすると３年に１回３％アップしているので、２００９年、２０１０年から８年ぐらいですから３回ぐらい、二、三回アップされて都合６％とか９％とか、そのときよりも上がっているという理解をしました。","respondent":"品川庶務課長","answer":"現在のところ、各年において３％から４％ずつ上昇しているようなペースで進めてあります。先ほどもお話ししましたが、来年度末には７０％達成するという見込みでありますので、このペース、他区の状況なども見ながらペースのほうは考えていきたいと考えています。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は５８ページ、５９ページの生活保護費にかかわって、２０１８年の生活保護制度改正について伺いたいと思います。国は生活保護利用世帯の６８％、約７割が食費や日常生活に充てる生活扶助費を最大５％削減する方針を決定しました。２０１３年には最大１０％という過去最大の生活保護基準の引き下げを行っております。これが１０月に行われたら、生活保護受給世帯はどうなってしまうのか。伺います。","respondent":"矢木生活福祉課長","answer":"そして考え方といたしましては、一般低所得者の消費実態などを踏まえながら、その生活水準とバランスのとれた適切な基準に設定するということになってあります。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"今私はこの生活保護を受給されている区民の方を一番近くで見ている自治体として、これが実行されたら、この大改悪がまた実行されたら、どういう生活に追いやられてしまうのかということを伺いましたので、もう一度お願いします。","respondent":"矢木生活福祉課長","answer":"こちら、先ほど申し上げたとおり、一般低所得者の消費実態を踏まえて、その生活水準とバランスをとるという形で国が決めているものです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、そういったことも含めて、さらにこの生活保護受給世帯、最後のセーフティネットと言われている、この生活保護がさらに引き下げられるというのは、本当に厳しい状況に追いやられていくということであると思いますし、また今回は３歳未満のいる家庭、先ほども言いましたけれども、児童養育加算が月５,０００円減らされます。区は、この辺はどのように考えているでしょうか。","respondent":"矢木生活福祉課長","answer":"２点目、生活保護基準の影響を及ぼす範囲ですが、委員ご指摘のとおり、こちらもまたほかの制度に影響を与えないようにということで考えているようですので、そのような形になると考えます。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほども他の委員の質問の中で、検証は区独自ではしていかないということを言われていましたが、やはり区民の生活実態ですから、ぜひそこは把握していっていただきたいと思います。品川区ではどうなのでしょうか。生活保護受給対象となる、今保護を受けていない低所得世帯の把握はされているのでしょうか。そしてまた、捕捉率が低い理由は、区としてはどう考えているか教えてください。","respondent":"矢木生活福祉課長","answer":"生活保護の制度は申請主義でございまして、生活にお困りの方がさまざまなご相談をされるという中で、最低生活費に満たない収入の方につきましては、生活保護の受給を開始するという、そういった制度です。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ各窓口、税金滞納や国保滞納などされている、困窮されているなという状況が見られる方々には、生活福祉課だけでなく、各窓口で生活保護のしおりだけでもいいので、配っていただきたいと思いますし、制度の周知、そしてセーフティネットがあるということを周知していただきたいと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"私からは３４ページ、特別区民税、４０ページ、待機児童解消区市町村支援事業補助金、そして４６ページ、繰越金についてお伺いをいたします。平成２９年度、今回の補正予算の特別区民税についてなのですけれども、９億７,７９０万円となっております。そうした景気や個人の所得が向上したということも考えられるかなと思うのですけれども、そのあたりのご見解をお聞かせください。","respondent":"伊東税務課長","answer":"それと１人当たりの税額ですけれども、こちらに関しても当初見込んでいた額よりも７,０００円ほど増加ということで計算しています。","id":"exchange-062"},{"speaker":"筒井委員","kind":"質問","question":"そうした背景というものについてのご見解をお聞きしたかったのですけれども、そうした景気の動向とか、そういったことも関連しているのかということをお聞きしたいのですが、いかがでしょうか。","respondent":"伊東税務課長","answer":"背景ですけれども、１つには納税義務者が増えたというところがありますが、それともう１点、昨年の状況、労働力調査等々を見ますと、完全失業率も下がっているということと、あとは都内の賃金に関しても０.４％の増というような報告もありますので。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"２年連続でかなり大きな補正なのですけれども、こうした特別区民税の増額というのは予測が難しいものなのでしょうか。特にここをしっかり正確に予測しないと、各施策に影響や、特に人の数でいくと各施設、特に教育施設などにも影響があると思うのですけれども、そうした予測が困難なのはどうしてかということをお聞きしたいのですが、いかがでしょうか。","respondent":"伊東税務課長","answer":"今言ったように１年おくれで収納というか、払っていただくということになりますので、そのときの状況によっては収納率ということにも影響してまいりまして、その辺を全体的に考えていくという中では、非常に困難性はあるのかと思っておるところです。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ところが、参考までに平成２８年度の場合は４億７,０００万円でした。その差が１３億５,０００万円ほどになっているのですけれども、こうした差が出てきた理由というものは何かあるのでしょうか。もちろん品川区も待機児童解消に取り組んでおりますし、東京都がより力強く待機児童解消施策を打ってきたということも関連すると思うのですけれども、そのあたりの区のご見解はいかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"当初予算では、子ども・子育て計画に沿いまして、毎年６園ずつ当初予算で組んでおります。結果的に前倒しで開設を進めまして、平成２９年度は１２園、平成３０年度４月には１６園ということで、開設数が当初予算とは違ってきておりますので、その差額ということになります。","id":"exchange-065"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後もこうした区のほうも取組みを進めているので、また補正でこうした大きな額が出てくる可能性というのはあるのでしょうか。平成３０年度は東京都も前の平成２９年度より９０億円ぐらい予算案を増額する予定ですけれども、引き続き東京都と品川区のこうした待機児童解消の取組み、進めていっていただきたいのですが、そうしたことについて区のご見解をお聞かせください。","respondent":"大澤待機児童対策担当課長","answer":"今年度、子ども・子育て計画の改定をいたしまして、平成３１年度の開設は１２園となっております。それに合わせて平成３０年度の予算も１２園で予定していますので、平成３０年度につきましては、大きな補正は今のところないかと考えています。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"繰越金についてお伺いしたいのですが、これも平成２８年度と平成２９年度を比べますと、補正の額が１５億円ほど、平成２９年度のほうが増えているのですけれども、その理由をお聞かせください。","respondent":"秋山財政課長","answer":"繰越金ですけれども、これは平成２８年度の歳入と歳出の差額ということで、平成２８年度の決算が６月に出ますので、それ以降、その時点で確定いたしましたので、補正予算でその歳入と歳出の差額を今回こちらで入れるという仕組みになっているところです。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問","question":"それは年によってやはり違ってくるものなのでしょうか。","respondent":"秋山財政課長","answer":"その年の決算ですので、決算の最終的な数字が幾らになるのかというのは、その年の使い方、それから歳入の仕方によって変わってきますので、これが一定の数になるということにはならないと考えています。","id":"exchange-068"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなかこうした額、差が大きいと、どうしてかなと思ってしまうのですけれども、予算の精度というものをぜひ上げていってほしいと考えておりますので、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は８７ページの品川区国民健康保険事業全体について質問いたします。平成３０年度から国民健康保険制度は大きな制度変更が行われることになりました。先ほども質問がありましたが、補正予算審議にあたり、まずこの国保制度変更の概要と、なぜこのような制度変更が行われることになったのか、ご説明をお願いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"平成２４年の社会保障制度改革国民会議がございまして、それを経て平成２５年、社会保障改革プロセス法案というもの、方針が出されました。それに基づいて、平成２７年に持続可能な医療保険制度を構築するための国民健康保険法等の一部改正がございました。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"質問","question":"詳細なご説明ありがとうございました。１点だけお聞きしたいのですが、新制度になると、東京都は都内区市町村へそれぞれ納めるべき納付金や、標準的な保険料率を提示し、区はそれを参考にして保険料率を決定するとなるようです。そして品川区は、新たにつくられる特別区統一保険料率方式に参加すると聞きました。この特別区統一保険料率に品川区が参加するメリットが何か、区のお考えをご説明ください。","respondent":"三ッ橋国保医療年金課長","answer":"メリットは大きく３つあります。特別区統一基準保険料率は、平成１２年から長年継続してきた実績があること、そして同一所得、同一世帯の場合は同一の保険料で区民の皆様にわかりやすいこと、そして将来的に都内統一を目指していくための考え方に即していること、この３つです。","id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"質問","question":"区のお考えをお聞きしました。制度変更については、今後もさらに議論を深めていきたいと考えております。次に、増大する医療費を抑制する目的で医療費適正化施策が行われていますが、この医療費適正化施策の１つである後発医薬品利用促進についてお尋ねいたします。このジェネリックの利用促進について、その目的と現在どのような取組みが行われているか、ご説明をお願いいたします。","respondent":"三ッ橋国保医療年金課長","answer":"ジェネリック医薬品についてですけれども、こちらは花粉症や風邪に関する処方箋に加えて、区といたしましてはジェネリック医薬品の周知および使用促進を実施しております。こちらはやはり高額な医療費の抑制というものが大きくございまして、そちらを目的としております。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もしも後発品を推奨するならば、幾ら医療費が安くなりましたというような価格面だけを強調するのではなくて、患者の健康と安全のために全てのジェネリックを推奨するのではなく、先発品と同様の効果を持つ後発品だけを十分な薬剤情報を患者に提供しながら推奨するべきだと考えますが、区のご見解はいかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"実際には医師や薬剤師の皆様方の丁寧な説明が必要でございまして、今後も引き続き医師会や歯科医師会、そして薬剤師会の皆様のご理解、ご協力を得ながら、また連携しながら取り組んでまいります。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"個々の医師、薬剤師の努力だけではなかなか話が進まないので、その辺は行政のほうでも何らかの処置とか、施策、対策を考えていただけるように、これは要望したいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"こちらは高齢者の医療の確保に関する法律に基づいて生活習慣病の対策がございまして、東京都は糖尿病重症化腎症プログラムというものを策定をする予定です。その中で２回、今現在ワーキンググループで話し合いをしています。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"さまざまな施策を行うことによって、区民の健康レベルの改善と医療費の適正化について、今後もご努力をお願いして私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"確認","question":"私からは５６ページ、児童措置費、区内私立保育園経費、国・都支出金返還金から、保育従事職員宿舎借り上げ支援事業、５９ページ、保健所等管理運営費追加分から、午前中もございましたが、簡易宿所について伺いたいと思います。保育士へのこの家賃助成、この５７ページの返還金に含まれているのかどうか、予算立てしてその分使い切らなかったので戻したのかということで、確認をしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"都への返還金ですが、保育対策総合支援事業費補助金ということで、４８５万円の返金をしております。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それでお伺いをしたいのが、これはスキームとしては、私のほうで言ってしまいますけれども、４分の３が国・東京都、区が８分の１と。お伺いしたいのが、なぜこれが１００％の助成ではなくて８分の１、おそらく事業者にとってはそれほど大きくない金額だと思うのですけれども、そもそもなぜこの事業者負担を設定したのか教えてください。","respondent":"大澤待機児童対策担当課長","answer":"事業者負担分ですが、これはやはり民間の事業者ですので、その事業者の職員の処遇につきましては、一定のご負担を事業者にいただくという考え方があります。それによって事業者にも責任を持ってこの制度を活用していただくという趣旨もあります。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"例えば翻ってみるならば、わずかな８分の１の助成を惜しむような認可保育園、保育事業者。それと今、実際に伺いますけれども、これ、手を挙げていない事業者が果たしているのかどうか。それと最後、既存の保育事業者、新たな事業者もそうなのですけれども、既存の事業者に対しても、やはりこれは強制はできないにしろ、改めて徹底してもらう、周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"新規に開設する事業者に対してですけれども、必ず宿舎借り上げの制度はご説明しています。品川区の場合はほかの区と比較しますと、制度を比較的緩やかに対応しているために、事業者からは保育士確保に大変有効な手段だと伺っております。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に簡易宿所の件で伺いたいと思います。こういう表記もあります。確認しますが、このホームページの記載のとおりなのかどうか。だとするならば、午前中、説明会の義務化というお話があったのですけれども、まずフロントの設置と管理者の常駐の義務化、こういうことが条例なのか、要綱なのかわかりませんが、そこについて検討が必要ではないかと思いますが、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"どこのサイトかよくわからないのですが、今、ご紹介ありましたけれども、そのようなことはございませんで、玄関帳場についての設置というのは原則義務化しています。例外的なものについては、国の省令での基準がありますので、それにのっとって厳格に指導しています。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"とすると、複数のホームページが虚偽の事項を記載しているということですので、これについては、品川区のほうで確認をしていただいて、「違いますよと。行政書士さん、これ違いますよ」ということで、行政書士の複数のページにそう書いてあるわけです。ぜひこれは注意をしていただきたいと思います。","respondent":"井浦生活衛生課長","answer":"そのようなご指摘をいただきましたので、どのようなサイトか確認しまして、きちんと法令に基づき、そして区の条例に基づいて指導しているというところについては説明してまいりたいと思ってあります。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"きちんと対応していただくということでございましたけれども、これ始まってからでは遅いのです。ですから、すぐに対応していただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"７８ページの職員給与費、その辺についてお伺いをします。全体的に見ても、職員給与費追加分ということで、これはおそらく昨年の人事院勧告ですか、給与が多少増えたので、追加はわかります。総務費ですか、４８ページの総務管理費の中に、それぞれの項の中に給与費追加分、減額分ということはあるのですが、退職手当の追加分に関しては、これは総務費の中で管理をされているのか。","respondent":"黒田人事課長、矢木生活福祉課長、持田河川下水道課長","answer":"退職者数が１４７人ということで、来年度の採用見込みですが、今のところまだ採用者数確定しておりませんけれども、おおむね一般職員で１５０人弱。こちら一般的に国が４分の３、区が残りの４分の１を負担するというルールになってありますが、そのうち国が４分の３負担する部分につきまして。戸籍事務費の部分ですが、サービスコーナーを委託した関係で、再任用短時間職員につきまして減員しておりますので、その分で減額が発生しています。","id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"特にすごく追加補正で増えてしまったわけではないので、それは安くあがったというと言い方はおかしいですけれども、しかしながらもっと地域の住民の方と区がお話をして、どうですか、つくりますからといったときに、こういう提案があります、それはちょっとやめてくれという話がおそらく、切り下げないでくれという話があれば、その流れでいくと思うので。","respondent":"持田河川下水道課長、鈴木建築課長","answer":"今言われたように、地元のほう、早目に絵を見せて、早目に意見をいただいてというところは必要なところだと考えていますので、今後設計を進めるにあたりましては、そのような形でしっかり検討していきたいと思ってあります。次年度送りにするにあたっても、前年度で設計を終わらせる等々対応して、できるだけお待ちいただかないような形で私道のほうの整備、今後も進めていきたいです。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９０ページの国保会計と、１３０ページからの介護保険会計についてお伺いしたいと思います。この取り立ての問題についてお伺いをします。東京都の収納率向上にかかわる取組成績別交付算定表による平成２９年度に品川区に入る交付金の総額は幾らなのか、これは何年度分でいつごろ入るのかについてもお聞かせいただきたいと思います。総額だけで結構です。","respondent":"三ッ橋国保医療年金課長","answer":"それが新規口座の振替世帯率という東京都自身が算定するもので、そちらの部分、不明な部分がありますけれども、そのほかの部分につきましては要綱に沿って金額等が算定される予定です。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこの実地支援研修は希望する自治体だけということなのですけれども、何区ぐらいになったのかということも、もしわかったら教えていただきたいですし、また品川区がなぜ希望したかということも教えていただけたらと思います。そしてもう一つ、平成２９年６月１５日に滞納整理部門の職場研修、職場講師育成というものが行われていると思いますけれども、ここには品川区から参加しているのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"こちら２３区全てなのかどうかは、参加しただけですのでそのあたりは不明です。２回目の研修ですけれども、こちらは実施されており、品川区としても２名参加しております。先ほどの整理係の者です。マニュアルです。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このマニュアルについては、国のほうとしても作成について、東京都に対して各保険者において収納対策緊急プランの策定を行うように助言指導をお願いしたいということも、これは平成１７年くらいのときから出しているものですけれども、これにかわるものが何らかの形で品川区にはあるということなのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"差し押さえの意味ということだと思いますが、こちらはやはり収納率の向上が一番大きいと思います。その中で、やはり国保と申しますのは自主納付が原則と考えております。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この件はさまざまなところでやりとりをしているので、私は改めて品川区がこの差し押さえのところも国税徴収法に基づいてというふうに言われておりますが、差し押さえ禁止財産も預貯金に入れば、それを継承しないということで、そこまで差し押さえるという方針でやっているのだということも先日の厚生委員会の中でも改めて確認されたところですけれども、この研修の中でも。","respondent":"寺嶋高齢者福祉課長","answer":"１点目の基金の取崩し額が当初の見込みよりも少なくて済んだという部分ですが、想定の範囲か否かということですけれども、この基金の取崩しにつきましては、最大限給付が発生した場合、それから保険料の歳入が少なかった場合を見越しての基金取崩し額を設定しておりますので。","id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"４３ページ、公衆便所について伺います。トイレについては、公明党会派を中心に学校トイレ、ずっといろいろ聞いていてなるほどなと思うことと、そもそものところを考えながら質問させていただければと思います。それと２つ目が、学校トイレでもありました和式と洋式の比率、先ほど学校のほうが、直近ですが６６対３４の比率、公衆トイレに当てはめると、おおむねどのぐらいなのか教えてください。","respondent":"溝口公園課長","answer":"トイレのそれぞれの数です。公衆トイレにつきましては３６カ所、区内全体であります。公園、これは児童遊園も含めてになりますが、公園、児童遊園に設置されているトイレといたしましては、１２７個整備しているものです。","id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問・要望","question":"洋式率３３％、確かにそうだなと思い浮かべればというところがあるかと思います。利用状況のところに行きます。これ今設置を聞いて、地域によっても、品川区も広いですからエリアによっても違うかと思います。ただ、私たちがよく耳にするのは、女性がトイレ行きたいといったときにも、やはり公衆トイレというよりは何か屋内の商業施設等を求めるケースがよく見受けられます。","respondent":"溝口公園課長","answer":"２５０メートルのメッシュを切ると、おおむねその範囲に必ずトイレがあるような形、これは大体５分ぐらい歩いていくとトイレがあるような形になっておりますので、おおむねそういった形で区内では充足していると考えているところです。利用状況です。","id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問","question":"これも財政基盤等がかかわってくるのかなと。そういう意味で、次に、改修等があるときの方針を教えてください。クラブハウス等も改修をされている。そういう中で、改修の主な計画ですか、単年度なのか、複数年なのかも含めて教えてください。個別案件も含めてしまうのですが、ほかの清掃等の管理は抜群にいいと思うのですけれども、この辺がもったいないなという思いもあったので伺いたいと思います。","respondent":"溝口公園課長","answer":"順次今進めているところですが、今年度、来年度を含めて改修工事をして、全てクラブハウスの改修または増築、そういったものの工事が終わりますと、更衣室も含めてバリアフリー対応、またシャワーも車椅子の方がご利用いただけるようなシャワー室。","id":"exchange-090"},{"speaker":"渡辺委員","kind":"確認","question":"もうある程度既に考えられているのだなということを確認できて、何か晴れやかな気分といったら変ですが、見通しが立っていいかなと思います。そういう中で情報発信です。やはりトイレの場所等、これは住んでいる方もそうですし、長く住んでいる方しかり、あるいは観光という観点で人がいらっしゃる、そういう時代ですから、特に品川区はウエルカムという体制をとっている中で、どう知られていくか。","respondent":"溝口公園課長","answer":"先行しているところでいきますと、豊島区などは民間と協定を結んでトイレマップをつくって、その中で民間で使えるもの、また公共のもの、あわせて挙げている、そういった事例もうかがえますので、そういったものも含めて、どのような形で区民の方たちに情報提供していくのか。","id":"exchange-091"},{"speaker":"渡辺委員","kind":"確認","question":"もう１点、高齢者福祉の点では、やはり外出を習慣化する、これは力を入れられている施策なのですが、やはり町場の声の中で、当人もそうですし、付き添い、介護の方もやはりトイレの場所どこだろうと確認をされているケースが多いそうです。あるいは２０２０年、最後これはまとめのようになってしまいますが、やはりオリンピック・パラリンピックに力を入れている品川区としてバリアフリーを加速させる。","respondent":"柏原企画調整課長","answer":"２０２０年のオリンピック・パラリンピックに向けて、こういったところの事業というものは、我々としても加速させやすい時期だと考えていますので、そういった中でより施設のあり方とか、整備というものを、区全体として進めていきたいと考えています。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"私からは、５７ページの障害児施設給付費追加分、３,０００万円ちょっとですけれども、それについてお伺いしたいと思います。この増加分についての内容についてというところなのですが、あわせて、おそらくこの児童発達支援事業、または子ども発達相談室といったところにかかわる増だと思いますので、そちらの利用状況なども含めてご説明をお願いいたします。","respondent":"中山障害者福祉課長","answer":"こちらは児童発達支援ということで、未就学のお子様の療育の経費ということになっております。この間、区内にあります児童発達支援事業所の数も増えておりまして、現在１２カ所ということになっております。療育を求める保護者の方も多く、この間ずっと増加傾向にあります。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"区としてその辺の状況をどのように考えているのか、またその増えている原因というものはどういうところだと捉えているのかというところでお伺いをいたします。","respondent":"中山障害者福祉課長","answer":"その２カ月待ちという考え方が、インテイクといいまして、発達検査をとるまでの時間になっています。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"現在の仮移転先でのという体制から、しっかりとした体制になります。それから戸越ルームというものが、引き続きこういった療育の場としては使われるということで、これまでの議論もあったかと思いますが、こういった今後の施設展開と育英も含めて、この発達相談体制、具体的にどのような形になるのか、具体的な計画等も含めて、もし今の段階で考え等がございましたら、教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"あそこの、今、戸越ルームの使い方、今後のニーズを考えたときに、療育の場としてが良いのか、それともやはり身近な地域で保護者の方にご相談に乗れる場としての活用が良いのか、この辺のことについては民間の療育の今後の動きも見ながら検討していきたいと考えております。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"もしこの地域的なことについて何かありましたら、一言お願いしたいと思います。各保育園を訪れて、訪問や助言ということを実施するということですけれども、これが現在どのような形のものか教えていただきたい。どのような形で実施されているか、訪問の回数とか、助言の内容とか、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"国のほうもすごくこの支援については大事な支援ということで、次期の障害児福祉計画の中でも保育所等訪問支援を進めるようにということで強く言っておりますので、また保育園ですとか、学校ですとか、説明してご協力いただきながら。","id":"exchange-096"},{"speaker":"塚本委員","kind":"意見","question":"この事業ですけれども、大切だと考えていますが、特にこのところ保育園、大変増えておりますので、これからも増えていくでしょうし、そういう意味ではしっかりとこの事業が漏れなくというか、つつがなくというか、できるようにこれからもいろいろとご配慮いただければと思いますが、最後に一言お願いいたします。","respondent":"中山障害者福祉課長","answer":"さまざまな施設と連携をして周知を図っていきたいと考えています。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"３月１１日で、東日本大震災から今年で７年が過ぎようとしております。ですからページ数は不明です。お聞きします。実態を教えていただきたいのですが、区有施設においての非常用発電機は、所管ごとでお願いしたいのですけれども、何機あって、管理がどのような状態になっているでしょうか。全体の掌握がされているのか、どこがそれを集計しているのかをお聞きしたいと思います。","respondent":"小林施設整備課長","answer":"非常用発電機のご質問ですけれども、区有施設の中には３１施設に非常用の自家発電機が設置されております。それで、今ご質問の負荷運転等については、消防用設備等点検報告というものが年に一度、消防機関のほうに報告の義務がありますので、各所管が実施しています。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"３１施設にあるというのはわかりました。では、この法定負荷試験というのはどういうことでしょうか。それが本当になされているのか。そこはいかがですか。","respondent":"小林施設整備課長","answer":"その際、消防機関のほうからは指導がないと聞いております。しかしながら、必要なものについて今後消防機関と協議をして、実施していくものについては実施していくということで努めてまいりたいと思います。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"この法定負荷試験、課長がおっしゃいました３０％負荷をかけて試運転をするということなのですが、電源を入れてついたからきちんと稼働ができているということではないのです、この負荷試験というのは。３０％の負荷をかけてチェックをしなければならないのです。ということは、今３１施設のこの発電機に対して、何ら法定的な規定に基づいたチェックがなされていないということではないでしょうか。","respondent":"小林施設整備課長","answer":"先ほどもご答弁いたしましたが、今後必要なものについては実施をしていくということで努めていきたいと考えています。消防機関とも協議をして、行っていきたいと思います。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"この消防法でいいますと、担当者に対しては３０万円以下の罰金または拘留です。こういう実態を各所管の方々も知っているのかどうなのか、まず１点お聞きしたいと思います。そうなりますと、当然ながら消防署だけではなくて公的な機関、または民間ですと病院等々も含めて、このチェックをしなければならないということが、かなり追及されてくるのではないかと思いますが、その現状はご存知でしょうか。","respondent":"小林施設整備課長","answer":"その辺の動きも注視して、必要なものについては実施していくように努めてまいりたいと思います。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"必要なのではないのですか。これ、非常用発電機がなぜ必要かというと、災害があったときの非常用のものだからです。やらないといけないことなのです。全庁あわせての情報共有も、各所管に任せるということではなくて、例えば危機管理室があるわけですから、そこで全体を掌握するとか、全体を管理していくという仕組みも必要になるのではないかと思いますが、その体制についてもお答えいただきたいと思います。","respondent":"小林施設整備課長","answer":"そのような状況の把握はしております。それとあと各主管課については、今消防機関と協議をして、必要に応じたものを委託内容に盛り込むとか、そういうものをこちらのほうから指導していきたいと考えています。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"これは早急に対応していただきたい。本来は仙台市であるとか、福岡市のことの情報が入っているのであれば、早急に品川区としても取り組むべき課題ではないかなと思うのです。その理由で不具合が生じて、そこから災害が発生するということも起きておりますので、ぜひこれは早急に品川区全体として考えて進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたします。しかし、計画がスタートしたからには、１００％を目指すお考えがなければなりません。その中で、この事業で４つの減額、３億６,１８４万円ですけれども、中でも旧同潤会地区の防災街区整備事業２億４,４６４万円が大きいわけでありますが、減額の理由は計画に無理があっての減額か、それともほかに何かあるのか、お聞きしたいと思います。","respondent":"高梨木密整備推進課長","answer":"こちらの減額の理由ですが、工事進捗による減となっております。具体的な工事進捗のおくれについてですが、基礎工事実施中に地中に障害物が発生したことによる出来高の減となっております。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、もし本区で阪神・淡路大震災や糸魚川市のような地震・火災が起きた場合、被害を最小限に食いとめるには常日頃から何を準備しておけばいいのか、また、区民に日頃からどのような心構えや準備をしていただくのか、行政側からのお考えというものをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"木密地域を多く抱える品川区におきましては、そういった被害を最小限に食いとめるために、今ある燃えやすい建物を火災に強い建物に一刻も早く変えていただくべく、今後も重点的に取組みを進めていきたいと考えております。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、不燃化１０年プロジェクトはこれから３０年以内に起きると言われている、この大震災だけではなく、あらゆることを想定した災害に対し、しっかりとした計画のもと事業を進めることが、３９万人にも及ぶこの区民全員の願いだと私は思っています。ぜひとも行政として、都民の１人としてのお考えというものも、もう一度しっかりとお聞かせをください。","respondent":"高梨木密整備推進課長","answer":"いろいろと建替えが進まない事情等あると思いますが、改めてこの時限的な助成制度があるということをしっかりと区民の皆様に説明し、理解していただいた上でご協力いただける方を１人でも多くいただいて、燃え広がらない、燃えないまちの実現に向けて。","id":"exchange-106"},{"speaker":"木村委員","kind":"意見","question":"ぜひお願いをいたします。本区においても、中延や旗の台、そして豊町、西品川、大井ほか、補助２８号・２９号線、放射２号線沿道地区など、この区内１４地区において計画が今進んでいることと思いますけれども、２０２０年ごろを完成目途にしているのでしょうが、それともまたいろいろな事情により延びるような可能性もあるのかどうかということをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"しかし、品川区内を燃えない、燃え広がらない、安全なまちにしていくという使命はなくならないと考えておりますが、まずは期限末である平成３２年度末を目標年次と定めて、それまでに精一杯取組みを進める必要がある、このように考えているところです。","id":"exchange-107"},{"speaker":"木村委員","kind":"意見","question":"１９２３年９月１日に発生した関東大震災では、マグニチュード７.９で、その後、翌日にかけてもマグニチュード７以上の余震が７回も起き、激しい揺れによる建物の倒壊や大火災による被害というもののほかにも、津波や山崩れによる被害も甚大でした。行政として、都民の１人としても、そのしっかりとした計画、またお考えをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"は火災に強いまちが区民一人ひとりの生命と、それぞれの財産を守るということが第一義だと考えておりますので、引き続き強力に推し進めていきたいと考えております。","id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"２０１０年４月に東京都が公表した被害想定では、広範囲に存在する木造密集地域市街地を中心に、大規模な火災延焼が起き、東京都内だけでも最大約２０万棟が焼失、火災による死者は４,０００人以上に上るとも言われています。お聞きいたしますけれども、本区でも複数箇所から出火することが予想されていますが、一斉に発生した場合、消防車や救急車の台数というものは今のままで十分と言えるのでしょうか。","respondent":"高梨木密整備推進課長","answer":"消防車等の台数については、また後ほどお答えがあろうかと思いますけれども、まず委員ご指摘のとおり、東京の被害想定では品川区の死者のうち火災の死者数が多くの想定されているところで、消防車の台数等も含めて、総合的な防災対策が必要になってくると。","id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これが増額になっていますけれども、１,８００万円余、その増額の理由を教えてください。これはマイスクールは私も地域の方から足りないということで、八潮だけあって足りなかったときに、増やしてほしいというお声を聞きまして、それで五反田のマイスクールができたという状況がありました。この補助金が、当初予算に入っていなかった中で、補助金が入ってきた理由について教えてください。","respondent":"高山子ども育成課長、中山障害者福祉課長、大関教育総合支援センター長","answer":"こちらのほう、子ども・子育て支援交付金のほうの増額の理由ですが、年度当初、想定していたより補助の基準額が引き上げられたことと、そしてもう１点。この自立支援サービス追加分の中の特徴的なものというご質問です。全都的に各区市で適応指導教室を増設する際に、人的な補助を行うという制度が入りましたので、そちらのほうに応募いたしまして、認めていただいた結果。","id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"確認","question":"何かこれ特別の理由があってなのか。細かいところを見ていくと、事項別を見ると出てくるのだろうと思うのですけれども、この中で対応する部分が出てくるのが普通ではないかという点で、その確認をします。実際にやっていただけるのですから、それは十分いいことだと思っているのですけれども、当初予算でももう少しつけてもいいのかなという感じもするので、その辺はいかがでしょうか。","respondent":"秋山財政課長、中山障害者福祉課長、大関教育総合支援センター長","answer":"予算書上の財源更正の表記の仕方なのですけれども、歳入で財源更正があっても、歳出のほうで、例えば３目の児童福祉施設費のほうで。金子山を１０人の男性にすることに伴いまして、グループホーム森前、同じく福栄会が運営しているのですが。新たにマイスクールの機能を浜川中学校の一部を活用いたしまして、次年度より適応指導教室を増やすという件についてですが、ご指摘いただきましたとおり。","id":"exchange-111"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、５９ページの予防接種費追加分、定期予防接種、６３ページの立会川緑道概略設計委託、時間があれば１０６ページの特定健康診査等事業費について質問します。その後、特に問題になるようなことはあったのか、なかったのか。決して起こしてはならない事故だと思いますけれども、今後とも注意を怠らないようにしていただければと思いますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"事故対応のほうにつきましては、１０月末までを再接種の期間として実施いたしまして、そちらのほうの再接種については、特に大きな健康被害はなく終了しております。現在、最終的な報告のほうを区内に限らず、区外で受けた方の報告を待っているような状況です。","id":"exchange-112"},{"speaker":"浅野委員","kind":"質問・要望","question":"２点目といたしまして、立会川緑道概略設計委託の件ですけれども、緑道の改修ですが、３０年も経過をしているということで、今後進めていくという話を伺いました。この件につきまして、今回設計委託という形が出ておりますけれども、今後のタイムスケジュールというのでしょうか、計画の進め方などについて概略を教えていただきたい、よろしくお願いします。","respondent":"多並道路課長","answer":"ここの整備のあり方につきましては、今後、今年度概略設計ということを行っておりますけれども、今回の説明会の内容を踏まえまして、来年度詳細設計を進めながら、再来年度から順次工事計画を進めていきたいと思っておるところです。","id":"exchange-113"},{"speaker":"浅野委員","kind":"質問・要望","question":"このような場所であるからして、今回の計画が発表されたわけですので、どうか地域の住民の方にどのような形でこの計画を理解していただくといいましょうか、概要だけでも知っていただいて、それである意味協力も求められるということも考えられます。私もよく通るところです。大体完成する時期ですか、どのぐらいの期間、いつごろになるのか教えていただければと思います。","respondent":"多並道路課長","answer":"立会川緑道につきましては、来年度詳細設計を行い、そのときに、今委員のお話ありましたように、地域の方に個別にお話ししながら、整備のあり方についていろいろお話聞きながら、整備を進めていきたいと考えています。","id":"exchange-114"},{"speaker":"浅野委員","kind":"質問","question":"特定健康診査等事業費についてですけれども、他の委員からも質問もありましたが、特定健康診査等事業費、こちらが１１％減額補正となっているということで、この件につきまして、今後はぜひとも増額補正になるように取り組んでいただければなと、そのように考えているところですけれども、こちらの特定健診、なかなか率が上がらないということで苦慮されていると思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"のだて委員","kind":"質問","question":"私からは、６９ページの不燃化１０年プロジェクトに関連して、戸越公園駅再開発と、また同じく６９ページの住宅・建築物耐震化支援事業について質問します。は戸越公園駅、戸越五丁目１９番地区の再開発についてです。再開発地域も不燃化特区の中にありますけれども、この１９番地区再開発を防災のためと説明しますが、どこが防災のためになるのか、まず伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"戸越公園駅の南側です戸越５丁目１９番地区の再開発事業についてです。こちら、防災のためということで進めているだけではございません。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問","question":"防災のためだけではないというご説明でしたけれども、どこが防災のためになるのかということを伺いましたので、ご答弁お願いします。","respondent":"東野まちづくり立体化担当課長","answer":"防災というところに特化してお答えしたいと思います。この戸越五丁目１９番地区にあります建物、１３棟あります。この中で旧耐震以前の建物が８棟ある、木造住宅も入れまして８棟あるという状況です。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"長期間の避難生活では備蓄がやはりある程度の期間しかできないと思いますので、避難所に支給を受け取りに行くたびに２４階まで上り下りをしなくてはいけないと、そのようなことはできるはずがないわけで、結局避難所生活になるということになりますけれども、やはりこの超高層でなくて、別の耐震化であれば、方法があると思います。この超高層のどこが防災になるのか、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"この戸越五丁目１９番地区につきましては、商業的なところの配置、そういったものも含めまして、必要な施設だと考えています。新たな居住空間の確保、こういったところから一定程度の高さは必要だと考えています。","id":"exchange-118"},{"speaker":"のだて委員","kind":"質問","question":"課題解決のため、あと商業的にも、そして住戸確保のためにもやっているというお話でしたが、商業的にということであれば、別に超高層にしなくても、商業的には沿道に商店を設けることもできると思います。この地図で見ますと、１９番地区のところはどの建物も接道していて、再開発でなくても建替えできると考えられるわけですけれども、再開発でないと建替えできないということなのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"建替えに関しましては、再開発でなくても建替えは可能です。ただ、こちらのお住まいの方々がみずから企画いたしまして、そういう再開発の手法によるまちづくりを望んでいる、それを区としては支援していくものです。","id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"地域の方が望んでいるというお話でしたけれども、この地域の中で情報発信として行われた事業者の説明会があったのですが、そこでは再開発以外の共同化ですとか、あと単独での事業の説明もありました。なぜ再開発になったのか、防災のためなのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"その中には共同化による方法、それ以外の、いわゆる一般的な建替えによる方法、そういったものについても皆さんで考えた末の結果としまして、再開発事業の手法を用いたものが自分たちのまちづくりに一番ふさわしいのではないかという考え方から。","id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"超高層が防災にもなるというお話もありますけれども、この超高層とほかのもので、先ほどご紹介しました共同化ですとか、単独事業、こういったところと耐震性というのは違いがあるということなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"超高層の建物とほかの建物につきましては、耐震性というところでは耐火基準を満たしているものであれば、何ら変わりはないと思います。","id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"やはり超高層によって別のリスクを生み出すということにもなってきますし、今の商店街がやはり商店の方も顔を合わせてコミュニケーションを取ることができる、こういったまちづくりがいいのだということで、この防災の面から見ても、超高層ではなくて低層、そして戸建への支援で防災に強いまちづくりを進めていくべきだと思います。この目標が未達成になっていますが、これでよいと考えているのか伺います。","respondent":"鈴木建築課長","answer":"ただ、目標に対しては非常にまだ、９５％ですので、これからもしっかり耐震事業、支援事業を充実し、あるいはＰＲしながら耐震化を図っていきたいです。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"ただいま８８.４％までいっているというお話でしたが、一応目標までには達していないということですけれども、以前の速報値は７３.５％だったと思うのですが、これはなぜこんなに急に上がったのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"先ほどご紹介しました８８.４％につきましては戸数ベース、これは先ほどもご紹介しましたように、東京都ならびに国がこの戸数ベース、より現実、世帯ベースに近い数字として採用してございまして、今その形で速報値のほうを算出しているというものです。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"今、戸数ベースでやっていることで８８.４％ということでしたけれども、マンションですとやはりもう数百戸という建物の戸数になるわけです。そうすると、やはり棟で考えたほうが、１棟、２棟で考えたほうが、この耐震化というものが実態に合ってできると思うのですけれども、そういったお考えは今後検討されるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"それぞれ木造の戸建住宅についても、充実した耐震化支援を今後も進めていきたいというものです。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問","question":"これは住宅の耐震化をすることによって、大震災のときの人命を守るということですとか、救助の際に道を塞ぐことがないようにするということが、やはり重要だと思いますけれども、今木造住宅についてどうなっているのか伺います。","respondent":"鈴木建築課長","answer":"当然ながら区全体の住宅は９５％を目指していくわけですけれども、それぞれ戸建、マンション、非木造、耐震化率を上げるべく、特に今年度からはアクションプログラムを木密地域内で開始しておりまして、特に戸建住宅についても耐震化を充実していきたいです。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひやっていただきたいのですけれども、来年度東京都の耐震改修の診断設計工事に補助が計画されております。一般質問でもお伺いしましたけれども、この区も既に補助を行っていると思います。あわせて、高齢化でなかなか建替えできないという方もいらっしゃいますけれども、そういった方にも個別に対応をしっかりとやっていっていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"来年度から東京都が全域でですが、既に区では平成１９年度から診断、設計、改修工事、全てにおいて全域で充実して、１５０万円、３００万円で助成を行っております。今後も進めていきたいです。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問・要望","question":"４８ページから、各項別、各目別で、それぞれ職員給与費が出ております。追加分があったり、更正減額があったり、午前と午後の質疑を踏まえまして、聞かせていただきたいと思います。全体的にこの平成２９年度の最終補正としまして、特色については先ほどのやりとりで、退職者の見込みが１０２人から１４７人だった、これも特色だと思うのですが、ほかに何か特色があれば教えてください。","respondent":"黒田人事課長","answer":"７８ページの、いわゆる給与費明細から申し上げますと、今回の補正では退職手当を除くと、人数としましては３５人増えておるのですが、金額としましては９,７５０万円ほど減額となっておりますので。","id":"exchange-127"},{"speaker":"本多委員","kind":"質問・要望","question":"全体について聞かせていただきました。今度は個別にちょっと聞かせていただきたいと思います。７３ページの小学校・中学校の教職員ですね。両方とも減になっておりますけれども、平成２９年９月から区内公立学校において、定時退勤日を設定したということなのですが、そういったこととの関連性について何かあれば教えてください。","respondent":"黒田人事課長、品川庶務課長","answer":"職員費の減につきましては、用務職を退職不補充としている関係で、人件費が減となっているというものです。例えば広報紙等に学校の勤務時間は何時から何時までだよというような形で、教員の正規の勤務時間を区民の皆様にもはっきりと示していくというような方向で、今こういった取組みを進めているようなところです。","id":"exchange-128"},{"speaker":"本多委員","kind":"質問","question":"ちょっと次の質問に行きますが、６１ページの清掃総務費の職員給与費につきまして、今定例会で専決処分の報告がありましたけれども、清掃作業中に、クリーニングに出すタオルを誤って収集してしまったという、一生懸命やっていればこういうこともあると思って、本当に普段の作業には感謝しております。それと平成２９年度、平成２９年４月から回収した小型家電、「都市鉱山からつくる！解析をすると。","respondent":"工藤品川区清掃事務所長","answer":"収集職員との関係という部分につきましては、こちらのほうは拠点回収でやっておるですので、私どもの収集の部分とは、別の部分で業務をやっておりまして、拠点回収、シルバー人材センターのほうにお願いしているです。特に影響という部分は見受けられないと考えておるところです。","id":"exchange-129"},{"speaker":"本多委員","kind":"意見","question":"最後に１点聞かせてください。先ほど質疑のやりとりで、行政サービスコーナーの人件費が直営事業の委託化、民間活力によってコスト削減という答弁がありました。この直営の事業を民間活力でという、この考え方についてお聞かせください。","respondent":"柏原企画調整課長","answer":"それは仕事の中身、それからどのようにサービスを提供するかというものによりますけれども、民にできるものは民という考え方のもとで直営の事業、それから委託できる事業というものは、区分けをしながら行っていくというものです。","id":"exchange-130"},{"speaker":"松永委員","kind":"質問","question":"私からは３９ページ、国庫補助金、防災生活圏促進事業、そして同じページの避難道路機能強化事業、そして同じ事業名ですが、４３ページの防災生活圏促進事業、避難道路機能強化事業で、また同じ内容ですけれども、６９ページの防災生活圏促進事業、それぞれ伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"具体的に言いますと、林試の森公園周辺では、かむろ坂付近から林試の森公園東門に至る富士見通りと呼ばれる道路の拡幅整備を行っておりまして、それと戸越公園につきましては、大原通りの東急大井町線から四間通りの間の６メートルへの拡幅整備。","id":"exchange-131"},{"speaker":"松永委員","kind":"確認","question":"この補正予算の内容、今確認させていただきました。その減になってしまった理由、それぞれどのような形でこうなってしまったのか、理由について教えてください。","respondent":"高梨木密整備推進課長","answer":"しかしながら、沿道の皆様と用地取得に係る交渉をする際に、用地をいただく交渉が未了で終わったため、今年度につきましては記載のとおりの金額を減額すると、このような理由です。","id":"exchange-132"},{"speaker":"松永委員","kind":"質問","question":"そこで、これ測量等の委託減というのは、その内容ですか。道路の変更というか、道路以外にも、例えば用地を取得して公園にしたりとか、いろいろさまざまな形になるのかなとは思うのですけれども、そういった計画が変わってしまっているのか、ちょっとその辺がわからないので、この測量等委託というものが変わってしまうとどうなってしまうのかなと思って、その辺について伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"この内容についてなのですが、ただその用地の測量をするだけではなく、当然用地をお譲りいただく際に一体どのぐらいの面積があるのかといったところを確定するために、現地の測量をするというような委託も当然行いますけれども。","id":"exchange-133"},{"speaker":"松永委員","kind":"質問・要望","question":"さまざまあるということなのですけれども、今後についてなのですが、今こうした国、都、そして区が行っている事業の中で、現状今整備というものはどれくらい進んでいるのか、全体的に何％ぐらいでもいいので、完了しているのか教えていただきたいと思います。例えば雑草が生えてしまったりとか、その環境がどうなっているのか、最後にそれについても伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"最初に道路拡幅の進捗率についてお答えをいたします。林試の森公園周辺で行われている地区防災道路と呼ばれる富士見通りの拡幅整備なのですが、こちらにつきましては約３６％の進捗率となっております。","id":"exchange-134"},{"speaker":"松永委員","kind":"質問","question":"実はそうした用地に関してなのですけれども、ずっとそのままほったらかしにするのはもったいないので、何かほかにできないかなとか、例えばそういう場所は、ちょっと暗いのです。周りが。最後ですけれども、この目標について、大体いつごろ、このパーセンテージを見るとなかなか進まないかなとは思うのですが、もしその目標がありましたら教えてください。","respondent":"高梨木密整備推進課長","answer":"区といたしましては、事業についての普及啓発活動を活発化させて、１日も早く整備が進むように、できるだけ道路にならないで遊ぶような土地がなくなるようにということで努めてまいりたいと思います。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"４６ページの歳入で繰越金について、それから５６ページの児童福祉施設費の職員給与費、これはほかの委員からもいろいろ質問があったと思いますが伺います。そしてここで補正をしているということです。先ほども簡単にあったのですが、もう一度見込額を４４億云々というふうに出した計算、算定の根拠と、補正においてこの繰越金についての考え方をお尋ねします。","respondent":"秋山財政課長","answer":"歳入と歳出の差額というもので、これは昨年の秋の決算特別委員会において認定いただきました実質収支４４億８,７５５万７,０００円が９月に確定いたしまして、今回平成２９年度予算で平成２９年度に繰り越す額がこちらの４４億８,７５５万７,０００円に確定いたしましたので。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話あったように実質収支の額ということです。これはちょっと平成２７年のものなのですけれども、渋谷区が５.９％、文京区は５.３％と非常に比率が高い。２３区平均だと３.２％で、品川区は中位よりもちょっと下というところなのですが、その数字と、品川区としてのこの繰越金のメッセージについてはどのようにお考えでしょうか。","respondent":"秋山財政課長","answer":"歳入と歳出の差額という実質収支という考え方が、実質収支比率という中で評価をされているというところもありますし、実質収支比率自体がそもそも地方交付税のないところで、２３区の状態でどうかという議論もありますけれども、そういう評価の中で実質収支を入れておりますので。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望します。ここで繰入金の補正額がないということは、そのまま平成２９年度当初予算で８０億円の基金繰入金を組んでいるのですけれども、それをそのまま全部歳入のほうに入れるというふうに、補正予算に繰入金が入っていないところを見ると、そのように考えてもよろしいのでしょうか。","respondent":"秋山財政課長","answer":"基金繰入金に関しましては当初予算で立てたものを、今回補正をしていないので、その額で繰り入れをしていくという予定でいるです。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"確認","question":"それで、これまでの平成２６年から平成２８年までは、一応補正で数字を出していますけれども、それ以上の形で繰り入れをしないで済んでいるというところがあるのですが、今年度はここでゼロということは、もう１回お話になるのですけれども、補正等で最終処理をするのではなくて、今お話あった当初予算の８０億円をそのまま歳入のほうに繰り入れるというふうなことで確認ですがよろしいでしょうか。","respondent":"秋山財政課長","answer":"最終補正とはいえ予算ですので、実際に出納閉鎖後の決算のときにどうなっているかというのは、ここで補正をしないということはあまり動くことはないだろうという予測はしておりますけれども、８０億円を必ず繰り入れるかということには、あくまでも予算ですので。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"昨年も一昨年も１０億円の補正をしている、それぐらい動くだろうという感じがあったのでしょうけれども、今年はそれだけ動かないだろうというようなお考えは、どのようなところから出てくるのでしょうか。平成２６年度でも４億円ぐらいの補正をしているということですので、そのあたりが全くないというところが非常に、これまでの数字から見て非常に目立ったところがあるので、お尋ねしています。","respondent":"秋山財政課長","answer":"こちら最終補正の考え方ですけれども、考え方というか、繰入金の考え方ですが、歳出に連動してそこの財源が出てきたとかいうことがあって、平成２７年、平成２８年については減額をしておりますが、そういう意味では今回はそういう影響が出ていないので。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの職員給与費のところは、保育士のお話がいろいろ出ていましたが、平成２８年度は２億５,０００万円余の減額があって、今年度は７,０００万円ぐらいなのですが、先ほど若い年齢の方が多かったという話があったのですけれども、昨年はちょっと予算書の書き方が違う可能性もあるのですが、ほかの事業も含んで２億円の減額だったのでしょうか。","respondent":"黒田人事課長","answer":"昨年度の予算書の書き方につきましては、現在ちょっと手元に資料がなく承知しておりませんが、今年度の保育園の職員につきましては、７１２人から７２８人に増えておりますので、人件費相当分が減っているということでは、若い職員を採用しておりますので。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"時間のほうがないので、質問のほうがはっきりいろいろお尋ねできなくて申しわけありませんでした。保育士の退職や、あるいは採用についてはまた別の機会にお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"若林委員","kind":"提案","question":"やはりこういう発達支援をする場合には、当然早期発見、早期の療育ということがずっと指摘をされている中で、こういう小さいお子さんの２カ月待ちというのが果たして、ある意味で障害児と、障害となったわけではありませんけれども、合理的配慮云々の話にかかわってくる事項なのかなという心配もありますので、改めてなぜ今この状態が続いているのかということを１つお聞きして、では平成３１年の。","respondent":"黒田人事課長、中山障害者福祉課長","answer":"非常勤職員につきましては、現在の非常勤は専門非常勤と申しまして、いわゆる区の職員よりもやや専門性が高い仕事の部分で非常勤になっていただいたりとか、保育園ですと保育補助という形で。これを受けるための待機時間というものがかかっているところなのですが、その手前のご相談を受けながら、必要に応じてこの発達検査まで持っていく、そうしたこともしていくことで、なるべく初回の相談を早目に受けて。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"障害、発達支援のほうについては、まさに現場の知恵、創意工夫でいろいろな皆さんのチームワークでできることがあられるのだろうなと今の答弁を聞きながら思いましたので、物理的な部分、またそういうインテイクをする側の職員の部分、人数が多ければ早くできるでしょうと、当初そういうものもありましたけれども、そういうものでは決してないのだということで確認をさせていただいて。","respondent":"飛田障害者施策推進担当課長","answer":"それよりまた、今後さらに強化していくということで、連携のほうを進めて、さらにまた新施設が立ち上がります。それに向けて一致団結して進めていきたいと考えております。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"連携、当然大事だと思うのですけれども、私も代表質問でやりましたが、障害児、障害者の部門にやはり連携ではなくて保健職、専門職がいるということで、この計画も、本来はこの計画自体にも参画していただきたいなという思いがあったのですけれども、そこについて一言お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"伊藤委員","kind":"確認","question":"私は３４ページの普通交付金等に関連をして、それから３７ページ、区内私立保育園経費に関連して質問します。先に普通交付金等でありますけれども、これはずっと議論のありました平成２９年度の補正予算、普通交付金が５億円の増、それから繰越金が１７億５,６００万円余の増等々、大体トータルで約４２億円ぐらいの増の結果が出ていると確認しました。ただ数字だけ出てきている。答弁をお願いいたします。","respondent":"秋山財政課長","answer":"個々のものを足し引きをしまして、いわゆる当初の予定よりも減額の補正が幾らぐらい、増額の補正が幾らぐらいというご説明はできるのかなと思ってあります。","id":"exchange-146"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、行政の見える化といったらいいのでしょうか。プラスマイナスがわかりにくい感じがするのです。ですからこういう数字の内容も、それから議会にｉＰａｄは入りましたけれども、ここに具体的に非常にわかりやすい資料が出てきたわけです。だから、すぐにはもちろんできないと思ってはいるのだけれども、このＩＣＴ化のことについては、品川区の考え方だけをここでお聞かせください。お願いいたします。","respondent":"秋山財政課長","answer":"そういうものも含めて、膨大な量をどうやってお見せするかというようなことも課題としてはあるかと思いますけれども、その辺も含めて、何らか見え方といいますか、説明責任という言葉もありますので、そういうところも含めて。","id":"exchange-147"},{"speaker":"伊藤委員","kind":"確認","question":"これはいろいろと確認しましたけれども、今年の補正予算、保育園は合計で約８３億円の予算が補正されています。これはもちろん今の待機児童対策でさまざまな事業を展開されていらっしゃるから正しいことではあるのだけれども、補正だけでこの金額ですから、このほかに通常経費を考えたら結構な金額を保育園に投入していることがわかります。結果として保育士の希望は非常に多い。お願いいたします。","respondent":"佐藤保育課長","answer":"私立幼稚園関係の幼稚園教諭等の処遇改善確保の関係のご質問だと思います。品川区といたしましては、これまでも私立幼稚園が幼児教育の主たる施設として、区立幼稚園は補完の立場というところで対応してきたところです。","id":"exchange-148"},{"speaker":"伊藤委員","kind":"質問","question":"それは当然なことではあるのです。もちろん繰り返しますけれども、園数も違うし、目的も違う。ご承知のように。でも幼稚園教諭というのは教諭ですから、１０年に一度その免許の更新が必要だということも聞きました。それはもちろん法的な体制もあって、それから所管の官庁も違うから、一概にすぐこの場でどうこうと言えない部分はあるのだけれども、だけれどもやはり私立幼稚園の方々の思いは切実であります。","respondent":"佐藤保育課長","answer":"定期的に私立幼稚園協会等からさまざまな要望等聞く場もありますので、委員ご指摘の趣旨も踏まえまして、今後さまざま検討していきたいと思います。","id":"exchange-149"},{"speaker":"伊藤委員","kind":"意見","question":"その方向は。だから、すぐにこの場でどうこうはできないとはわかっていながら聞くのだけれども、補正だけで保育園は約８３億円です。それで、平成３０年度の新規予算では、私立幼稚園は約８億円です。だからこれだけの差がある中で、幼稚園がどう生き残っていくのか、私立幼稚園が。どういうふうに確保していくのかということについては、結構大きな課題でありますから、もう一言だけ答弁をお願いいたします。","respondent":"佐藤保育課長","answer":"私立幼稚園に関するご質問ですが、繰り返しになる部分もありますけれども、品川区の幼児教育を支えてきたのは私立幼稚園だと考えておりますので、今後もさまざまお話を聞いて、東京都と区と、できることの役割分担をよく確認して進めていきたいと考えています。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"私は３４ページ、特別区民税についてお聞きしたいと思います。政策についてなので、財政課にお聞きします。特別区民税が約１０億円増えていると。理由は品川区は人口が増えている、そしてとりわけ所得が高い納税義務者が増えているというようなお話でした。そして、この特別区民税が増えたのは、区の事業により生まれたものなのでしょうか。２点についてお聞きします。","respondent":"秋山財政課長","answer":"委員のご質問ですけれども、特別区民税につきましては、納税義務者の増ということでご説明をしています。その納税義務者の増が、いかなる理由によるものかというご質問だと思います。これは品川区の努力というものももちろんあります。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"さて、その一方でふるさと納税制度により、区では２０１７年度、１２億円の減収となっています。区では、継続して行財政改革に努めています。そして各事業部もそうですが、節約しつつ、効率的な予算の執行を行っています。各事業部が努力しているわけです。やはり減収を抑えるべきことを考えないといけないのではないでしょうか。それに対して何か抜本的な対策というものは行っているのでしょうか。","respondent":"伊東税務課長、秋山財政課長","answer":"さらに納付しやすい環境を整えるということでクレジット納付等を開始して、民間サイトのホームページ上にも載せてＰＲを行ってきたと。そのようなことで、何とか区のほうに目を向けていただきたいということでやってきたところです。このような制度全体に対しては、都と連携をしたり、それから区長会を含めて強く主張していきたいと考えています。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"おかしくないですか。各事業部が予算の範囲で一生懸命やって、何とか予算オーバーしないように努力している。そして品川区には、支援を求める方がたくさんいます。累計で相当の額になっているのではないかと思うのですが、それがとまっているならわかります。このようなことをしていいのでしょうか。ちょっとその点について、もう一度ご見解をお聞かせください。そして累計額についてもお聞かせください。","respondent":"秋山財政課長、伊東税務課長","answer":"その話と、各部が歳出のほうを効率的にやっていくということは、あまり連携はしていないと考えております。平成２７年度の流失が約１億１,０００万円、平成２８年度が約６億３,０００万円、そして平成２９年度が約１１億９,０００万円、そのような数字です。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"これだけの額を放置して、私が言ったように努力している、結果が出なくていいのですか。これは放置しているのと同じ、今税務課長が話していました。どんどん増えていますよ。本来なら、区民のために使うべきお金を毎年放出しているのです。１２億円。我々は訴えているのですから。だけれども国の制度がどうのこうの。では、その制度に対して、こちらもやるべきことはやらなければいけないのではないですか。","respondent":"秋山財政課長","answer":"ただし、返礼品競争であるとか、そういうふるさと納税の半分以上お返しするような返礼品競争にくみするつもりは全くございません。こういう中で、ふるさと納税をどうしていくのかというのは、国に対しての制度の変更であるとか、そういうことを求めているです。","id":"exchange-154"},{"speaker":"須貝委員","kind":"意見","question":"私はもっと税金というものをしっかり捉えて、区も真剣に闘って、一緒に返礼品競争をやるべきだと思います。国に対する訴えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-155"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは１０６ページの特定健康診査等事業費についてと、５８ページの予防費、定期予防接種についてお伺いします。それと、この把握をされている中で、どのような取組みをして、いわゆる医療費の削減に向けて努力をされているのか、お知らせいただきたいと思います。５８ページの定期予防接種ですが、いわゆる子宮頸がんワクチン予防接種についてです。","respondent":"三ッ橋国保医療年金課長、舟木保健予防課長","answer":"そこで実際には、指導については委託しているのですけれども、栄養士であったり、また保健師であったりが、その個別の対応をしております。子宮頸がんワクチン予防接種についてお答えいたします。現状も積極的な勧奨については差し控えているような状況です。","id":"exchange-156"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これを良しとするか悪しとするかは別としても、実際に今行われていて、本当に自治体としても多くの歳入マイナスが出てしまっているのですから、これは本当に、先ほどほかの委員からもお話がありましたけれども、真剣に考えていかなければいけないのではないのかと思いますので、その点は答弁は要らないですが、ぜひそういったものも含めて、特定健診なども活用して。","respondent":"三ッ橋国保医療年金課長、舟木保健予防課長、大関教育総合支援センター長","answer":"特に今回、来年度に関しましては、早得キャンペーンなども実施しておりまして、魅力的な健診、この特定健診というものを魅力的なものとして。改めてその対象者への対応等については検討してまいりたいと思います。がん教育につきまして、学校では取り扱っておりますが、子宮頸がんワクチンまでは踏み込まずに、健康教育の中でがんについても取り扱うという範囲です。","id":"exchange-157"},{"speaker":"石田（し）委員","kind":"意見","question":"そのかわり判断については最終的にはご自身、またご家庭で判断をしていただくというふうにはなるかと思いますが、ぜひその辺はしっかりと教育の現場でも行っていただければなと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-158"},{"speaker":"安藤委員","kind":"質問","question":"私から４９ページの基金積立金など、最終補正予算全体について伺いたいと思います。歳入の部分を見ますと、当初予算に比べて特別区民税が約１０億円、財調も５億円増額補正となりました。さらに繰越金は約１７億５,６００万円増額補正です。これらを合わせると約３２億円余となりますが、これらは当初予算に比べて新たに３２億円、区で自由に使える財源が増えたということでよろしいのか伺います。","respondent":"秋山財政課長","answer":"繰越金につきましては、これは既に１０月の決算特別委員会等でもご認定いただいておる実質収支額が、こちらのほうに入ってくるというものです。","id":"exchange-159"},{"speaker":"安藤委員","kind":"質問","question":"これは一般財源に入ると思うので、区で自由に使える新たな財源が増えたということでよろしいのですかと伺いましたので、後で聞かせてください。それと繰越金ですが、つまり黒字分が当初予算から最終補正で１７億円余増えて４４億円余となった、その要因は何でしょうか。効率的な執行とは何なのか伺います。繰出金の更正減額はそれに当たるのでしょうか。伺いたいと思います。","respondent":"秋山財政課長","answer":"したがいまして、繰越金については、この繰越金の補正額につきましては、補正額の１７億５,６５９万３,０００円に意味があるというよりも、補正後の金額４４億８,７５５万７,０００円が昨年の実質収支と同じになるとご理解をいただければと思います。","id":"exchange-160"},{"speaker":"安藤委員","kind":"質問","question":"効率的な執行というと、何か、ああ、すごい良いことかなというように聞こえてしまうのですけれども、伺ったのは、先ほど、例えば各特別会計繰出金を更正減額しているのですが、こういう一般会計からの繰出金を減らすということは、当然国保料が上がったりとか、そのようなことになるわけですが、それは効率的な執行に当たるのですかと伺ったので、伺わせてください。伺います。","respondent":"秋山財政課長","answer":"これも特別会計のほうの歳入歳出がありますけれども、歳出のほうでそれぞれの会計において、一般会計からの繰入金というのは、そちらの差額を補填するという性格のものですから、特別会計のほうで効率的な財政執行を行ったがゆえに。","id":"exchange-161"},{"speaker":"安藤委員","kind":"質問","question":"特別会計のほうで効率的な執行をしたということでございましたけれども、２つ目の質問です。この３２億円新たにできた一般財源のうち、歳出のほうを見ると２１億５,０００万円を基金積立金に大幅追加しているのです。かなりこれの基金の積立てに充てたということなのですかと伺ったので、もう一度お伺いします。","respondent":"秋山財政課長","answer":"いわゆる事業の効率化により減額をする補正のトータルが６３億円、それから増額の今回の補正による増減額は３６億円余。","id":"exchange-162"},{"speaker":"安藤委員","kind":"質問","question":"ですから、今答弁されたように積み立てているということなのです。私は、こうしたお金というのは、今の苦しい区民生活や地方自治体の役割に照らせば、基金の積み立てに充てるのではなく、待機児童の緊急対策ですとか、中小零細企業の支援策、あるいは障害者などの福祉の改善など、住民福祉向上の施策に使うべきだと思うのですけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"したがいまして、今この段階で最終補正をしておりますけれども、それ以前に必要な福祉の財源であるとかというものには、必要な額は入れていると考えております。","id":"exchange-163"},{"speaker":"安藤委員","kind":"質問","question":"二次募集の結果は３月１５日ですけれども、この最終補正をしたとしても９５５人です。この最終補正でこの４月、区が言う待機児童はゼロになるのですか。その見込みについて伺いたいと思います。少なくともとりわけ深刻な、認証保育所にも入れなくて、４月入園再申請も諦めてしまうような子ども、これはゼロにできるのでしょうか。この対応を十分にやっていると言えるのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ただ、今年度から企業主導型が始まりまして、４月には１０園になると聞いておりますので、一定、企業主導型のほうで受け入れがかなえば、もちろんマッチングの問題、地域的なマッチングの問題はありますけれども。","id":"exchange-164"},{"speaker":"安藤委員","kind":"質問","question":"私はやはりこの最終補正の姿勢を問われていると思うのです。区長の公約は待機児童ゼロですから。ですから、ゼロに近くなればいいという問題ではないわけです。私が伺いたいのは、二次募集発表は３月１５日ですけれども、もう既に一次の発表は２月２０日です。もう大分前です。最後の１人まで不承諾になった方々に対して手だてをとる、そのような姿勢があるのかどうか、しっかりと伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ただ枠が、先ほども申し上げたように新しい企業主導型なども実施しておりますので、そういう意味ではこれ以上、今の時点で特に対策をとる考えはございません。","id":"exchange-165"},{"speaker":"安藤委員","kind":"質問","question":"財源がたっぷりあるのです。基金を積み増すだけの余裕があるわけではないですか。それを、私が聞いたのは個々の状況に対応してほしいと聞いているのです。このような緊急対策を品川区はやるべきなのではないでしょうか。私が伺ったのは、その個々の状況に対応してほしい。不承諾を出した方全てに責任を持つ、そうした姿勢があるのか、そうしたことを行うつもりがあるのか伺ったので、お答えください。","respondent":"大澤待機児童対策担当課長","answer":"そのほかに４月から定期利用保育ということで、不承諾者が多い１歳児については１年間、最長１年でお預かりするという対応も予定しておりますので、十分に対策としてはとっていると考えております。","id":"exchange-166"},{"speaker":"安藤委員","kind":"質問・要望","question":"その緊急対策でも足りないというところなのです。最後の１人まで責任持っていただきたい。最後に態度表明いたしますが、品川区一般会計補正予算に対しては反対いたします。区民サービスの削減や負担増を効率的な財政運営と合理化し、増やしたお金は基金にため込むのではなく、福祉の充実のために充てるべきです。反対いたします。以上、３会計に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"こんの委員","kind":"質問","question":"受託事業ですので、直接品川区というところでは、なかなかできることが限られているかもしれないですが、更正減額ですから単純に受診の方が少なかったと、このように見るのですけれども、減の要因は何でしょうか。それから受診率の推移ですけれども、事務事業概要を少し見させていただいたときに、４３％前後で推移をしている。この数字をどう捉えていらっしゃいますでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"一方４３％という、この受診率ですが、５０％を目標として、区としては対応してまいりたいと思っています。この４３％は若干まだまだ少ない、到達はできていない状況ですけれども、日々推進してまいります。","id":"exchange-168"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたことを考えたときに、この５０％まで持っていく、これはやはり努力していただきたいなと。そのためには何か今施策があるのでしょうか。後期高齢者の方々に健康診査を受けていただく、ご自分の健康状態を知っていただいて予防をする、あるいは治療する、そういうところにつなげる施策が必要と思いますけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"今までも受診勧奨というものは、受診率向上に向けては実施しておりました。今回、平成３０年度に向けては、国保もそうなのですけれども、早得キャンペーンというものを実施していく予定です。こちらも５月から８月に向けてのキャンペーンを実施する予定です。","id":"exchange-169"},{"speaker":"こんの委員","kind":"意見","question":"グループホームの開設にあたって、月に一、二件ご相談があって、ですが、なかなか整備に結びつかないという現状だということです。ご相談される民間の方々がどういったところで踏み切れないのか、どういう課題があるのか、その辺の、こちらの区として手当てをしてさしあげるものがあるのか、こちらもちょっと現状をお願いいたします。","respondent":"大串福祉計画課長","answer":"それ以外にもさまざまな近隣の関係ですとか、いろいろなご事情があるというふうに伺っております。なかなかそこに対して区のほうでというのは、今現状持っております、こういった補助のスキーム、これ以上のといったところはちょっと難しいのかというふうに考えているところです。","id":"exchange-170"},{"speaker":"こんの委員","kind":"質問・要望","question":"開設するにあたっては区のご努力も、また民間の方々の思いもあるのですが、引き続き鋭意ご努力をいただいて、整備にあたっていただきたいと思います。すまいるスクールですけれども、すまいるスクールの教室、いろいろな地域の方の力をおかりしての伝統授業などの教室、いろいろなサークルをされていると思いますが、その地域の方々にお支払いをしている謝礼金の金額の設定の考え方をお聞きしたいと思います。","respondent":"高山子ども育成課長","answer":"その補助となる方には５００円という形で、金額のほう設定しています。","id":"exchange-171"},{"speaker":"こんの委員","kind":"質問","question":"補助の方には５００円ということで、正規の方には１,５００円という形で出されています。この講師の方々は、その学校の周辺から来る方ばかりではないというふうに理解をしております。そうしたときに、やはり交通費というところを考えると、補助の方の金額というのはもう少しあってもいいのかなと、このように考えますが、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"先ほど申しましたように、本来無料でもやっていいといった方々の善意の中で、この事業を運営しておりますので、今後の課題とさせていただきたいと存じます。","id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"執行率のところを伺いたいと思います。例えば、平成２９年度当初予算繰出が１２０億円ぐらい出そうと思っていたけれども、ここでいくと特別会計の繰出金は１２億円ぐらいの更正減額があると。予算を決定したと。もちろんわかっていますよ。６月、９月、１２月の補正というのがあるのはわかっているけれども、この最終補正のときにどういうお考えでこれが出てくるのかということを改めて伺いたいと思います。","respondent":"秋山財政課長","answer":"１つは年度、もう最終補正を編成するのが年の暮れ以降になりますので、それまでの時点でどのぐらい進捗しているのかですとか、そこから先の見込みを見た上で、最終的にどこまでこれができるのかというところで考えておりますので。","id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は９５％、９６％というのは非常に誤差の範囲で、よくやられているなという理解をしております。今回も８０億円、防災が１５億円ぐらいあるからちょっと置いておくと、８０億円ぐらいは繰り入れしますと。ためたけれどもどうするのか。このようなことをもう少し見えるようにしてほしいと思っています。その辺はどうお考えか。この辺の見え方はどう思われるのかということをお聞きします。","respondent":"秋山財政課長","answer":"最終の見込みですけれども、こちらはまだどうなるかというのはなかなか今の段階でお示しするのは難しいのかなと考えていますが、そういうことです。","id":"exchange-174"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"申しわけありません。区の職員だけで考えたとは思わないけれども、いろいろな方を入れて、先ほどのライザップの話ではないですが、いろいろな考えを持って、いろいろな対策を打っていくということは、私はこれはありだと思っていて、いろいろなイベントを組むことも１つ、その中に使えるものをやっていくということも１つの考え方と思うので、ここの考え方だけ教えていただきたい。","respondent":"柏原企画調整課長","answer":"そこで生まれてくるところをどういった形で区民の方とか、ふるさと納税をしようという方に気に入ってもらえるかということを種々、いろいろな部署、いろいろな方々と検討しながら、返礼品競争という、そのような特化したところではなくて。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/314416?Template=document&Id=1072#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":127561,"voices":410}},{"id":"h30-20180306-3","meetingId":"h30-c-budget","date":"2018年3月6日","dateIso":"2018-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","topics":[{"id":"topic-01","title":"平成３０年度品川区一般会計予算","agenda":"平成３０年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私からは、６５ページ、八潮北公園スケートボート場についてお伺いしたいと思います。昨年１１月１９日にオープニングセレモニーがございました。やはりこのスケートボード場については、前々からいろいろ要望があったということで、スケートボード場が開園して、スケートボード愛好者が今現在も利用し、盛り上がっているというところであります。そこでお聞きいたします。よろしくお願いします。","respondent":"池田スポーツ推進課長","answer":"１１月２０日にオープンいたしました八潮北公園のスケートボード場の登録者の人数です。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区内の小学生が５９人、中学生が９３人に対して区外の中学生以上の人数が１６５名いるということで、今現在、区外の方が倍近いのですけれども、区外からスケートボードの愛好者が来ているということについてのお考えといいますか、その辺のところをお聞きしたいと思います。","respondent":"池田スポーツ推進課長","answer":"区外の方については、中学生以上の方で１６５人が登録されているところですけれども、主に大田区の方、それと、ちょっと遠いところでは川崎の方ということで、八潮北公園に近い区外、都外の方が登録されていまして、皆さん。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこで、日本スケートボード協会のほうにも要望というか、お願いで、貸出をぜひしていただければと考えています。これは要望で終わらせたいと思います。今月、３月２４日の土曜日、１３時から１５時まで、定員が先着２０名ということで、同じくスケートボード教室をやると思うのですけれども、今現在の、申し込み状況をお知らせいただければと思います。","respondent":"溝口公園課長","answer":"３月２４日の応募状況です。これにつきましては、まだ開始したばかりで、これから多分、応募人数が増えていくような形で予想しております。若干名、問い合わせと応募があるというふうには聞いておりますが、まだ人数等は確定をしていないというのが現状です。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこで、江東区の有明で行われる競技の中にはＢＭＸがあるのです。ほかの委員からも第１回定例会の一般質問のときにＢＭＸの使用について要望がありましたが、品川区として、今後どういうふうに問題点を改善していくのか、そこをお知らせいただきたいと思います。","respondent":"溝口公園課長","answer":"ただ、やはり当初、スケートボード場としてオープンしておりますので、スケートボードの利用者をしっかり守りながら、さらなるスケートボード場の活用、そういったものも行っていきたいというふうに考えているところです。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"区広報では３月１１日の日曜日、９時から１１時まで、この八潮北公園は休場するということですけれども、これはＢＭＸの利用に関する要望を踏まえて、約２時間休場して、施設の調査をするということで、具体的な調査内容を教えていただければと思います。","respondent":"溝口公園課長","answer":"そういったところで、実際に試走していただいて、危険な箇所がないか、また、当施設が今のまま安全に使えるのか、そういった視点で確認をしていただきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からも、ただいま質疑がありました６５ページの八潮北公園スケートボード場について、それと１１５ページの生活支援付住まい確保事業補助金についてお伺いいたします。八潮北公園は、今、状況を伺いましたが、利用状況についてお伺いしたいと思います。土日、また平日、それぞれ利用されていると思うのですが、特に平日の利用状況がどうなのかということをお伺いしたいと思います。","respondent":"池田スポーツ推進課長、溝口公園課長","answer":"１１月からこれまでの利用状況ですけれども、平日で８４５人、休日については４３４人ということで、１週間は５日間が平日で、２日間が土日ということを考えますと、この２日間の休日で４３４人ということで、平日の８４５人に比べると。今回の試走にあたりご協力いただく団体になりますが、公益財団法人日本自転車競技連盟の方からご紹介いただきまして、一般社団法人全日本フリースタイルＢＭＸ連盟にご協力をいただいて試走をするものです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"あわせて、高齢者の住宅支援補助金では、厚生労働省の「低所得高齢者等住まい・生活支援モデル事業」の補助金や、また、これまで我が会派が求めてきた居住支援協議会を立ち上げることで、受け取ることができる国土交通省の「重層的住宅セーフティネット構築支援事業」の補助金があると思いますが、それらを使わない事業とした理由をお伺いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"国土交通省の新しいセーフティネットの補助金につきましては、住宅の確保と生活支援がリンクしていないなどの課題がございまして、活用は難しいと考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"これから開始される新規事業の内容について少し教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"新規事業の内容ですが、低所得者の高齢者が品川区でいつまでも暮らし続けるために、対象としましては、住宅あっ旋の対象のうち、特に支援が必要な方を社会福祉協議会の生活支援サービスで、長く居宅生活を送っていただけるということが目的の事業です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"今既に品川区の事業で行われております高齢者地域支援課の住宅あっ旋事業があります。条件としては、低所得者支援のため、年間収入が約２５７万円以下の方が利用できるというものですが、この事業は、この新規事業の中に吸収されると考えていいのでしょうか。そうなると、新規事業の対象も年間収入が２５７万円以下の方となるのかを確認させていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"１つは、高齢者住宅のあっ旋制度で解決される方は、そちらをお使いいただきます。一方で、入居後の生活にご不安がある方については、新規事業でということになります。ですから、所得に関しましても、委員ご指摘のとおり２５７万２,０００円以内の方が対象になってあります。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後新しく始まる事業は、生活支援の見守り等も含まれております。高齢者の中には、所得が２５７万円以上でもお困りの方もいらっしゃるので、この所得については、今後、ご検討をいただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"７５ページの情報公開手数料に関してお伺いしたいと思います。この理念、私も本当に好きな文章であります。一方区では、情報公開手数料として３００円いただく、受益者負担ということで品川区はずっと手数料を徴収しておりますけれども、これは区民憲章に反していると思うのです。私は無料にするべきだと考えていますが、その点についての答弁をお願いしたいと思います。この点についての考えも伺います。","respondent":"中元広報広聴課長","answer":"情報公開手数料のお尋ねです。こちらにつきましては、従来から申し上げているところですが、やはり一部の事業者からの大量請求によるところが大きいところですので、やはり受益者負担という考え方で、こちらは手数料をいただいているという考え方です。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"区民憲章の理念に反しているのではないかというところの答弁がありませんでしたので、ぜひお願いしたいと思います。この間、大量請求を理由としているのであれば、どの程度そういう状況があったのかの実態もあわせて伺いたいと思います。そういう点についての認識を伺いたいと思います。","respondent":"中元広報広聴課長","answer":"やはり区の職員が大量請求の対応をするに当たりましては、時間を必要とするところですし、区職員が本来行うべき職務に専念できるということも大切なことかと思っているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"今のところは手数料もお払いするわけです。そういう方向に考え方を変えるべきだと思っています。これは区民の知る権利を品川区としてどういうふうに捉えるかという問題だと思いますので、ぜひ改めるべきだということを強調したいと思います。そしてどこに何を目的で行ったのか、どのような内容で懇談なり要請をされたのかということについて、なぜ保管をしていないのか、その辺について伺いたいと思います。","respondent":"中村都市計画課長","answer":"タウンミーティングに関連してですけれども、一般論になり恐縮ですけれども、個人も含めた区の全ての動きについて公開するための文書を残しているというものではございません。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、これはきちんと保管をするべきだと考えていますし、ぜひ改善をしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"私からは、４８ページの特別区たばこ税、３０億６,２８０万円、６３ページの歴史館使用料について、時間がありましたら、１４７ページの歴史館講座等について伺いたいと思います。４８ページの特別区たばこ税についてです。小中学校や医療機関、福祉施設、官公庁について、どのように整備されているのか、あわせて伺いたいと思います。","respondent":"川島健康課長","answer":"今、委員ご説明のございました現行の健康増進法につきましても、多数の者が利用する施設を管理する者は、受動喫煙を防止するために必要な措置を講ずるよう努めなければならないという趣旨がありますので。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"先ほどお答えいただいた中で、本区の庁舎にある喫煙所について伺いたいと思うのですけれども、現在、区役所内に何カ所ぐらい喫煙場所が設置されているのか、そして今後どのように変わってしまうのか、その流れについて伺いたいと思います。禁煙外来についてなのですけれども、利用者はどのくらいおられるのかと思いまして、その点についてもあわせて伺います。","respondent":"川島健康課長、立川経理課長","answer":"禁煙外来助成の利用状況ですが、今、３０数件ほどご登録いただいております。３月にもう少し頑張って予算額の５０人にいけばいいなというふうに考えているところです。現在、庁舎の喫煙スペースにつきましては、７カ所あります。今後ですが、国の法律の関係、東京都の条例の関係、その辺、詳しくわかり次第、適切に対応していきたいというふうに考えているところです。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"喫煙される方から、残してほしいという意見もありまして、財政としても、約３０億円、昨年よりも６,０００万円ぐらい減っているのですけれども、３０億円という大きなお金です。撤去するかどうかは今後の流れなど、いろいろありますが、ぜひご検討いただきたいと強く要望します。","respondent":"菅生活安全担当課長","answer":"たばこの路面表示シートにつきましては２種類ございまして、地域美化推進地区と、それ以外と２種類というふうになっております。路面に表示してありますシート、これは地面に張ってありますので、どうしても劣化してしまいます。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"わかりました。エリアについてなのですけれども、例えばステッカー１枚について何m2とかではなくて、その近辺は吸ってはいけないということなのか、その辺についてお聞きしたかったのですけれども、よろしくお願いします。","respondent":"菅生活安全担当課長","answer":"路上喫煙防止条例につきましては、これは区内全域が歩行禁止ということで努力義務になっております。その中でも大井町ですとか五反田ですとか大崎ですとか、そういった５地区につきましては路上喫煙禁止・地域美化推進地区ということで、全く吸ってはいけないです。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"６３ページの歴史館使用料についてです。初めに、利用者について質問をいたします。書院４５回、講堂５回、来館者６,２４０人とありますが、それぞれ現在どの程度の利用をされているのかお知らせください。","respondent":"鈴木文化観光課長","answer":"講堂につきましては、主に歴史館の事業で使うことが多くなっておりますので、こちらのほうも件数としては約６０件で３,０００人ほどの方が利用されている状況です。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"書院については、年間５０から６０というふうな形でおっしゃっていたので、この予算書の４５回というのは、もうちょっと目標を高くしていただければと思うのですけれども、その辺について伺います。そこで、この茶室についてですが、いつごろ利用が可能になるのでしょうか。今後、復旧される予定はあるのでしょうか。お知らせください。","respondent":"鈴木文化観光課長","answer":"今年度、改修について関係部署と検討したのですが、実際に使えるようにするためには、建て直すのと同じぐらい経費がかかるということが判明いたしまして、今後、歴史館自体の機能強化、それから観光での活用等も踏まえまして、今後。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"お茶に関しては、私もやっているものですから、いろいろとありまして、よろしくお願いします。今後、東京２０２０大会を控える中で、多くの方が来館されることも予想されます。改めてアクセス方法や駐輪場の整備、駐輪場といってもシェアサイクルも進んでいる中で、そうした整備について、今後、ニーズに合った施策を進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"藤原委員","kind":"確認","question":"これも確認なのですけれども、社会福祉法人に対しては利子をとっていないのでしょうか。私は違和感がありますが、お考えをお伺いします。これは平成２９年度もというか、平成２９年度はいつも以上に余剰金が出るという見込みだったからこういうふうにしていると思うのですけれども、そのことの確認と、どうして毎年このように膨大な繰越金を計上しなければいけないのかお伺いします。","respondent":"寺嶋高齢者福祉課長、山崎商業・ものづくり課長、秋山財政課長","answer":"社会福祉法人の貸付金返還金につきましては、主に福祉施設の建設に伴う資金を用意する必要があるということで。商店街のほうは１０％の支出ということになりますが、補助率が大きいので、商店街に対する先ほどの補助金が出るまでのつなぎということで、今回。これにつきましては、前年まで２５億円ということで予算を立てておりましたけれども、１つは、財政規模がこのところ。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"今回、歳入全体で１００億円増加していますね。よく見ると、繰入金が１００億円増えているのです。これは年度の終わりに基金からそれほど出さないで、さらに積み増す結果になるのでしょうか。そのことの確認をしたいと思います。","respondent":"秋山財政課長","answer":"この差額は、歳入を大きく見込むというのは、なかなか財政的にはしがたいものがあります。入ってこないものを入ってくるというふうに予算を立てることはできませんので、歳入はどうしても堅めに見ざるを得ない。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"最後に、８３ページの国保でお伺いしたいのですけれども、昨日も国保について伺ったのですが、国保の制度が変わるということで、国保の課題があると思うのですが、この課題に対する制度改革があると思うのですが、その辺は区がどういうふうに考えているか教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"引き続き、皆様へのご協力、ご理解を進めてまいります。区といたしましては、区民の皆様の健康や命を守る国民健康保険制度の運営につきまして、国保医療年金課一丸となって、あと１カ月に迫ってまいります平成３０年度からの国保制度改革を進めてまいります。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に要望になってしまうのですが、この国民皆保険制度は、誇れる制度だと考えています。高額医療も含めて、国民皆保険制度を、守っていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"私からは、８５ページ、１３款国庫支出金、１項国庫負担金、７節障害児通所給付費、８８ページ、１３款国庫支出金、２項国庫補助金、２目民生費補助金、１節地域生活支援事業、１３６ページの１７款繰入金、１項基金繰入金、８目財政調整基金繰入金について伺います。先に財政調整基金の繰り入れの考え方について伺います。財政調整基金条例を確認させていただきました。基金の設置は大変もっともと考えます。","respondent":"秋山財政課長","answer":"財調基金のお問い合わせです。財調基金は、委員ご指摘のとおり、年度間の財源の不均衡の調整ということを設置の目的に掲げしています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"意見","question":"２０１０年度以降、毎年、特別区民税はずっとプラスの補正をしております。しかし、そのときには、政策的な目的を明確にして、こういう状況で、これに必要だからこういうふうに充てるということが、項目ではなくて政策的なものが明示されて、それでこの委員会の議論に付して、そうやってみんなで決めていくべきなのではないかと思いますが、その点について、もう１回お考えをお聞かせください。","respondent":"秋山財政課長","answer":"一般財源も全て充当事業ということを示すとなりますと、これはなかなか難しいものであり、あまり現実的ではないかなというふうに考えてあります。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、そのときには目的を明確にして、きちんと政策的な議論がされるべきではないかということを申し上げておりますので、これについては要望にとどめますが、ぜひ明確な基準を持っていていただきたいというふうに思います。次に行きます。８５ページの障害児通所給付費です。報酬改正の趣旨、新旧の表を見たのですけれども、私、理解できなくて、その趣旨をどのように理解したらいいのかも教えてください。","respondent":"中山障害者福祉課長","answer":"２点のお尋ねです。放課後等デイサービスの仕組みがどういうふうに変わるか、報酬体系がどう変わるかです。１点目は、やはり障害の重いお子さんに対して支援を手厚くするということがあります。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"利用者の中で障害の重い子を重視するというのは理解できるのですけれども、これを利用している子どもたちのことを考えると、軽度だからこういうケアがなくて済むと考えるのは、ちょっと難しいのではないかということと、それから、環境の変化に対応するのが難しいお子さんが多いということを考えると、利用者への急な影響は避けたほうがいいと思うのですが、その辺のことはどのようにお考えか教えてください。","respondent":"中山障害者福祉課長","answer":"今回、放課後等デイサービスを国が報酬改正するに当たっては、より専門的な対応をできる、やはり療育目的ということになりますので、それをきっちりやる事業所に手厚くというのが本来の趣旨だというふうに聞いております。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。伺いたいのは、このにじのひろばについて、これは伝聞によるもので調べていないのでごめんなさい、その範囲で聞かせていただきますが、年間の登録料があるというふうに聞いたのですけれども、それは事実なのでしょうか。登録料という名目で伺ったのですけれども、あるとしたら、どういう性格のものなのか、それも教えてください。","respondent":"中山障害者福祉課長","answer":"年間登録料といたしましては、月々の請求の郵券、それから銀行振替の手数料、それの１２カ月分を中心としつつ、あとはシステムの運営のための経費を乗せさせていただき、現在、年間の登録料ということで５,０００円をいただいているところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"登録料というものなのでしょうか。ちょっと今のお話で伺うと、登録というのと何か、利用料に上乗せになるものなのか、登録という文字の意味、いわゆる名称の問題ですけれども、どうなのかなというふうに思います。","respondent":"中山障害者福祉課長","answer":"そのほか低所得の方が月額４,６００円、それ以外の方も３万７,２００円を上限としています。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、課長もおっしゃいましたけれども、やはり登録料というより事務手数料と考えると、軽減措置が必要な方たちにとって、毎年５,０００円ということですから、大きい負担ではないかというふうに思います。必要なものは自己負担ということがあってもいいかと思うのですけれども、その辺の全体の整合性をぜひ考えていただきたいと思うのですけれども、その点について見解を伺います。","respondent":"中山障害者福祉課長","answer":"この年間登録料につきましては、少しこちらのほうでも考えさせていただいて、所得制限に応じたいただき方になるのか、料金の見直しなのか、検討させていただければと考えています。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。さっき名称の問題と言いましたけれども、やはり、多くの方は名称で意味を受け取るので、もし利用料ということであれば、きちんと軽減措置の中に入れていただきたいし、どういう意味の料金なのかということは、ぜひ明示して皆さんに納得して使っていただけるようにしていただきたいと思います。これは要望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"私からは、８９ページ、シティプロモーション推進経費ほか３事業、１１７ページの予防接種費ほか６事業、１５７ページ、議会運営費についてをお伺いいたします。１点目は、予防接種費ほか６事業についてお伺いいたします。出生時から何歳くらいまで管理可能なのでしょうか。定期予防接種だけではなく、任意予防接種やインフルエンザなどの流行時期に合わせて管理することはできますでしょうか。","respondent":"舟木保健予防課長","answer":"今回、新たにアプリを導入することで、接種のスケジュールの自動調整やプッシュ通知等の機能が追加されます。導入時期につきましては、４月以降、詳細を検討してまいりますので、７月ごろを予定しております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"接種間隔の間違いですとか、接種忘れを防止するなどの効果が期待できると考えているのですけれども、予防接種とともに、生後４カ月児、１歳６カ月児、３歳児の健康診査ですとか、歯科健診などの健康診査のスケジュールなどもあわせて管理していくようになるかと思うのですけれども、こちらの一括の管理の仕方について、もしありましたら、区のお考えをお聞かせください。","respondent":"舟木保健予防課長","answer":"健診スケジュールの一括管理についてですが、現在、乳幼児健診などにつきましては、事前に個別通知を発送しております。予防接種、健診と合わせたその後の健康管理につきましては、担当している所管とも今後このアプリについて相談してまいりたいと思います。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"２点目は、シティプロモーション推進経費ほか３事業についてお伺いいたします。第５５回の宣伝会議賞に品川区が参加しているかと思います。こちら、受賞したキャッチフレーズと応募総数、一次通過作品は、コピーライターの方ですとか、プロの広告クリエーターの方が審査されていると聞いておりますけれども、こちらの一次通過作品数をお聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"応募総数が７,０５５作品、うち一次審査を通過した作品が８２です。それから、いわゆる品川区賞としてこちらのほうで授賞を決めたキャッチフレーズですが、「東京の玄関というよりリビング」というようなキャッチフレーズを選ばせていただきました。","id":"exchange-036"},{"speaker":"横山委員","kind":"意見","question":"こちらは私も『宣伝会議』で見せていただいたのですけれども、課題のところに、「いっぱいある魅力をイマイチ伝えきれていない品川区をエッジの効いたインパクトのある表現でアピールしてください。面白ければ少々自虐的でも破天荒でも構いません。もし少々自虐的ですとか、破天荒、エッジの効いた思わず笑顔を誘うようなキャッチコピーがありましたら、一部ご紹介ください。","respondent":"木村報道・プロモーション担当課長","answer":"「私たちは住み続けたいと答えなかった人が１割もいたことを反省しています」、これはどちらかというと、ちょっと自虐的なほうになると思います。それから、「東京に疲れました。品川区に帰ります」というようなこともありました。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"「わ！しながわ」のキャッチコピーやロゴと合わせて、受賞作品は、今後、どのように展開していくのでしょうか。品川区シティプロモーションの特設サイトに、一次通過作品の掲載をすることによって、応募者の方々にさらに品川区の魅力を感じていただくことで、繰り返し発信をしていただく機会にもなると考えますが、いかがでしょうか。続けて３点目も入ります。議会運営費についてお伺いいたします。","respondent":"木村報道・プロモーション担当課長、久保田区議会事務局長","answer":"ご提示いただきました特設サイトへの作品の掲載につきましても、４月以降になりますけれども、随時進めていきたいと考えております。もしこれに違反した場合の対応ですけれども、同じ規則の第７条に、規則違反者に対する措置ということで、「傍聴人がこの規則に違反したときは、委員長はこれを制止し、その命令に従わないときは。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"キャッチコピーの件については、ぜひ進めていただけたらと思います。傍聴規則のほう、ありがとうあります。品川区議会委員会傍聴規則の遵守を要望いたしますが、一言お願いします。","respondent":"久保田区議会事務局長","answer":"私ども、傍聴される方には、傍聴券をお渡しする際に、こういった規則を守ってくださいということをお願いしていますが、これからも徹底してやっていきたいと思います。","id":"exchange-039"},{"speaker":"つる委員","kind":"確認","question":"１５１ページ、公園駐車場運営事業納付金、１５７ページ、本会議場等バリアフリー化、８５ページ、児童扶養手当給付費について伺いたいと思います。納付金の件ですが、まず最初に確認で、この納付金が入る法令等の根拠、また仕組み、そして運営事業者がどこなのか、それを教えてください。","respondent":"溝口公園課長","answer":"これにつきましては、都市公園法第５条に、公園施設の設置管理許可という項目があります。この制度を使いまして、有償の運営を民間事業者に委託しているものです。実際、今現在、民間駐車場を運営しているのは、タイムズ２４株式会社が運営を行っているものです。","id":"exchange-040"},{"speaker":"つる委員","kind":"確認","question":"それで、この歳入に関連してなのですが、公園の維持管理にかかる経費、補助金等を除いた経費ですが、区の経費は、歳出を確認すると、一般財源として２０億６,０００万円余あるわけですが、細かく見ていくと、公園そのものよりも、それに付随するウエブの管理とか、その辺のお金も入っていたり、年度によっていろいろ変わってくる、トイレの改修等も入っていると思うのですが。","respondent":"溝口公園課長","answer":"委員ご指摘のように、予算を計上している２０億円余、さまざま改修等により、いろいろ変わってくるところはありますが、傷んでいるところ、そういったものを直しながら公園の維持管理に当たっているものですので、年間ですと、大体２０億円ぐらいが公園全体。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"そこで、国家戦略特別区域法の一部が改正されて、都市公園法の特例を活用して、既に品川区内にも保育園が設置されておりますけれども、先ほど冒頭でご答弁いただいた都市公園法に基づく駐車場以外で民間事業者が収益を上げる事業として取り組んでいることがあれば教えていただきたいと思います。しながわ区民公園内のレストランとか、そうしたものが挙げられると思うのですが、確認の意味で教えてください。","respondent":"溝口公園課長","answer":"そのほかにつきましては、公園内にある自動販売機の一部についても、こういった都市公園法の第５条の設置管理許可を活用して、実際、民間事業者が自動販売機を設置しているといったところもあります。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"区として同制度の活用についてのお考え等があれば教えていただきたいのと、また、活用に際しては、区の関係条例等の改正が必要になるのかどうかという点、公園の今後のあり方等も含めて教えていただければと思います。","respondent":"溝口公園課長","answer":"今回、施設を設置するに当たっては、公園施設の建蔽率、そういったところが条例で定まっておりますので、そういったところをどういう形に設定していくのか、そういったところの条例改正が場合によっては必要になってくると思いますので。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"法律を確認すると、管理許可の期間が１０年から２０年であるとか、面積については２％だったものが１０％増えて１２％になる、こういうふうにしていくと、条例改正が必要になってくるという理解をいたしました。韻松亭は今もありますけれども、そういった経緯がある。ちょうど平成３３年を目指して戸越公園内に体験型環境学習施設ができるわけです。","respondent":"溝口公園課長","answer":"さまざまな観点で、今回の都市公園法の改正に合わせて、さまざまな制度ができておりますので、今後、そういったものも含めてしっかりと公園のあり方については検討していきたいと思っているところです。","id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"今、大きい部分でありましたけれども、細かい部分では、議会より２００９年ぐらいからネーミングライツの提案が各議員からされております。そこで、公園またトイレなどに対するネーミングライツについて、改めて提案をさせていただきたいのと、これまでの検討状況を教えていただければと思います。","respondent":"溝口公園課長","answer":"そういったことも含めて、今後、おもてなしトイレということでトイレ整備を進めておりますので、そういった中でネーミングライツの活用もしっかり検討していきたいと考えているところです。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"今回はたまたま公園ということでありましたけれども、やはり自治体としてもしっかりと税外収入を得ていくということは、今後、法体系を含めて必要な観点の１つかなという部分で、非常に可能性のあるところかと思いまして質問させていただきました。本会議場等バリアフリー化でありますが、この中に議会棟５階のトイレ改修工事も含まれていると思いますが、どのように改修するのか教えてください。","respondent":"久保田区議会事務局長","answer":"本会議場等のバリアフリーですけれども、５階のトイレをだれでもトイレに改修する予定であります。","id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"簡潔に答えていただいて、だれでもトイレへの改修は、非常にいいことかと思います。この前広便座というのは、オストメイトの方が便座に座った状態でパウチ処理ができる便座で、合理的配慮の観点でも、一般便所への設置拡大を進めるべきと私は思っておりますけれども、今回この議会棟の５階トイレの改修工事に合わせて、前広便座の設置をしたらどうかと提案させていただきたいと思いますが、いかがでしょうか。","respondent":"久保田区議会事務局長","answer":"委員からご提案のありましたこういった便座も含めまして検討の項目として入れまして、あと３階の本庁舎のトイレを参考にしながら、関係部署とこれから協議をして詳細を決めていきたいと考えております。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"残りの時間で、児童扶養手当給付金について伺っていきたいと思います。国のほうでも法改正が進み、２０１９年度を目指して、隔月支給にしていくということでありますけれども、今回の当初予算の中に、２０１９年度に開始できるシステム改修費などの財源が確保されていますので、次々年度、確実に実施できるようになっているかどうかということを教えてください。","respondent":"廣田子ども家庭支援課長","answer":"取り込めない場合については、すぐに改修ができるよう平成３０年度中に調整をする予定です。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ２０１９年度にしっかりと対応ができるように、実際、当事者のお母様からもお声をいただいているところでありますので、また、実際に実施した後もしっかりとそうしたお声を窓口として受け取っていただいて、推進していただきたいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"筒井委員","kind":"提案","question":"りんかい線についてです。そして、私、ある会合で、天王洲アイルに来た人、区外の方だったのですけれども、何人かとお話しして、そうした方に天王洲アイルはどうですかといろいろお聞きしたのですけれども、やはりなかなか来ない、行かないというお答えでした。そこで品川区の水辺、天王洲アイルに来ていただくべく運賃の値下げをぜひ提案していただきたいのですけれども、区のご所見はいかがでしょうか。","respondent":"中村都市計画課長","answer":"そのような中で、鉄道事業者の料金に対する認識もあるというところで、今後、引き続き、料金についてご意見があるというのは、区のほうもお伝えはしていますが、料金の設定につきましては、なかなかやはり経営の方法や方針もあると思いますので。","id":"exchange-050"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひこの要望を東京臨海高速鉄道株式会社のほうにお伝えいただければと思います。特別区民税、今年の予算は補正予算を見て比べると控えめになっていると考えられますが、これはふるさと納税が原因だと考えていますけれども、確認として、今年度を含めた過去３年分の推移を確認したいと思います。確認としてお聞きいたします。よろしくお願いします。","respondent":"伊東税務課長、秋山財政課長","answer":"平成３０年度におきましては、減収額として１５億４,０００万円ほどを見込んでいるですので、それがどうしても影響してしまいまして、そのような数字になっているところです。その理由ですけれども、これは地方消費税は消費地に交付することが基本ですけれども、その基準を消費の実態に合わない基準に国が一方的に変えて、大都市部から地方への還流といいますか。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。１０年やっている、ふるさと納税は本当にうまくいっているのですかという話なのです。ぜひとも、今も特別区長会を通じて要望しているかと思われますけれども、さらに徹底して強く見直し、廃止、そうした抗議を行っていただきたいと考えております。やはり区民の方を巻き込んでＰＲを行っていただきたいと考えております。それについてご意見、ご所見はいかがでしょうか。","respondent":"秋山財政課長","answer":"これについては、都とも連携しながら、いわばこれは基本的な税の話ですので、区としても強力に主張していきたい、また、区民へのＰＲも、今後、いろいろなチャンネルを通じて行っていきたいというふうに思っています。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"７３ページの区営住宅、１３５ページの地所賃貸料、旧第一日野小学校跡地について伺います。区営住宅です。そこで質問いたします。２０００年の都区協議では、おおむね１００戸までの規模の団地を移管対象とし、元芝以外に区内４つの都営住宅が移管対象団地として挙げられましたが、移管を受けるべきだと思いますけれども、いかがでしょうか。対象となる４つの団地それぞれ伺いたいと思います。","respondent":"長尾住宅課長","answer":"そういった建設当時の経緯や今後の建て替えの時期の活用の方針など、そういったことを総合的に考慮して、慎重に検討する必要がある対象になっていると考えております。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"私は、人権保障の観点から、また、住み続けたいまちしながわと言うならば、区内の都営住宅は１戸も減らすべきではないと思います。移管を受けるべきです。元芝アパートの入居者には都がほかの都営住宅への移転を今後調整すると伺っているという答弁だけでした。伺いますけれども、これは区内で都営住宅戸数が減るのは問題ないという認識なのでしょうか。伺いたいと思います。","respondent":"長尾住宅課長","answer":"公営住宅につきましては、公益的な観点のもとで、都と区が役割を分担して実施している施策となっております。こういった観点から、都内の都営住宅戸数が変更になるものではない状況です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"今住んでいる方が区内の都営住宅に移るということ自体は、万が一廃止になってしまった場合に、それは当然やるべきことだと思いますし、私が伺っているのは、住宅政策を預かる品川区として、区内の公営住宅である都営住宅の戸数が減るということについて問題と感じていないのですかと伺ったので、きちんとお答えください。","respondent":"長尾住宅課長","answer":"繰り返しになってしまいますが、都は都の役割のもと、公益的な観点に基づいて必要な公営住宅の建設・維持を行っていると伺っております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"都の役割があると、都のやることだから区はあずかり知らないということだと私は思います。それは大問題ではないですか。区内で区民の方が入れる公営住宅の戸数が減ることに対して、何も問題意識を持たない、問題だと思わないというのは問題ではないのですか。もう一度伺います。","respondent":"長尾住宅課長","answer":"繰り返しになってしまいますが、都は都の役割のもとで都営住宅の建て替え、維持を行っており、区は区で区営住宅の維持管理、または必要なタイミングでの建て替え等を行っており、適切に公営住宅を供給していると考えております。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"都営住宅といった公営住宅があれば助かる、あるいは貧困から抜け出せる、あるいは生活保護の受給を申請する必要がなくなる方がたくさんいますから、これは認識を改めていただきたいと思います。区の建て替え時に複合施設として有効活用が可能であるという移管の条件は、これはおかしいのではないでしょうか。伺います。単独でも建て替えるべきだと思いますけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"そういった観点からも、区営住宅の建て替え等におきましては、他の行政需要との関連性も見ながら、複合化や集約といったことを考えて建て替えについて検討するべきものと考えております。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の生存権の住まいからの保障の観点から、区は区営住宅の増設と移管対象の都営住宅の移管を強く求めたいと思います。契約期限が来た際には速やかに返還していただく考えとの答弁もありましたけれども、その契約期限とは、議会にも住民にも約束していたおおむね８年という２０２０年９月６日のことなのか、それとも契約書上の２０２２年９月６日のことなのか、どちらなのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"区といたしましては、引き続き早期着手に向けて働きかけをしているといったところです。返還の部分につきましては、契約書上、平成３４年です。これは法的なところの最後のリミットといいますか、契約書上のリミットになります。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"議会と区民との約束は、おおむね８年、当時の委員会の議事録を見ても、８年、でも、契約書上は仕方がないので１０年にしましたということを言っていました。契約期限が来た際には速やかに返還していただく考えとの答弁が本会議でありましたけれども、それは２０２０年９月６日には返還を速やかにいただく考えはないということになったのでしょうか。お聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"こういった賃貸借、土地の貸し借りというところでは、行政も民間も同じでございまして、契約というものが法的な根拠です。そういった意味で言いますと、先ほど申しましたとおり、平成３４年の秋というのが法的なところのリミットというところで捉えてあります。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"法的なリミットは平成３４年９月６日ということなのですけれども、私が伺ったのは、地元の住民説明会でも、議会の委員会の審議の中でも説明されているとおり、２年間の暫定貸付をしているのです。ですから、それとあわせておおむね１０年、つまり、おおむね８年でということですが、しかし、契約書上は地上権などを主張されるかもしれない。どうでしょうか。","respondent":"柏原企画調整課長","answer":"契約内容の期間というところについてです。この第一日野小学校旧跡地を貸し付けることを、議会をはじめいろいろなところで説明、回答もさせていただいてきたところです。そういった中で、ＴＯＣのほうからおおむね８年というお話はありました。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"仮に２０２２年だとしても、これは、間に合わないのではないですか。今の時点で工事着手しても間に合わない。貸付の目的が宙に浮いた以上、速やかに返還を求めることを要請したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"本日は、８７ページの感染症予防費、感染症対策事業についてお伺いいたします。梅毒についてお伺いします。梅毒患者は２０１０年から増え出し、２０１４年ごろから急激に届出数が増加しています。昨年の予算特別委員会でも梅毒流行について注意を喚起し、区に対策を要望してきましたが、梅毒の流行は衰えるどころか拡大する一方です。現在の梅毒の大流行に対する区のご認識を伺いたいと思います。","respondent":"舟木保健予防課長","answer":"梅毒は性感染症の１つでもありますので、性感染症をみずからの問題と捉えて予防手段などを知ることや、感染が疑われた場合には、すぐに医療機関を受診するということなどの普及啓発が重要だと認識しております。","id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"意見","question":"梅毒は梅毒トレポネーマによる性感染症で、１９９６年の時点で世界中で１,２００万人が新しく感染したと推定されており、ＨＩＶ感染症と合併しながら世界中で流行が続いています。すなわち、昨年は数万人が実に梅毒に感染したと推定されているのです。なぜ梅毒が流行すると問題なのか、淋病とか性器クラミジアなど他の性感染症との違いを含めてご説明をお願いいたします。","respondent":"舟木保健予防課長","answer":"梅毒につきましては、症状が出てもすぐにおさまって、また出てくるというような形で、無症状になりながら進行してしまって、検査とか治療がおくれたりとか、無治療でそのまま経過してしまうと、脳や心臓などに重大な合併症を起こすことがあります。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"意見","question":"昔、コロンブスが西インド諸島の風土病であった梅毒をヨーロッパに持ち帰ってから、わずか２０年で梅毒は日本にも上陸しました。国立感染症研究所による７例の先天梅毒児を産んだ母親のインタビューの記録を見ると、全員、学校教育やメディア、雑誌、妊婦健診等のいずれの情報源からも妊娠中に気をつけるべき性感染症の情報を得ていなかったということでした。","respondent":"舟木保健予防課長","answer":"梅毒に対する対策についてです。現在、区におきましては、性感染症について、相談と検査を月１回、保健センターで毎月実施しております。","id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"梅毒が大流行している現在、区が先頭に立ってあらゆる予防策を行うことを強く要望いたしまして次の質問に移ります。次に、先天性風疹症候群対策についてお伺いいたします。妊娠を希望される夫婦間等に対する風疹抗体検査と予防接種の接種助成事業が平成３０年度も継続されることを高く評価いたします。平成２９年度の風疹抗体検査と予防接種の実施数は、現段階の集計ではいかがでしょうか。","respondent":"舟木保健予防課長","answer":"風疹抗体検査と予防接種の実施状況ですが、１月末までの実施状況ですが、抗体検査が８０２件、予防接種が４５４件となっておりまして、昨年度の実績と大きな増減はない状況です。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"昨年の一般質問において、風疹に感染する方を減らすために、大人への風疹予防接種事業に準じた対応を要望いたしました。今の実績をお聞きすると、昨年度とほとんど実績は横ばい、変わらないように感じますが、風疹に対する積極的な対策、対応は、何かお考えでしょうか。","respondent":"舟木保健予防課長","answer":"風疹につきましては、２０２０年度の風疹排除に向けて、現在、国を挙げて取り組んでいるところですので、まだこの事業の対象者の方で利用されていない方への周知については引き続き努めてまいりたいと思います。","id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"先天性風疹症候群が一刻も早く根絶されるように、一層の努力を要望して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"木村委員","kind":"質問","question":"私は、１５７ページの中ほどより下にあります本会議場等バリアフリー化、１,９４６万円余からです。来年度予算として、１,９４６万円余が計上されており、第２回本会議と第３回本会議の間に工事を始めると言われております。先ほど、ほかの委員からバリアフリーの質問がありました。だれでもトイレの質問でしたが、バリアフリーはトイレだけなのでしょうか。お答えください。","respondent":"久保田区議会事務局長","answer":"本会議場のバリアフリーですけれども、だれでもトイレを５階に設置するほか、本会議場の演壇のところを車椅子対応にするということと、もう１つ、委員会室に、耳がちょっと聞こえにくい傍聴者のためヒアリング支援システムを入れるというものです。","id":"exchange-068"},{"speaker":"木村委員","kind":"質問","question":"本会議場と傍聴席のバリアフリーを行うということであります。車椅子の区民の皆さんが傍聴に来られることも十分考えられます。傍聴席をどのように変えていくのでしょうか。そして、区としては、バリアフリーをすることで、障害を持っている人や車椅子の区民の傍聴者が増えることを願っていると思いますけれども、それでよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"私の説明が足りませんで済みません。今回、議場のバリアフリーをするのは、本会議場の中の一般質問を行っています演壇のところを車椅子対応ができるように改修するというものです。","id":"exchange-069"},{"speaker":"木村委員","kind":"質問","question":"以前から思っていましたけれども、現職の議員の皆さんは元気でいらっしゃるから考えられませんけれども、これからひょっとして車椅子の方が立候補などということもあり得ます。現に、文京区や足立区、葛飾区には、車椅子を使う議員がいるそうです。これから本区にも車椅子を使用する議員の可能性も十分考え、改修していくことが必要だと思いますが、そう理解してよろしいでしょうか。","respondent":"久保田区議会事務局長","answer":"私どもは、委員おっしゃるように、障害者差別解消法等も施行されましたので、私ども、そういったことに基づきまして、本会議場の中もバリアフリー化を進めていくというものです。","id":"exchange-070"},{"speaker":"木村委員","kind":"質問・要望","question":"人は元気なときは感じないものですけれども、私自身も体を悪くして初めてあらゆるところに目がいくようになりました。あるとき、議場の段差に不安を感じて、議場の壁に手すりがあったら、自分の体を支えられるのでいいのになと思いました。議場の中も手を入れていただきたいと思いますけれども、いかがでしょうか。今以上にバリアフリーをお願いしたいのですが、いかがでしょうか。","respondent":"久保田区議会事務局長","answer":"議場内のバリアフリー化についてですが、私どもは、今、一般質問をする演壇のところをバリアフリー化ということで、あと、段差がありますので、その解消についてもいろいろ検討はしているのですが、角度が急になるということもありますので、そういった場合には。","id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"先ほど言ったのですけれども、区役所の中、区民の皆さんが区役所にいろいろな手続をしにやってきますけれども、そういう中で、高齢化が進んでおりますので、そういう人たちのためにもバリアフリー化をお願いしたいと思うのですが、いかがでしょうか。","respondent":"立川経理課長","answer":"庁舎のバリアフリー化につきましては、不特定かつ多数の人が利用する施設ということで、国のほうで建築物移動等円滑化誘導基準という指針が出ておりまして、窓口業務を行う事務室に至るまでの扉の自動扉化、また、大型ベッドを備えた多機能便所設置など。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"いい言葉が出ました。次に、その下にあります図書室運営費、３７８万円余ですけれども、運営費ということですが、３７８万円余のお金の使用目的は何でしょうか。議会棟の４階にある図書館のことと思いますけれども、そんなに使用されているようには見えないのですけれども、この３７８万円余はどのようなところに使われているのでしょうか。","respondent":"久保田区議会事務局長","answer":"一般にも開放していますが、一般の方の閲覧等につきましては、１桁台の数字ということで、利用はあまりないという現状です。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、年６回発行して、２,８４２万円余なので、６回で割りますと、１回大体４７０万円前後になります。品川区全体の戸数は、２月１日現在で２１万５,８００少々ということでありますから、２２万部を製作することと思いますけれども、余ったものはどのようなところに使われるのか。","respondent":"久保田区議会事務局長","answer":"区議会だよりの１回の発行部数は、２２万４,０００部です。このうち２２万部は全戸配布で、シルバー人材センターより各家庭に配布をさせていただいてあります。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、本日も区民相談の内容をもとに２点お伺いをしたいと思います。１つ目は（仮称）障害児者総合支援施設について、２つ目が、８９ページ、民生費補助金、母子・父子家庭自立支援給付金事業補助金で、離婚相談について伺います。離婚相談のほうから伺いたいと思います。その際いただいたご相談の中で、年金分割という制度をご存じでしょうかと、こういうことを聞かれました。","respondent":"三ッ橋国保医療年金課長","answer":"離婚時の年金分割ですけれども、制度としては、離婚した場合、お二人の婚姻期間中の厚生年金を分割いたしまして、それぞれ自分の年金とすることができる制度です。これには２つございまして、合意分割、そして３号分割というものがあります。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただし、ここからが問題なのですけれども、これは自動的になるわけではなくて、離婚した日の翌日から２年間で請求の手続をしなければ、法の不知でいたずらに期間が経過してしまいますと、その請求権を失ってしまうということがあります。行政評価局に対する厚労省、日本年金機構の回答にありますように、品川区に対してこういう周知を依頼するような事務連絡とか通知等があったのかまず伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"関東・甲信越年金機構からですけれども、国保医療年金課のほうに周知の依頼がございました。関連部署に周知するようにという依頼がございました。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"意見","question":"婚姻中で離婚のご相談に訪れる子ども家庭支援課、それと、離婚届を提出する戸籍住民課、そして、離婚後の年金の相談や手続に訪れる国保医療年金課、そして離婚の相談等を受ける区民相談を担当する広報広聴課、実際にこういう区民の声も上がっておりますし、全国的な課題にもなっておりますので、この年金分割の制度について徹底した周知をお願いしたいのですが、それぞれご答弁をお願いいたします。","respondent":"廣田子ども家庭支援課長、提坂戸籍住民課長、中元広報広聴課長、三ッ橋国保医療年金課長","answer":"その他、窓口で、もし離婚した場合に、手当であるとか、どのようなサービスが受けられますかというご相談も少なからず受けておりますので。現在は年金分割については触れておりませんけれども、その中に年金分割についてもわかりやすいような形で簡潔にまとめたいと思いまして。引き続き、周知に努めてまいりたいと思います。今後また年金関連の依頼などがございましたら、関連部署に周知徹底してまいります。","id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"パンフレットもありますので、対象になる方、ならない方がいらっしゃいますので、それについてはパンフレットを活用していただきたいと思います。１点だけ、先ほども家庭支援課のほうで、「ひとり親家庭のしおり」をつくっていらっしゃるのですが、ここについても、もし記載をできるのであればお願いしたいと思うのですが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"毎年、「ひとり親家庭のしおり」につきましては５月に配布を予定しておりまして、もう編集が大分進んでおりますので、平成３０年度分に間に合えば平成３０年度分に掲載しますが、間に合わない場合には、平成３１年度にしおりに載せて。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問","question":"続きまして、（仮称）品川区立障害児者総合支援施設について伺います。アール・ブリュット美術館のパース図もそこにあったのですけれども、非常に天井が高くて、フリースペースというよりも、まさに美術館という感じの絵があったのですが、これをどのような活用を考えていらっしゃるのか、まず伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今度の（仮称）品川区立障害児者総合支援施設で、美術館、展示室を設置するわけですが、そちらは委員もおっしゃったとおり、１階から入りまして、２階が吹き抜けになっており非常に広いスペースで、光も取り入れた感じを考えております。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この中で生活介護事業として、表現活動としてのアトリエ活動や音楽、リズム等、こういった芸術活動にもしっかり施設の中で行われていくということも表明されています。ここで１つ要望したいのが、やはりこれはフリースペース的なというよりは、学芸員もしっかり入れていただいて美術館としての機能を備えた、区として日本に、世界に冠たる美術館にしていただきたいということが１つであります。","respondent":"飛田障害者施策推進担当課長","answer":"今回、こちらの障害児者総合支援施設は、旧品川児童学園ということだったので、児童学園の子どもたちに協力していただきまして、普段の創作活動、そういうところで行っている作品を準備していて、感触遊びとか、そういう中で絵の具を手に触れて。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり芸術としての人の心を動かす力があるのかどうか、子どもがつくったものに動かす力がないとは私はもちろん言えないのですけれども、さっき私が前段でアール・ブリュット美術館をつくる、また障害者の芸術活動に力を入れていく、世界に発信する施設ということで申し上げましたが、やはりそれに加えて、いわゆる評価のあるアール・ブリュットの展示、これは中野区等でも愛成会がやっていますが。","respondent":"飛田障害者施策推進担当課長","answer":"まさに今回、こちらの展示室なのですけれども、中野の愛成会が一緒に協力して展示室の運営をしていきますので、そういう意味では、広くいろいろな作家、また発掘も含めまして、障害者の理解促進を進めていきたいと考えています。","id":"exchange-081"},{"speaker":"本多委員","kind":"質問","question":"４７ページの特別区交付金と、１３５ページのふるさと納税寄附金、２つ質問します。ふるさと納税寄附金５４０万円の計上について聞いていきますが、昨日も渡部委員、石田秀男委員が取り上げ、提言もありました。引き続き聞いていきますが、昨日の答弁では平成２９年度に１１０万円の寄附があったとのことです。平成３０年度では５４０万円予算計上しておりますが、その根拠について教えてください。","respondent":"秋山財政課長、伊東税務課長","answer":"１つは、固定資産税があります。固定資産税について、今年の３年に一度の評価額の見直しの年ということで、４.２％の伸びというふうに見込んでいるもの。ふるさと納税のご質問です。確かに平成２９年度の見込みとしては１１０万円ということで、年度的には残りわずかですため、これぐらいの収入しか見込めないかと思っているところです。","id":"exchange-082"},{"speaker":"本多委員","kind":"確認","question":"財調のほうは、都の見立てと区の見立てを聞こうかと思っていたのですが、相互間で確認しているということで、これでやめます。ふるさと納税のほうなのですけれども、品川区へ納税された方の心遣いですとか、個人的な部分があるので必ずしも理由を把握することができないかもしれないのですが、その辺の分析についてはいかがでしょうか。","respondent":"伊東税務課長","answer":"なかなか細かく個々の分析まではしていないところですけれども、応援する意味での寄附ということで理解をしています。返礼品を出していますけれども、辞退される方もいらっしゃるところです。","id":"exchange-083"},{"speaker":"本多委員","kind":"質問・要望","question":"やはりイベントへの参加、大井競馬場が関東で一番のイルミネーションをやる、その入場券ですとか、例えば品川は国際交流事業を行っている都市がありますが、オーランドで言えばヒツジの製品がありますですとか、食べ物はよくないと思うのですが、物ですとかイベント参加ですとか、区民に対しては郷土愛、区外に対しては品川の魅力という、その辺の展開についてはいかがでしょうか。","respondent":"伊東税務課長","answer":"それと、逆に品川区のほうにご寄附をいただく方策ですけれども、委員、今、ご提案ありましたけれども、その辺のことはこれからどういう形がいいのか、物というのがなかなか難しいところはあるかと考えていますので、別の形で何かいいものがあるかどうかというのは、今後。","id":"exchange-084"},{"speaker":"本多委員","kind":"質問・要望","question":"これまでの答弁でも、返礼品競争をやらないということで、今現在の考えはよくわかります。ただ、何かしら手を打っていくべきだと思いますので、何がいいのか、昨日もイベントとか、ゴルフ場の割引券、いろいろな考え方があると思いますので、ぜひこういったことを今後もみんなで協議していくというようなことでお考えいただければと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"のだて委員","kind":"提案","question":"就学援助についてです。さて、就学援助への国からの補助金は１８６万円と毎年数％の補助率になっていますが、国や東京都へ支援を要望したらどうかという私の提案に、区は東京都への財調単価の改定を求めていくことが先決との答弁でした。東京都への支援を要望したのか、現在の状況を伺いたいと思います。","respondent":"有馬学務課長","answer":"したがいまして、今の段階では２３区それぞれ増額するのかしないのか、さまざまな動きがあると思います。ある程度、２３区の金額がまとまったような段階で、都のほうには申し入れをしていくということになろうかと思います。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の段階ではないということでしたけれども、就学援助という制度は子どもたちの教育機会を保障する大事な制度の１つですから、引き続き、他区とも連携して支援の要望もしていただきたいと思います。これまで同様、生活保護の引き下げに連動させないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"今回、また平成３０年度の秋に生保基準が見直しされるですけれども、これについても上限５％で数年間にわたって段階的にというようなことも言われており、詳細がまだ確定していないところもありますので、そういった意味から。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越公園駅南側の戸越五丁目１９番地再開発について伺います。初めて１９番地再開発に補助金が今回つくことになりました。補助金が出るということは、総事業費が決まったのではないかと思いますけれども、この１９番地再開発の総事業費、補助金、そして公共施設整備負担金でしたか、公共施設を整備するときに出されるお金、これが幾らなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"補助金額の合計につきましては、約４０億円ほどを予定しています。こちらについてもまだ精査をしている段階です。それから、再開発事業に係ります社会資本整備総合交付金につきましては、平成３０年度に予定されております権利返還計画作成費に対しての補助金です。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"それに対する区の見解は、課題解決を図りつつ、事業採算性を確保する上で、高度利用地区に伴う容積緩和が妥当だということで超高層ビルにしていくということでしたけれども、事業採算性を確保するというのは、どういう意味なのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"私ども区といたしましては、老朽化した建物の耐震性の確保、それから不燃構造化、また駅前というところを捉えますと、公共空間の確保でありますとか、狭い道路を拡幅したりとか、そういう基盤整備を再開発事業で進めていくことが妥当というような考えです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"事業採算性は準備組合の考え方ということでしたけれども、区の出した意見書に対する見解が事業採算性を確保するために妥当だということでしたので、これが区の見解だということではないのか、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"区としても事業を進める中で、事業者の見解については承知しています。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"事業者の見解は承知しているということですけれども、つまりは、４０億円の補助金を出して、大企業の利益を確保していく、事業採算性を確保していく、そういったことのために容積率の緩和を行うのが妥当だということなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"あくまでも町としての課題の解決、それから駅前の基盤の整備、そういったものについて区として再開発事業を進めることが妥当というような考えで進めているものです。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"今回の地区計画で、１９番地が高度利用地区に指定され、事業計画に合わせて容積率が４００％から６５０％に上げられました。この変更をしなければ、２４階建て、９０ｍの建物を建てる事業はできないということになると思うのですけれども、やはりこの容積率の緩和は大企業のもうけのためではないのかと思いますが、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"再開発を進めるに当たりましては、先ほどから委員がお話があるような事業が成立するかどうか、そういった観点も必要だと考えています。再開発については、そればかりが目的ではございません。こちらにつきましては、やはり町の課題の解決、そういったものが念頭にあるものです。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"企業の利益の観点も必要だということですけれども、企業は当然、利益を出すことを目的にやっているとは思いますが、自治体として４０億円も補助金を出して利益を確保していく、そういった観点が必要だというのは、自治体がやることなのかと思います。地域課題の解決は、超高層ビルでないとできないのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"地域課題の解決方法はいろいろあると思います。こちら、戸越五丁目１９番地地区におきましては、権利者である皆様方が再開発事業として進めたいという意思のもと進めているものです。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"「生まれ育ったこの町が好きだ」と、「再開発によって町が壊されてしまう、１９番地再開発をやめさせたい」というお話を伺いました。この間、品川区は、戸越公園駅のまちづくりビジョンも作成しておりますけれども、作成に向けて、まちづくり協議会の方だけでなく、幅広く周辺住民の方にも意見を聞いて作成したものなのか、そして計画を進めているのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"まちづくりビジョンで定めている将来像を区として今後も進めていきたいと考えています。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"だからこそ、今、この周辺の方からも、１９番地再開発をやめてほしいという声が上げられております。品川区は、戸越公園駅周辺の町をどういう町だと認識しているのか、私は町の方々がおっしゃっているとおり、肩肘張らずに出かけられ、商店街もありますので、町のコミュニケーションも活発に行われて親しみのある町だと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"私どもも町会の方、それから商店街の方とお話しする中では、委員と同じ考え方です。この町について今後も維持し続けられるような取り組みを続けたいと考えています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じ考えだということでありましたら、やはり再開発が進むと町が壊されてしまうということも近隣の方が危惧されておりますので、こういった考え方を改めるよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"私は、例年要求資料を使わせていただいて、その中の７ページにあります保育園に対する国、都の補助金等々の金額がそれぞれ入っております。その中でお聞きしたいのは、保育園を設置するといった場合に、私立、認証、それぞれどのぐらいの補助金が入るのか、品川区も当然負担をしていると思うのですが、品川区の負担はどうなるのでしょうかということ。そして、運営費です。","respondent":"大澤待機児童対策担当課長","answer":"補助金としましては、平成３０年度、運営費で、国と都から入ってきます合計額が４３億円余というふうになっております。開設経費に関しましては、平成３０年度予算で、国および都から、準備経費として２６億円余が歳入となる予定です。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"それと品川区の負担も増えてきていますよねということを言いたいのです。推移も聞いているのは、品川区の負担がどんどん増えてきているのではないでしょうか。そのもととなる数字があればということでお答えをいただきたいのです。なので、推移のほうは数字がないということなので、品川区の負担がどのぐらいになっているのかをお聞かせください。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年度の予算で、私立保育園等の運営費は１２６億円になりますので、区の負担割合が６６％というふうになっております。このパーセンテージ自体は毎年大きく変わるものではございません。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"今、６６％ということで、この割合は毎年変わらないということですか、私立保育園は非常に多くなっています。１０園とか、今年も１２園でしょうか、増やしていくという形になるので、当然ながら運営費ですから、毎年毎年、私立保育園、認証保育園に対する運営費が品川区にかかってくるのだと思うのです。","respondent":"大澤待機児童対策担当課長","answer":"金額はもちろん毎年園数が増えれば上がりますけれども、運営費全体にかかる区の負担割合は、毎年大きく変わるものではないです。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"この待機児童解消に向け、いつまでこの事業をどこまで大きくしていくのかということです。そして、その根拠がどういうところにあって、今後の５年先、１０年先の保育園を計画していくのか。次に民営化です。その民営化になったときの品川区の負担といいますか、ほかのところからの補助金等々が出ると思うのですが、どういう形になってくるのか、それを教えてください。","respondent":"大澤待機児童対策担当課長、吉田保育施設調整担当課長","answer":"ですので、子ども・子育て計画に基づいて、平成３１年度までは開設の予定が立っておりますけれども、平成３２年以降の開設につきましては、来年、ニーズ調査等をいたしまして。私からは、公設民営についてと、運営費についてもご説明申し上げます。公設民営につきましては、区の持ち出しはほぼ１００％という形になります。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"今の公設民営に関してですが、持ち出し１００％とはどういう意味なのでしょうか。要するに、公立保育園をつくるというのは、１００％一般財源から出るわけです。今の公立保育園を民営化することによって、どういう形になってくるのですかという話です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"もう一度。新設はわかります。運営費が変わってくるわけですね。要は、民営化をすることによって変わってくると思うのです。それによって予算の立て方も変わってくると思うのですが、どういう形になってくるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"公設民営のところの運営費ということでよろしいでしょうか。公設民営の運営費となりますと、これは区立保育園と同等になりますので、区の持ち出しがほぼ１００％という形で運営する形になります。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"済みません、私の質問が悪いのかもしれませんが、では、なぜ民営化するのですかという話になってしまうのです。では、民営化になるとどういう形になるのですかという話です。民営化しても、品川区からの持ち出しが変わらなければ、なぜ民営化するのですかという話になってくるのです。では、公立保育園の意味は何でしょうかという話です。そこを答えていただけますでしょうか。","respondent":"佐藤保育課長","answer":"先ほどの答弁があったように、運営費に関しましては、公立の保育園のスキームと同じで、利用者の負担が大体１５％、それ以外に関しましては区の税金で負担をするというものでありまして、第一義的には待機児童対策です。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"品川区は公立の民営化をやろうとしているわけではないですか。そうなったときに、予算立ても変わってくるのですか。今の答弁ですと、いや、変わらないです、委託するにしても全て区がお金を出すことになるのです、品川区の負担が同じなのですというのであれば、民営化にする必要はないではないですか。だったら、ではなぜ公立保育園を民営化にする意味があるのですかということです。答えられますか。","respondent":"佐藤保育課長","answer":"その関係で一度に民設民営に切り替えるのではなくて、一度、公設民営という形で民間に委託をしてから、徐々に民設民営に切り替えていくという考え方に基づいてやっているものです。","id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"すまいるスクール関係です。児童指導に携わる方の人材確保を要望するという質問をさせていただいた中で、国の子ども・子育て支援交付金の運営費補助は、人件費基準額が引き上げられ、増額分を要求しますという答弁をいただいております。これは具体的に言うと、さっきもちょっとお話が出ましたけれども、工事現場を見ると、来年の２月の完成、４月の運営開始に間に合うのでしょうか。","respondent":"高山子ども育成課長、小林施設整備課長","answer":"今回の歳入に関します部分につきましては、利用児童の増加に伴いまして、必要額を最大限要求するというものでございまして、こうしたものが回り回ってではありますが。現在、現場のほうでは、５月末ごろまで、地下の部分の工事を進めております。それから鉄骨を建てまして、８月ごろから仕上げに入ります。そして、平成３１年２月を目標に竣工できるように、今現在、一丸となって頑張っています。","id":"exchange-105"},{"speaker":"鈴木（真）委員","kind":"質問","question":"契約は５年ですね。その中で人件費分を乗せていただいている、乗せてもらいたい部分なのですけれども、その辺に関して教えてください。全然反対もなく、あれだけのものが立ち上がるというのは、本当に地域の方のご協力があると思っているのですが、その中で近くの小学校の児童の作品も一緒にしたらどうかというお話もあったのですが、今そういうお話は進んでいないのでしょうか。","respondent":"高山子ども育成課長、飛田障害者施策推進担当課長","answer":"すまいるスクールは委託による運営形式ということでございまして、平成２９年度の総事業費に占めます委託料の割合は、大体５９％程度だったのですが、平成３０年度の当初予算におきましては６３％ということで。近隣の小学校ということで、今後、城南小学校に声をかけて、どういうふうな作品、どういう展示方法があるかを検討していきたいと考えております。","id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"運営のほうです。４つの団体というか、法人が一緒になってこれから指定管理を受けていく方向にあると思うのですが、やはり４つの団体が一緒にとなると、まとまりがなかなかつきにくいというのは以前からお話を伺っています。最初のプロポーザルのときから４つで来ているのですから、ぜひそのまま進めていただきたいのですが、今の進捗状況、そのまとまり状況について、もう一度教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"運営に関しても、なかなかこちらの考え方と相違が出ることもありますが、そこが大きな課題と言えば課題になってしまいますが、いずれにしましても、区と運営事業者ともに平成３１年４月より、しっかり運営ができるよう、今後とも協議を図っていきたいと考えております。","id":"exchange-107"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地方消費税の関係です。このままいくと、品川区は３０億円という数字になってくると思うのですが、この辺につきまして、区は当然、先ほど来、お話はわかっておりますが、これから例えば特別区長会として、さらなる要望をどのようにしていくのか、この辺をどう対応なさっていくのかお聞きしたいと思います。","respondent":"秋山財政課長、柏原企画調整課長","answer":"法人税も含めて、税制改正案が上がって、国はこちらのほうを見ているですので、これを、繰り返しになりますけれども、区長会を通じて、また東京都とも連携をとって強力に主張してまいりたいというふうに考えているところです。全国連携プロジェクトの関係です。今、委員ご指摘もあったとおり、区としてもさまざまな都市と交流連携したいというところで、区長会のほうでも連携プロジェクトの強化ということで、さまざまな取り組みを今、検討しています。","id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全国連携プロジェクトはぜひ、やっぱりわかってもらわないと、せっかく２３区でやっているものが何も伝わらないのではないかと思います。ぜひその辺もしっかり区長会等で検討していただきたいと思います。ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、８３ページ、国庫支出金の国民健康保険負担金、また同じく１０３ページに、都支出金としての国民健康保険負担金というところで、いわゆる国保の広域化にかかわる質問をさせていただきたいと思います。これまでも、昨日も含めて幾人かの委員からもこのご質疑がありましたけれども、平成３０年度から広域化ということで、国保が東京都に移管をされる。","respondent":"三ッ橋国保医療年金課長","answer":"その中で区といたしましては、やはり統一保険料方式の、２３区内同一世帯同一所得であれば同じ保険料という考えに基づきまして、区といたしましては、その考え方に賛同しております。","id":"exchange-110"},{"speaker":"塚本委員","kind":"質問","question":"将来的な方向性で示されている法定外繰入金の解消または縮減というふうになっていますけれども、改めて法定外繰入金に対する特別区の方針、ならびに、その特別区の方針の中において、さらに品川区としてそれをどのように受けとめ、また理解をしているのか、何か独自の考え方等あるのか、お伺いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金の部分ですが、国からは法定外繰入金を解消・縮減するようにと求められております。その考え方に基づきまして、区といたしましても法定外繰入金を解消・縮減する方向で考えております。","id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"医療費の適正化に向けた取組等に対する支援ですけれども、これはどういうものなのか。品川区として、今、この支援制度の活用にあたり、どのような状況であるか教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"保険者努力支援制度ですが、これは国の追加で１,７００億円が予定されておりまして、それは国保共通の指標、そして一方では、保険者共通の指標というものがそれぞれあります。","id":"exchange-112"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうさまざまな財政支援で国保の負担を下げていこうという動きがあるわけですけれども、そういう中でも、どちらかといえば医療費が高くて、そして所得としてはそんなに高所得の被保険者がいないという特性がありますので、この中で区として、今後の、保険料負担をどのような形で安定化していくのか、持続可能なものとしていくのか、そういうところについてご見解をいただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"今回、財政運営の安定化といたしましては、東京都が財政運営の主体となっております。区や特別区長会、そして全国自治会連合会からも国庫負担金の増額の要求はしておりますので、なるべく保険料が値上がりしないようにしていく所存です。","id":"exchange-113"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる支援というところを含めまして、あとは医療費の抑制というところで最後にもう１つ伺いたいのですけれども、これまでも医療費の抑制ということで質疑がございましたけれども、医療費をなかなか少なくしていくということは難しいのかもしれませんが、増加を少しでも抑制していくというところで、いろいろな手段があるかと思います。","respondent":"三ッ橋国保医療年金課長","answer":"医療費の適正化につきましては、データヘルス計画の中でいろいろな取り組みを行っております。その中で、やはり医療費、重症化予防対策や薬剤の関係のさまざまな取り組みを行っておりますけれども、できるだけ保険料が上昇しないように抑制してまいりたいと考えています。","id":"exchange-114"},{"speaker":"いながわ委員","kind":"確認","question":"それと、１４７ページの雑入の広告料収入について、要するに、広告料収入ですから税外収入の観点から考えて大変必要なものだと思っておりまして、おそらくこれは大半が区のホームページのバナー広告料だと思っていますが、これに関して、その詳細と、今後の事業展開をどうお考えなのかということ。","respondent":"今井土木管理課長、稲田都市開発課長、池田スポーツ推進課長、溝口公園課長、中元広報広聴課長、松山高齢者地域支援課長","answer":"７５ページの土木使用料、土地建物使用料につきましては、五反田ふれあい水辺広場内の地域貢献施設として貸し出しを行っているところです。西大井駅周辺の西大井作業所というところで、従前居住者への仮移転先としてお貸ししているという状況があります。１０７ページのスポーツ施設整備費の補助金です。新たにという形ではありませんが、今後もこういった補助金等は活用しながら整備等を進めていきたいというふうに考えているものです。こちらも引き続き広告等の掲載に努めていきたいです。","id":"exchange-115"},{"speaker":"いながわ委員","kind":"質問・要望","question":"スポーツ施設整備費は、オリンピックに向けてということだったのですが、ということは、オリンピックはあと２年後なのですが、２年たったら、それは打ち切られる方向性なのかどうなのか、もちろん計画的に整備はしっかりと進めていただきたいという思いがありますので、よろしくお願いします。","respondent":"秋山財政課長、松山高齢者地域支援課長","answer":"区としましては、税外収入については、各所管に工夫をするようにという通知をしておりますので、それぞれ各所管の立場で工夫をしてやっているというところで。ただし、シルバーセンターの老朽の度合いですとか、お困りの状況を総合的に勘案しながら進めてまいりたいと考えています。","id":"exchange-116"},{"speaker":"いながわ委員","kind":"質問","question":"要するに、例えば広告料収入はすごく考え方が幅広いと思うのです。そのバナーの上には広告募集についてなどというものが書かれているのです。そこを押すと、バナーのみです。では、ほかの例えばデジタルサイネージに載せたいという人たちは、どこにいけばいいのかもわからないですし、それをしっかりと管理するべきではないですかということを申し上げております。よろしくお願いします。","respondent":"秋山財政課長","answer":"どのようなことをやっているかという調査も含めて、こちらのほうで取りまとめて、今後、ワンストップでできるようなことを検討していきたいと思います。","id":"exchange-117"},{"speaker":"渡辺委員","kind":"質問","question":"１３１ページ、オリンピック・パラリンピック教育推進事業について伺いたいと思います。その中で、まず東京都委託事業の、主な内訳を教えてください。数値目標か何かおありなのか、そういう認知度、学ぶという観点になるかと思うのですが、こと３競技の応援ということでおありでしたら教えてください。","respondent":"熊谷指導課長","answer":"特に都のパラリンピック応援校になっております荏原第六中学校におきましては、ブラインドサッカーに特化して選手たちの競技会場、練習会場として活用する中で、生徒との取り組みを進めているところです。","id":"exchange-118"},{"speaker":"渡辺委員","kind":"質問","question":"そこで１つ伺いたいのが、映像の活用をどのように考えられているか。だからこそファンになったというケースを最近ちょっと感じたものですから、映像等を活用して、今まで３０人が限界だった、１００人が限界だったものが、またそこからの広がりという意味で浸透できるのかなと、教材にもかかわってくるかと思うのですが、何か考えがございましたら、よろしくお願いします。","respondent":"熊谷指導課長","answer":"この都の委託金ですけれども、こちらにつきましては、全ての幼稚園、学校に、次年度は２０万円ずつ支給となっております。こちらにつきましては、平成２８年度が３０万円、平成２９年度が２５万円、来年度が２０万円ということになっているところです。","id":"exchange-119"},{"speaker":"渡辺委員","kind":"質問","question":"体験会も、今、所管のほうでやっているスポーツ団体から今度は違うところへ、文化団体等へというのも伺ったことがあります。一方で障害者の方が友達や家族にいますかというと、手を挙げた方は３分の１ぐらいでした。そのような形で障害者理解を高めるための手段としては最高のものだと思いましたので、その辺の発信力を学校が、先生がリーダーとなって力を入れていく、そんな抱負を最後に伺えればと思います。","respondent":"熊谷指導課長","answer":"障害者スポーツのレベルが非常に高いというようなことも含めて、保護者や地域にも一緒にかかわって参加していただくような仕組みをとっておりますので、これからも学校だより等で周知していきますけれども、参加型ということも含めて行っていきたいと思います。","id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、国庫補助金、また都補助金の地域生活支援事業から、日中一時支援事業についてと、そこに関連して放課後等デイサービスについて伺いたいと思います。先ほどもあったのですけれども、登録料について伺いたいと思います。先ほども答弁があったのですけれども、改めて登録料とは何か。なぜ徴収するのか。そして、なぜ生活保護世帯や非課税世帯からも徴収されているのかを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"お尋ねの生活保護世帯ですとか、所得の低い方からもいただいているのかというお尋ねですが、現在のところ、登録料は全員の方からいただいているところです。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問","question":"この利用料の月々の請求や銀行振替手数料等々の事務的なものということなのですけれども、先ほどもありましたが、この事業だけが登録料なるものを徴収しているということで、２３区で見ても、品川だけなのです。月々の請求や銀行の振替、こうした業務は誰がやっているのでしょうか。どこかが代行などされているのでしょうか。","respondent":"中山障害者福祉課長","answer":"それが社会福祉協議会のほうに、もともとのＮＰＯ法人がもうこれ以上事業ができないというようなお話をいただき、社会福祉法人に移管をしたものです。そういった当時のところから事務的な経費ということでいただいていたものです。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"確認","question":"この事務手数料等々の代行としては、にじのひろば戸越では、明治安田生命が収入代行として月５０数件を請け負っているというふうに伺ったのですけれども、そこをまず確認したいと思います。最初はＮＰＯの方々がやっていたと、それから社会福祉協議会に移管される時点で、この登録料を委託料、品川区の委託料の中に入れることで、親御さんからの負担をなくすということはできなかったのでしょうか。","respondent":"中山障害者福祉課長","answer":"済みません、多分、代行手数料のところのお話かと思います。明治安田生命のほうは、私、申しわけございませんが、存じ上げません。社会福祉協議会に事務移管をしたときの話ですが、利用料金制度自体の中身の見直しは特にその時点ではしておりませんでした。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどの生活保護世帯や非課税世帯、要は、収入の低い世帯からもこういった５,０００円の登録料は減免なしにとっていくということでしたので、ぜひここをなくしていくべきだと思います。そして、委託料として区が払うということを進めていくべきではないかと思うのです。その辺はいかがでしょうか。利用料軽減等により利用料ゼロで通われている方はどれくらいいるのでしょうか。","respondent":"中山障害者福祉課長","answer":"先ほどもご答弁申し上げましたが、この５,０００円ということにつきましては、料金の見直し、それから負担軽減策をあわせて検討していきたいというふうに考えております。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"登録料は廃止すべきだと思います。これがなければ運営できないというものではないと思いますので、ぜひ廃止していただきたい。低所得の方で９名の方はゼロということですが、そしてまた、昨年引き下がった利用料で多くの方が利用できるようにすべきだと思いますけれども、いかがでしょうか。ぜひ検討をお願いしたいと思うのですが。","respondent":"中山障害者福祉課長","answer":"日中一時支援のにじのひろばの利用料につきましては、今年度から利用料金の負担軽減の策もとってきたところです。利用者の方のお声も聞きながら、登録料についても見直しを検討していきたいと考えています。","id":"exchange-125"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ廃止の方向で検討をお願いしたいと思います。にじのひろば戸越を見せていただきました。ですけれども、目的のところには、障害者等の日中における活動の場を確保し、障害者等の家族の就労支援や、障害者等を日常的に介護している家族の一時的な休息等を確保するためとあるので、障害児に絞る必要は、この目的から見てもないのではないかと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"日中一時支援を大人の方にもご利用できないかというようなお尋ねかと思います。今現在でも、小学校１年から高校３年生までということで、幅広い年齢層のお子様、障害児の方に対応しています。","id":"exchange-126"},{"speaker":"石田（ち）委員","kind":"質問","question":"日中一時支援事業の対象を障害児にした理由は何なのでしょうか。","respondent":"中山障害者福祉課長","answer":"やはりこの事業を、ＮＰＯ法人の方が始めたときの成り立ちがございまして、特別支援学校の放課後において、なかなか障害児の方が楽しく過ごせる場所がない、あるいは、働いているため親御さんが見られない、そういったときの預かりの場が必要だということから。","id":"exchange-127"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。では、ぜひそういった障害者の方が心を休める時間をとれる場所を工夫してつくっていっていただけたらと思います。ですので、やはり放課後等デイサービスの利用日数、品川区の方針では、基本月１０日、これがやはり壁になっているというふうに思います。塾や習い事とは違うと思うのですけれども、なぜこれと同じ扱いになるのか伺います。","respondent":"中山障害者福祉課長","answer":"そういった中では、１５日の利用の方も大変増えておりますので、これからもご利用される方のお声を聞きながら、何がそのお子様にとって最適かを一緒に考えていければと考えています。","id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問","question":"療育への偏りという答弁があったのですけれども、療育というのは、機会を増やすことでつらくなるというものではないと思うのです。ですので、やはり塾や習い事と同じ考え方で基本月１０日にしていくという考えを改めるべきだと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスは、やはり特別支援学校などと連携をすることというのが、今回、国の方針でもあります。そうしたことを見ながら適切な支援ができるよう支給のほうも決定してまいりたいと考えています。","id":"exchange-129"},{"speaker":"浅野委員","kind":"質問","question":"歳入、５９ページの集会所使用料、１２５ページの緊急放送設備整備補助金、９５ページのがけ・擁壁安全化支援について質問します。このような形で集会所が増えると、また地域の活動がより活発になるのかというふうにも考えられます。このたびの改修に関して、部屋が増えたとか、そういうことはあるわけですけれども、特徴的な内容、何かほかにもプラスアルファがあるのかどうか教えてください。","respondent":"伊崎地域活動課長","answer":"荏原第四連合のほうに貸し付けておりました旧荏原第四地区会館が閉鎖することに伴いまして、カラオケをやっていらした方の活動の場がなくなるということのご意見も受けまして、音響設備を入れて、３階の集会室でカラオケを利用できるにしたところが大きな特徴です。","id":"exchange-130"},{"speaker":"浅野委員","kind":"質問・要望","question":"１２５ページの緊急放送設備整備補助金１,０００万円、国庫補助金２分の１ということですが、大井埠頭に３カ所、品川埠頭に１カ所、この緊急放送設備が受信設備を含めて設置をされるというふうに伺いました。この意図といいましょうか、当該地域に３カ所、また１カ所設置をされる意図があれば教えていただきたいと思います。","respondent":"古巻防災課長","answer":"今年度から品川区において防災行政無線の更新を進めておりますけれども、それに際しまして、品川埠頭、大井埠頭のほうに防災行政無線の設備を増設するということで、補助金の申請をしまして、補助金を受けるというような形で事業を進めるものです。","id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"続きまして、がけ・擁壁の安全化支援ということで質問いたします。このがけ・擁壁については、今まで手をつけるというのが非常に難しかったと思うのですけれども、今回このような形でスタートといいましょうか、やっていきますということになったわけですが、何か大きな変化があったのか、それとも特別なやり方とか、そういうものがあるのかどうか教えてください。","respondent":"鈴木建築課長","answer":"大きな動きとしましては、やはり広島あるいは大島の土砂災害を受けて、東京都でも、昨年と一昨年かけて擁壁の緊急地域を指定に向けて調査を行ってあります。そういったところと連携しながら、来年度も擁壁の改修事業を進めていって、擁壁の改修を進めていきたいです。","id":"exchange-132"},{"speaker":"浅野委員","kind":"確認","question":"私がよく回っている地域につきましても、これは完全に切り立ったところもあるわけでありまして、やはりそういうところが少しでも安全に改修できれば、これは地域にとってもプラスになる、そのように思いますので、この点についてはこれからも確認しながら進めていただければと思います。","respondent":"鈴木建築課長","answer":"箇所数としましては、約２,２００カ所というところでございまして、調査結果につきましては、目視の調査でございましたが、区のホームページ上でも分布図として公表しまして、さらには所有者宛てに調査結果の概要を周知し、事業の案内も行っているところです。","id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"実際にできるところといいますと、なかなかこれは難しいと聞いております。簡単にはいかないところが多いと思いますけれども、粘り強く地域住民の方の意向も踏まえて、持っている方とも当然ですけれども、しっかりと連携をとりながら改修できるようにしていただければと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"その辺の不安をアドバイザー派遣等を通じて、しっかりまず擁壁の安全化についてご理解いただいて、あるいは、日ごろの維持管理についてもしっかり技術的なアドバイスを差し上げて、１箇所でも擁壁の改修が進んで。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問","question":"初めに、予算全体のことを伺います。それで、プレスなどを見ると、長期基本計画の最終年であり、集大成の予算だというような形でありますけれども、この予算をどのように捉えて、今、予算を提出されたか、積極的にいろいろな事業をやって、新規事業とかいろいろ載っているのだけれども、どうゆう気持ちの中でこの予算を組んで、そして１００億円増の過去最大規模にしたというところをお考えを教えてください。","respondent":"秋山財政課長","answer":"平成２９年度に比べて、民生費が１１３億円伸びておりますけれども、そのうちの７０億円強が子どもに関する施策ということで、そういうところに注力をして区民の期待にこたえている予算だというふうに認識しております。","id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その中で義務教育などは学校３校プラス施設建設で３０億円増。特に今度、待機児童もあるけれども、そういうところへ入れていったら１００億円になったけれども、そうではなくて、にぎわいの町をつくるため品川区としてこういうことをしていくのだということを明確にすべきだと思っているのですが、こういう考え方がどこかあれば教えていただきたい。","respondent":"秋山財政課長","answer":"そういう中でも、例えば今回、投資的経費の中でも障害児者総合支援施設とか、かけるところにはかけていって、こちらの施策を進めていきたいというふうに思っております。","id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ未来志向で、区長も答弁でいろいろな形でにぎわいをつくっていくのだというふうにおっしゃっていて、にぎわいがある品川区を今後４年間でもつくっていこうという形で力強く発言をされているわけですから、そのにぎわいをつくるためには、もちろんそれにはソフトもハードも必要だと思っているので、そういうところにしっかり予算をつけていくということをぜひやっていただければと思います。","respondent":"濱野区長","answer":"２０２０年東京オリンピック・パラリンピック競技大会があります、多くの方々が区に訪れていただきます。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。次に、５５ページの庁舎管理費負担金に関連して質問します。スクエア荏原でシナモロールカフェが開かれます。今回は、スクエア荏原でいいけれども、そういう発想をぜひしていただきたい。そういう発想もあったのか、それから、今後もそういう発想で人の流れを変えていくということも考えていくのか、ここだけ最後にお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"これは委員おっしゃるとおりでございまして、そういった流れを政策的といいますか、戦略的にといいますか、考えてつくるというのは、これは今後にぎわいという観点では非常に重要なポイントであると考えていますので、シナモロールだけではなくて。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは６４ページの使用料及び手数料か、それとも１４４ページの雑入なのか、どこに入るかちょっとあれなのですが、健康センターの利用料金と指定管理に伴う区への還元金というのでしょうか、それに関してと、それからもう１つは、７５ページ、総務手数料の住民票等の証明発行にかかわって、目黒のサービスコーナーについてお尋ねします。","respondent":"川島健康課長","answer":"健康センターの利用料金収入のお話です。ここ数年の還元金の推移からお話ししますと、平成２６年度が７６０万４,２９６円、平成２７年度が９７０万５,６５２円という推移になっております。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが今お話しあったように、９００万円、１,０００万円近いということは、ただ、収入の２０％というと、もっと多くなると思うのですが、その算定方法は、料金が出てから幾ら還元するかということを決めるというお話ですが、今度どうなるかということをあらかじめ決めないで、収入料金が出てから決めるのですか。そこがちょっとあれで、ここ数年において見直をしているのかもお尋ねします。","respondent":"川島健康課長","answer":"失礼いたしました。今委員がおっしゃったとおり、収入額から見込額を引いた部分ということで見込額が１億６,７００万円、これは最初に決めたものですけれども、収入からこの見込額を引いた部分の２割が区の還元金になるという計算です。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"指定管理の運営委託の成功例だと思います。さらに還元金がこのように１,０００万円近く入ってくるということに関しても、区の歳入を増やす非常に効果的な施策であると思います。これまでのこちらの指定管理運営委託としての評価と、このような形式、つまり、利用料金、水族館はまた違った形式なのかもしれませんが、このようないわゆる歳入を生むような指定管理の仕組みに関するお考えをお願いします。","respondent":"柏原企画調整課長","answer":"ですので、こういった形での指定管理のあり方というのは、進めていくべきであると考えていますし、そういった事業の内容によっては、なかなかそういうものが生みづらい事業の施設もありますけれども、そういった効果が望めるようなところについては。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"意見","question":"健康センターについては２箇所でこのような形で進められているのは大変よいことだと思っています。サービスコーナーのほうに移りまして、目黒のサービスコーナーが大井町、武蔵小山に続いて民間委託ということなのですが、期待される成果、それと、また逆にこういった課題を克服しながら進めていかなければいけないのではないかという、その点についてお尋ねいたします。","respondent":"提坂戸籍住民課長","answer":"目黒サービスコーナーにつきましては、大井町、武蔵小山に次ぐ第３のサービスコーナーということで、４月７日にオープンを予定しております。運用形態ですけれども、大井町は今年度から委託を開始しておりますけれども、武蔵小山は今のところ直営でやっております。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"期待される成果というのは、サービスの向上や直営で行うことによる経費削減という、そういったところの観点でお話しいただきたいのですが、その点についてはいかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"もちろん接遇の向上、あと、コスト減ですと、職員を以前の大井町サービスコーナーですと１０人以上雇用していたのですが、それが約半分程度で済むのではないかということで、サービスコーナーだけではなくて、戸籍住民課全体のコスト減につながると期待しております。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"サービスコーナーは区全体の窓口でもありますから、大井町も含め、サービス向上と経費節減を、このまま進めていっていただければと思います。ほかの分野においても、このような民間委託についてはさまざまな課題を検討しながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"質問に入ります前に、平成３０年４月から新しい公会計制度、いわゆる複式簿記の発生主義による新しい制度がいよいよ始まるということで、またそれに合わせて、今回いろいろ工夫を、特に明日からの歳出の審議に当たって１課１目に合わせた新しい予算書の作成とか、しっかりとこういうものを私たちはツールとして活用させていただきたいと思います。","respondent":"齋藤会計管理者","answer":"歳入、歳出、日々仕分けに当たってのパソコンの操作研修です。日々、管理職も含めて、延べで８００人近い職員が研修に携わっておりまして、実際にパソコンを使って間違いのないようにきちんと対応できるようにということで取り組んでいるところです。","id":"exchange-145"},{"speaker":"若林委員","kind":"質問","question":"空き家等対策事業ですけれども、まずは平成２８年度から空き家相談会、これは年に２回ですか、それから電話相談が毎週の月・水・金の午前中に行われております。こういう中で、区民等からのご相談でどのような内容があるかをお聞きしたいと思います。あわせて、昨年の決算特別委員会でもお聞きしましたけれども、平成２９年度、今年度、空き家対策等の計画策定をする予定というふうになっております。","respondent":"長尾住宅課長","answer":"対策計画につきましては、現在、作成を進めているところです。現行のこれまで中心に行っておりました空き家に関する調査の内容でありますとか、あと、先ほど申しましたホットラインでの相談の窓口のお話などをまとめるとともに、これから取りまとめを進めていくところです。","id":"exchange-146"},{"speaker":"若林委員","kind":"質問","question":"今の計画の内容は、その大きな２つをもって、いわゆる空き家等対策の計画といわれるのでしょうか。もうちょっと内容を、私のほうで去年のご答弁を紹介しましたので、不足があればつけ加えてください。","respondent":"長尾住宅課長","answer":"その中でどういった地域を空き家対策を進めるエリアとして指定するのか、また、その計画の実施年数についてであるとか、あとは、大きなところで言いますと、空き家の適正な管理に関しての施策、空き家の活用に関しての施策といったものもまとめることになっております。","id":"exchange-147"},{"speaker":"若林委員","kind":"質問・要望","question":"もう１つ、居住支援団体、これは東京都のほうで指定をするというふうに法的に決まっていますけれども、こういった都の指定も受けなければいけないという、まだまだそういう意味では、これまでのご答弁どおり、なかなか居住支援協議会の立ち上げには壁が厚いというか、高いというか、国のほうでは平成３２年度を目標にすべての自治体での立ち上げを掲げていて、一方、一昨年の決算特別委員会では。","respondent":"長尾住宅課長","answer":"そういった国や都の動きなども含めて、効果的な品川区版の住宅確保要配慮者に対する支援体制というところを構築していきたいというふうに考えておりますが、既存の事業などもいろいろ既にやっているものもありますので、そういったところとのバランスも見ながら。","id":"exchange-148"},{"speaker":"若林委員","kind":"質問","question":"取り組んでいくということで、先ほどご紹介したいわゆる残る２つ、３つの大きな課題をどうやって乗り越えていくのかというところの、課題を指摘したわけですので、そこについてのご答弁をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"伊藤委員","kind":"質問","question":"７７ページの個人番号カード再交付手数料に関連して、それから１２ページのオリンピック・パラリンピック施設周辺道路整備工事に関連して、それから１４１ページの社会福祉法人貸付金返還金に関連して質問します。は個人番号カードのほうですけれども、これは去年も質問しました。国のホームページによれば、公平公正な社会実現云々かんぬんで、全国民が対象であるということ。お願いいたします。","respondent":"提坂戸籍住民課長","answer":"マルチコピー機の端末体験セミナーというのを何回か開催しまして、コンビニで設置しておりますマルチコピー機がいかに使いやすいかということをＰＲして、マイナンバーカードの普及につなげたいと考えています。","id":"exchange-150"},{"speaker":"伊藤委員","kind":"確認","question":"だって、国はあくまで公平公正な社会実現、利便性向上のためにやるというわけだから、おそらくこの目標は変えないでしょうから、そうなってくると、必ず全ての国民の方々がこのカードを持つことが前提としてあるわけだから、やはり今までの取り組みだけではなくて、さらにそういう国の方向性を確認した上で、積極的な取り組みをしていかないと、３８万、３９万人の区民に対して。","respondent":"提坂戸籍住民課長","answer":"マイナンバーカードの個人番号が情報漏洩ということにつながらないように、安全なカードですということをあわせて十分ＰＲしてまいります。","id":"exchange-151"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。これは私も何回か質問させていただいたので、大井競馬場入り口から大井ふ頭中央海浜公園、それからホッケー会場までの無電柱化、これはぜひ進めてくださいということをお願いしているのですが、やはり立会川駅周辺が抜けているのです。だから、そこからのアクセス、そこからのルートについても、やっぱり配慮していくべきではないかと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"私からは、オリンピック・パラリンピック周辺の無電柱化についてお答えします。","id":"exchange-152"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、もちろん看板設置なり、さまざまなことをこれからソフト、ハードやっていくのでしょうけれども、改めてこの立会川駅から大井ふ頭中央海浜公園までの間のアクセス、道路整備、それから案内看板の設置等、さまざまな検討をして、ぜひ２０２０年に間に合うようにしていただきたいと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"多並道路課長","answer":"整備の考え方ですが、立会川駅の近くの浜川橋のちょうど補修工事が入ることで、来年度の予算に計上をしています。その補修工事をやりながら、前後の舗装の修復もやっていこうと思っているところです。","id":"exchange-153"},{"speaker":"伊藤委員","kind":"質問・要望","question":"改めてよろしくお願いいたします。今、社会福祉法人のＩＣＴ化は、厚生労働省が非常に積極的でありまして、２０１８年に現場スタッフの報告を電子化、そして２０２０年に全面展開を目指すということが厚生労働省の方向性であるとわかりました。これはぜひ品川区の社会福祉法人の中でも展開をしていっていただきたいと思うのですが、まずは品川区のお考えをお聞かせください。お願いいたします。","respondent":"寺嶋高齢者福祉課長","answer":"いずれにいたしましても、ＩＣＴ化につきましては、全国的にも注目されておりまして、品川区も他の自治体の例なども参考にしながら、鋭意情報収集に努めているところで、今後の検討課題の１つであると認識しています。","id":"exchange-154"},{"speaker":"伊藤委員","kind":"質問","question":"だから、これからは間違いなく高齢者の数が増えていくわけであって、そこにＩＣＴ化の導入を図ることによって、総体的に個々のサービスが向上していくということ。同時に、介護のサービスにかかる費用も下がっていくということ。だから、今の検討する方向は正しいのだけれども、もっとより主体的に具体的に、国の方向性をつかみながら品川区がリードしていくべきだと思うのですが、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"これは民生費の款の中でのお話にもなってくるのですけれども、来年度、データ分析の費用として１,１００万円ほど計上させていただいている、ＩＣＴ化に向けてデータ分析をやるという、そういった事業も検討しているものがあります。","id":"exchange-155"},{"speaker":"伊藤委員","kind":"質問","question":"これももちろんあるでしょうけれども、できれば最期の看取りの部分については、社会福祉法人の中では、円満な形で、さまざまなことがあり、もちろん簡単にはいかないことはわかってはいるのだけれども、個人の最期のところは、やっぱりさまざまな専門家が合同ですばらしい形で送ってあげたほうがいいと思うのですが、品川区のお考えをお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"これからもその部分につきましては、しっかり取り組んでいくというふうに聞いているところです。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"８９ページ、シティプロモーションについてお聞きしたいと思います。品川区も地方も、それぞれシティプロモーション事業を各自治体でやっております。さまざまな事業をやっておりますが、そもそもシティプロモーションの始まった理由は何ですか。教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"そのときにそれぞれの自治体で都市間競争のような、そのときに定住人口の確保というような形で、住み続けていただきたい、あるいは訪れていただきたい、住んでみたいというふうに思っていただきたいというところで、そういう方々を増やしていきたいということで始めた事業です。","id":"exchange-157"},{"speaker":"須貝委員","kind":"意見","question":"今、人口減少に伴って、人を誘致したり、また、生き残れる自治体ということもあるのでしょう。観光事業をさまざまやったり、企業の誘致をしたりしております。もちろんその中には、人口だけではなくて、減少する税収に対しても何とか抑制しようという努力もあると視察に行って聞いております。その一方で、品川区は人口も税収も増えています。もう一度お聞かせ願いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"これから全国的なそういう流れの中で、そういうところも見据えた形で、ある程度、基盤といいますか、愛着を持ってこのまま住み続けていただきたいというような、そういう活動です。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"我々も地方、さまざまなところを視察しております。そのような状況にあるわけですから、今、課長がおっしゃったような、今後、心配だ、それはどこと比較して心配と言うのでしょうか。今この状況で２３区、ますます人口が増え続け、まして都心一極集中している状況ですから、人口や税収が増え続けている品川区にとっては、このシティプロモーションの役割は終わっているのではないでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"確かに定住人口も必要でしょうけれども、実際に訪れていただく、品川区のよさをもっと知っていただく、区外の方に知っていただく、魅力を発信していくというような形の動きはこれからも続けてまいりたいと思います。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"これだけ年々税収が増えて、人口も増え続けています。これは先ほど課長がおっしゃいました。その中において、この品川区は、事業費をかけて、そして人件費もかけてやる必要があるのですか。税収は増えて、人も増えて、増え続け過ぎているではないですか。ならば、シティプロモーション事業による他の地方自治体とのアピール競争も私はやめるべきだと思うのですが、それはどう思いますか。","respondent":"中山企画部長","answer":"課長の説明にもあったわけですけれども、まずは外に向けて品川の魅力を発信するという面がありますけれども、内外、これは品川の魅力を外にも発信するし、区民の方にしっかりと品川の魅力を伝え愛着を持っていただく。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"部長、十分魅力があるから来ているのではないですか。品川区に住んで、住宅もきちんと供給しています。魅力を発信しなくても来ているのではないですか。今の答弁はおかしくありませんか。それをしなくても人がなぜ集まるのか、先ほど言いましたが、２３区はこの場所がそもそも、交通網を含めて生活環境がいいわけです。それが、区民のためになるのですか。区民は何を望んでいるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問・要望","question":"区民のためになるのですか。その辺についてお聞かせいただきたいと思います。私は、これだけもう品川区は、立派なものを持っているのだから、地方自治体とのアピール競争はするべきではないと思うし、また、区民にとってどれだけ役立っているかということをもう一度教えてください。","respondent":"中山企画部長","answer":"そういうものの総合的な積み重ねが現在に至る品川の魅力につながり、転入増、あるいは定住率が高まっている、９割以上に方に住み続けたいと思っていただく、こういうものにつながっているわけですので、そういうものの延長線上にシティプロモーションはあると。","id":"exchange-162"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、まず６５ページの八潮北公園スケートボード場について、それと１１７ページ、地域自殺対策強化交付金についてお伺いします。初めに、八潮北公園スケートボード場ですが、まず、利用時間についてお伺いしたいのですが、小学生以下は１８歳以上のつき添いが必要というふうに明記されているのですけれども、時間帯が書いていないので、小・中学生の利用時間についてお知らせください。","respondent":"池田スポーツ推進課長、溝口公園課長","answer":"現在、教室につきましては、公園を運営している委託業者のほうでお願いしていますけれども、今後も定期的な教室を開催する予定ではありますけれども、この後どのような拡大をしていくかというところは。ただ、先行事例として、やはり企業としてＰＲが十分できるようなところについて導入しているというところがありますので、ネーミングライツについては、今後。","id":"exchange-163"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"利用時間なのですが、それはスケートボード場の利用時間であって、その利用時間帯は、中学生も夜９時まで保護者なしで使うことができるのかどうか、その辺を改めてお聞かせください。次に、地域自殺対策強化交付金についてですが、いわゆる自殺総合対策の中で、対策の大綱も昨年の７月ですか、閣議決定がされ、また、全ての都道府県および市町村に対して、対策の計画を策定するようにということになりました。","respondent":"池田スポーツ推進課長、溝口公園課長、舟木保健予防課長","answer":"ですので、ご提案いただいたキッチンカーということにつきましては、こちらのほうでは考えていないところです。そういった中でいきますと、やはりスケートボード場という特性をしっかり踏まえた中で、スポーツ用品店ですとか、またスケボーのショップですとか。教育との連携ですが、そちらは若年層への取り組みということで、ここ２年くらい強化しているところなのですが。","id":"exchange-164"},{"speaker":"石田（し）委員","kind":"提案","question":"たばこを吸う人はわかると思いますが、喫煙所に１人でいるときに、たばこを吸っているだけではなくて、いろいろ考えごともしたりしている中で、その時間帯は、その喫煙所の中を見渡したりもするので、そういったいわゆる人間が何かをするときの目線というところに注目していただいて、ぜひそういうところにそういった広報を、月間だけでも打っていただきたいというふうに思いますので、もう時間がないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-165"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８５ページの障害者自立支援給付費について伺いたいと思います。金子山のグループホームが開設しましたけれども、２０１６年１１月に行われた厚生委員会では、福栄会が得意とする重度知的障害、おおむね愛の手帳２度の方を中心に入れていきたい、かがやき園の入所の方の地域移行にもチャレンジしたいという報告でした。","respondent":"中山障害者福祉課長","answer":"その中では、ご本人の希望、ご家族の希望、それから、やはり今回、緊急対応というところもありましたので、ご家族の介護の状況、そして、グループホームになりますので、ご本人様の日中活動の状況、そういったものを総合的に勘案して入所の決定をしたところです。","id":"exchange-166"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中に地域移行の希望を、ぜひ区内、区外の入所者が今、２８１名ということで計画書にも書かれていますけれども、この方にもぜひ意向を確認して、区はグループホームに入りたいという希望がある人がどれくらいいるのかということをまずは把握していただきたいと思うのですけれども、その点についてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"この間、実施計画上では、民間活用型ということで、毎年２つ分のグループホームの建設の準備はしているところです。ただ、区が主導となって区立で建てるという計画は、現在、持ち合わせていないです。それから、区外の利用者の方への意向調査というところになります。","id":"exchange-167"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今も民間主導でということなのですけれども、私は、林試の森隣の荏原地域に、１つのグループホームも就労支援Ｂ型もないというところで、先日も厚生委員会でこのことが議論されたところですけれども、ぜひ荏原地域につくっていただきたい、これは行政需要ということであれば、最も高い行政需要の１つではないかと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長、柏原企画調整課長","answer":"計画相談の中では、中期目標、長期目標みたいなものも立ててまいりますので、丁寧に相談に乗る中で、今後の生活、在宅から例えばグループホームで自立した生活をしたいというようなところも聞き取っていけるように。これは行財政改革特別委員会でもご報告申し上げたところですが、こちらについては購入に向けて、今、調整をしているといったところで、使用の用途については、地域のにぎわい、それから防災の強化というところを軸にしながら。","id":"exchange-168"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ぜひ行政需要が最も強いというところで計画に入れてください。それから、今年の施政方針の中で、今度できる障害児者総合支援施設に対して、区長が、全国的にも類を見ない施設ということで言われたのですけれども、この全国的にも類を見ないというのは、どういう意味なのかについてお聞かせください。","respondent":"中山障害者福祉課長","answer":"併設される美術館ですとか、あるいはパフォーマンススタジオ、こうしたところを使いながら、地域にも広げていけるような、そんな施設になればと考えているところです。","id":"exchange-169"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川よりもかなり規模も大きいというところなのですけれども、そういう点では、私はここを１カ所だけにしないで、荏原地域からはあそこまで通うのはなかなか厳しいものがありますので、今度できる施設に加えて、私は、荏原第四中学校跡に、ぜひ第２の総合支援施設をつくっていただきたいと要望させていただきまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-170"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたときに、先ほど、居住支援協議会というお話もしましたけれども、都の住宅供給計画案も示されている中で、賃貸住宅の確保、供給、これについて、やはり各自治体も居住支援協議会を立ち上げ、こうしたことを検討していくことが大事であるというふうにもうたってありますけれども、その点はいかがお考えでしょうか。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃられる居住支援協議会につきましては、東京都の居住支援協議会にオブザーバーとして私どもも参加しています。他区の先駆的な動向を見極めながら、今後、検討してまいりたいと考えています。","id":"exchange-171"},{"speaker":"こんの委員","kind":"質問","question":"でも、町なかには、空き家、空き室がたくさんある。これが活用されていないというところで、私は、福祉の部分と住宅の部門とがやはり連携をしていかないと、このことはソフト面でやっていただく大変にありがたい制度だからこそ、それを生かすために供給する物件、そうしたことへの流れをつくるためにも、住宅課を中心とする居住支援協議会が必要であると考えますけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"ただ、個別に丁寧にお話をいろいろな主体の団体等も含めて話を伺う中で、困難な事例を解決しているというところも同時に伺っているところです。そういった機能を居住支援協議会も一定果たしているところは認識しております。","id":"exchange-172"},{"speaker":"こんの委員","kind":"質問","question":"そうしたことも活用できるでしょうということと同時に、品川区としては、新しい事業として、高齢者地域支援課でこうしたソフト面もしっかり立ち上がるわけですから、そこと連携をしたら、この国交省が出している補助金も使いながら、きちんと手当てができるのではないかと考えるからこそ、そのほかにも理由はありますけれども、居住支援協議会が必要であると、このように思っております。次に行きます。","respondent":"大関教育総合支援センター長","answer":"防犯カメラ等につきましては、警察等関係機関の要請には、柔軟に学校は即対応しておりますが、そのほか地域の方、あるいは警察署の方などをお呼びして防犯教室を子どもたちだけでなく、保護者も対象に開くなど、さまざまな形で検討を進めてまいりますので。","id":"exchange-173"},{"speaker":"こんの委員","kind":"質問","question":"今のご答弁のとおりだと思うのです。いろいろな人が入ってきます。そうしたことを考えたときに、その不審者、侵入してくる者を防御する体制にはなかなかない。そうしたことを考えたときに、学校の裁量で何か防犯対策を打ちたいといったときには、どういったことまでできるのでしょうか。","respondent":"大関教育総合支援センター長","answer":"現状におきましては、今、委員よりご指摘ございましたように、入り口での名札等の確認の徹底ですとか、ＰＴＡの協力も得ながら人を配置する等もしておりますが、さらに、例えばさすまた等をもう少し数を増やすですとか、そういった相談がありました際には。","id":"exchange-174"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、具体的なものが出ました。さすまた、これは、改良されたものが出ておりますので、もし学校裁量で購入ができるのであれば、それをぜひ支援をしてあげていただきたいと思います。教育委員会全体でそろえるというのは非常に難しいと思いますが、学校裁量でできるようお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-175"},{"speaker":"渡部委員","kind":"質問・要望","question":"１４０ページの東京臨海高速鉄道株式会社貸付金返還金に関連して、りんかい線について伺うのですが、済みません、数字を少し聞いていきますので、お答えできる範囲でお教えいただければ、確認を含めてですのでお願いいたします。ここ数年来、１億８,０００万円でしょうか、貸付金が戻っています。その都度、事前に定められた授権資本の中で増資をされていっているのか教えてほしい。","respondent":"中村都市計画課長","answer":"毎年利益に応じて増資も、これは利益追求の企業ですので、この辺は経営方針に従って、減資はなかったかと思いますが、増資が繰り返されているです。","id":"exchange-176"},{"speaker":"渡部委員","kind":"質問","question":"今の増資のところがちょっとわからなかったのですけれども、要は、平成２０年のところで１.７７％ですよね。だとしたら、品川区が今まで幾ら資本金を入れていて、増資のときには品川区も入れたのか、逆に、増資になることによって品川区のパーセンテージが下がってきたのか、その細かい金額は結構ですから、その辺の考え方を教えてください。","respondent":"中村都市計画課長","answer":"品川区といたしまして、この東京臨海高速鉄道株式会社にかかわっている部分といたしまして、貸付金と、それから持ち株分の比率に応じた金額です。資本にかかわるところは以上です。","id":"exchange-177"},{"speaker":"渡部委員","kind":"質問","question":"済みません、私の認識違いだったのか、貸付金の残金もこの資本の中に入っているということなのでしょうか。それ以上にりんかい線に対して、例えばＪＲから何かアプローチがあったのかとか、国土交通省とのやりとりがこの数年間で何かあったのか、あれば教えてほしい。この数年間の中でそういう動きがあるのかどうなのか、品川区は働きかけができるのかどうなのか教えてください。","respondent":"中村都市計画課長","answer":"ただ、この空港線につきましては、空港の動き、またＪＲ、それからりんかい線、さまざまな事業者が関連をしているところから、まだ実現というところの具体的な話には至っておりませんけれども、まず、りんかい線も将来的にそういった発展性については認識を持っているですので。","id":"exchange-178"},{"speaker":"渡部委員","kind":"提案","question":"ただ、この事業計画年度が２０３０年ですから、今の今という話では全くないと思うのですけれども、ぜひ品川区も株主にはなっておりますので、しかるべき時期に、そのようなことができるように、にぎわいづくりにもなりますので、ぜひぜひ進めていただきたいと、これは要望しますし、また、何年か後に質問が出てくるかもしれませんので、よろしくお願いいたします。","respondent":"柏原企画調整課長","answer":"そのやり方等については、関係部門とも共同して検討していきたいと思いますけれども、区全体、区民の皆様全ての課題として捉えていきたいというふうに思ってあります。","id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/314416?Template=document&Id=1074#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":120499,"voices":413}},{"id":"h30-20180306-10","meetingId":"h30-cm03","date":"2018年3月6日","dateIso":"2018-03-06","committee":"議会運営委員会","time":"午後 ５時５２分～午後 ６時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"お手元、資料５のとおりです。新たなところは、５のワークショップによる意見交換が「品川の魅力発見！」というところに決まりました。今までと変わりございません。既に会派を通じてご案内になっている日程かと思いますが、ここにはありませんけれども、４月２３日（月）午後１時半から第１委員会室で、全体リハーサルをやらせていただくことになっていますので、合わせてご報告します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100622?Template=document&Id=5266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3807,"voices":25}}]);
